const WGER_EXERCISES = [{"id":"wger-1962","wgerId":1962,"name":"Step Jack","muscle":"jambes","equipment":"none","desc":"Le Step Jack est un mouvement pliométrique à faible impact qui apporte des bénéfices cardiovasculaires sans le stress articulaire des sauts. Il sollicite l'ensemble du corps, en ciblant plus particulièrement les jambes, la sangle abdominale et les épaules. Ce mouvement est idéal pour les débutants, les personnes ayant des sensibilités articulaires, ou comme échauffement dynamique pour élever progressivement la fréquence cardiaque. Notes (Instructions) : 1. Tenez-vous droit, les pieds joints et les bras le long du corps. 2. Faites un pas sur le côté avec le pied droit tout en balançant simultanément les deux bras au-dessus de la tête. 3. Ramen","tips":["Tenez-vous droit, les pieds joints et les bras le long du corps","Faites un pas sur le côté avec le pied droit tout en balançant simultanément les deux bras au-dessus de la tête","Ramenez le pied droit au centre et abaissez les bras","Répétez immédiatement le mouvement en faisant un pas sur le côté avec le pied gauche","Continuez en alternant les côtés à un rythme régulier et soutenu"],"image":"https://wger.de/media/exercise-images/1962/74041371-1019-4f89-9ebe-cec792484a46.png.400x400_q85.png","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1963","wgerId":1963,"name":"Squat lent","muscle":"jambes","equipment":"none","desc":"Un squat basé sur le tempo qui utilise un mouvement contrôlé pour augmenter la tension musculaire et améliorer la stabilité du bas du corps. 1. Descente : Descendez lentement pendant 3 secondes. 2. Pause : Maintenez la position basse pendant 1 seconde. 3. Remontée : Revenez à la position de départ à un rythme normal. 4. Technique : Gardez la poitrine ouverte et le poids dans les talons.","tips":["Descente : Descendez lentement pendant","Pause : Maintenez la position basse pendant","Remontée : Revenez à la position de départ à un rythme normal","Technique : Gardez la poitrine ouverte et le poids dans les talons"],"image":"https://wger.de/media/exercise-images/1963/db285682-1ab3-4be0-ae00-5117ecce1ee6.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1964","wgerId":1964,"name":"Pompe prise large","muscle":"pectoraux","equipment":"none","desc":"Une variante de la pompe avec une position des mains plus large pour accentuer le travail des pectoraux externes et des épaules. 1. Installation : Placez les mains au sol, plus écartées que la largeur des épaules. 1. Descente : Descendez jusqu'à ce que la poitrine effleure presque le sol, en gardant la sangle abdominale gainée. 1. Poussée : Poussez à travers les paumes pour revenir à la position de départ. 1. Technique : Ne laissez pas le bas du dos s'affaisser ; conservez une ligne droite de la tête aux talons.","tips":["Installation : Placez les mains au sol, plus écartées que la largeur des épaules","Descente : Descendez jusqu'à ce que la poitrine effleure presque le sol, en gardant la sangle abdominale gainée","Poussée : Poussez à travers les paumes pour revenir à la position de départ","Technique : Ne laissez pas le bas du dos s'affaisser ; conservez une ligne droite de la tête aux talons"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1965","wgerId":1965,"name":"Montées de genoux sur place","muscle":"jambes","equipment":"none","desc":"Un exercice de cardio et de mobilité à faible impact qui renforce les fléchisseurs de la hanche et améliore l'équilibre. 1. Mouvement : Tenez-vous bien droit et levez un genou vers la poitrine, aussi haut que possible et confortablement. 1. Bras : Balancez le bras opposé vers l'avant à mesure que vous levez le genou, comme lors de la marche. 1. Gainage : Gardez les abdominaux engagés pour maintenir une posture droite. 1. Rythme : Effectuez le mouvement avec contrôle, en alternant les jambes de façon rythmée.","tips":["Mouvement : Tenez-vous bien droit et levez un genou vers la poitrine, aussi haut que possible et confortablement","Bras : Balancez le bras opposé vers l'avant à mesure que vous levez le genou, comme lors de la marche","Gainage : Gardez les abdominaux engagés pour maintenir une posture droite","Rythme : Effectuez le mouvement avec contrôle, en alternant les jambes de façon rythmée"],"image":"https://wger.de/media/exercise-images/1965/03c08a42-dedb-4a46-8d15-acaf497a35a2.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1966","wgerId":1966,"name":"Rotation thoracique à demi-genou","muscle":"jambes","equipment":"none","desc":"- Commencez en position de demi-genou, la jambe éloignée du mur étant stabilisée contre le mur à l'aide d'un ballon. - Les deux mains tendues directement devant vous, ouvrez un bras en rotation en cherchant à atteindre le mur derrière vous. - Expirez pendant la rotation, inspirez en revenant à la position neutre, puis répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1967","wgerId":1967,"name":"lento avanti seduto","muscle":"epaules","equipment":"elastiques","desc":"exercice lent en avant assis contrôlé avec haltères","tips":["exercice lent en avant assis contrôlé avec haltères"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1968","wgerId":1968,"name":"Développé épaules unilatéral à l'haltère","muscle":"epaules","equipment":"elastiques","desc":"Poussez l'haltère verticalement au-dessus de la tête dans un mouvement contrôlé jusqu'à ce que le bras soit complètement tendu, sans verrouiller le coude. Abaissez lentement l'haltère vers la position de départ, à hauteur d'épaule.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1968/cd92e973-a0d9-4e5f-9011-5369012598d3.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1970","wgerId":1970,"name":"Tirage haut sumo à la kettlebell","muscle":"dos","equipment":"elastiques","desc":"Un exercice polyarticulaire combinant des éléments du soulevé de terre sumo et du tirage haut. Il cible la chaîne postérieure, en particulier les fessiers, les ischio-jambiers et le haut du dos. La position sumo augmente l'engagement des hanches, tandis que le tirage haut ajoute une composante explosive qui favorise le développement de la puissance. * Tenez-vous droit au-dessus d'une kettlebell, les pieds plus écartés que la largeur des épaules et légèrement orientés vers l'extérieur. * Maintenez la sangle abdominale gainée et la colonne neutre tout au long de l'exercice. * Faites une charnière des hanches vers l'arrière et tendez les bras po","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1022","wgerId":1022,"name":"Single Arm Plank to Row","muscle":"epaules","equipment":"elastiques","desc":"Start position as row, extend to plank and back. Finish with row and repeat","tips":["Start position as row, extend to plank and back. Finish with row and repeat"],"image":"https://wger.de/media/exercise-images/1022/f74644fa-f43e-46bd-8603-6e3a2ee8ee2d.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-2447","wgerId":2447,"name":"Hip Airplane","muscle":"fessiers","equipment":"elastiques","desc":"Tenez-vous sur une jambe et inclinez légèrement le haut du corps vers l'avant tout en gardant le dos droit. Tendez la jambe libre derrière vous de sorte que le torse et la jambe forment à peu près une seule ligne. Ouvrez lentement la hanche sur le côté en faisant pivoter le bassin et le haut du corps de manière contrôlée. Refermez ensuite la hanche et revenez à la position de départ. Le mouvement doit provenir principalement de la hanche. Gardez le pied d'appui stable et évitez de laisser le genou s'affaisser vers l'intérieur.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-2452","wgerId":2452,"name":"Curl De Muñeca Con Barra","muscle":"jambes","equipment":"barre","desc":"This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. 1. Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders. 2. Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of ","tips":["Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders","Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it","Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor"],"image":"https://wger.de/media/exercise-images/2452/f6262118-1e01-4a98-b8aa-1cc69d383311.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-2454","wgerId":2454,"name":"YTW Raises","muscle":"epaules","equipment":"none","desc":"L'exercice YTW pour la rétraction scapulaire est conçu pour renforcer les muscles inter-scapulaires entre vos omoplates, pour vous aider à vous rétracter ou à tirer vos épaules vers l'arrière, ce qui vous aide à maintenir une bonne posture verticale.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-960","wgerId":960,"name":"Kettlebell Swing","muscle":"epaules","equipment":"elastiques","desc":"Bien que le kettlebell swing soit un exercice pour tout le corps, il cible principalement les muscles de la chaîne postérieure (l'arrière du corps). Les principaux muscles sollicités sont les fessiers, les ischio-jambiers, les érecteurs du rachis et les muscles du haut du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/960/da4d0560-da89-4bb5-b91f-746458fb04ad.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-977","wgerId":977,"name":"Box squat","muscle":"fessiers","equipment":"none","desc":"1. **Installez la box :** Placez la box derrière vous, à environ un mètre d'un rack à squat si vous utilisez une barre. Choisissez une hauteur qui vous permette de descendre en squat et d'effleurer doucement la box avec les fessiers, le dos droit. 2. **Adoptez une bonne posture :** Tenez-vous debout, les pieds écartés à la largeur des épaules, les pointes de pieds légèrement vers l'extérieur. Engagez la sangle abdominale et gardez le dos neutre. Si vous utilisez une barre, placez-la à hauteur d'épaule. 3. **Descendez :** Asseyez-vous vers l'arrière comme pour vous installer sur une chaise, en fléchissant les genoux et en abaissant les hanches","tips":["**Installez la box :** Placez la box derrière vous, à environ un mètre d'un rack à squat si vous utilisez une barre","**Descente contrôlée :** Descendez de manière contrôlée jusqu'à ce que les fessiers touchent doucement la box","**Pause et poussée :** Marquez brièvement une pause en position basse, le dos droit et la sangle abdominale gainée"],"image":"https://wger.de/media/exercise-images/977/3124c091-6395-4377-96c5-56048b627ceb.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-980","wgerId":980,"name":"Tractions commando","muscle":"epaules","equipment":"none","desc":"Variante de la traction, elle s'exécute avec une main en supination et une main en pronation. Ne tordez pas le torse pour revenir de face : la tête passe une fois d'un côté, une fois de l'autre.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-828","wgerId":828,"name":"Oiseau sur banc incliné","muscle":"epaules","equipment":"elastiques","desc":"L'oiseau à l'haltère sur banc incliné est un exercice du haut du corps qui cible les deltoïdes postérieurs (arrière de l'épaule), ainsi que les muscles posturaux du haut du dos. Comme il cible de si petits muscles, cet exercice se réalise généralement avec une charge légère et un nombre élevé de répétitions, par exemple 10 à 15 répétitions par série ou plus.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/828/2e959dab-f39b-4c7c-9063-eb43064ab5eb.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-112","wgerId":112,"name":"Body-Ups","muscle":"bras","equipment":"none","desc":"1. Placez-vous en position de planche au sol. Vous devez supporter le poids de votre corps sur les orteils et les avant-bras, en gardant le torse droit. Vos avant-bras doivent être écartés à la largeur des épaules. Ce sera votre position de départ. 2. En appuyant fermement les paumes contre le sol, tendez les coudes pour soulever votre corps du sol. Gardez le torse rigide pendant le mouvement. 3. Abaissez lentement les avant-bras vers le sol en laissant les coudes se fléchir. 4. Répétez autant de fois que nécessaire.","tips":["Placez-vous en position de planche au sol","En appuyant fermement les paumes contre le sol, tendez les coudes pour soulever votre corps du sol","Abaissez lentement les avant-bras vers le sol en laissant les coudes se fléchir","Répétez autant de fois que nécessaire"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-604","wgerId":604,"name":"Speed Deadlift","muscle":"jambes","equipment":"none","desc":"Deadlift avec un repos court (moins d'un 1min) entre les séries.","tips":["Deadlift avec un repos court (moins d'un 1min) entre les séries."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-821","wgerId":821,"name":"Pullup on fingerboard","muscle":"bras","equipment":"none","desc":"Pull-up sur un bord choisi d'une touche / hangboard","tips":["Pull-up sur un bord choisi d'une touche / hangboard"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-2478","wgerId":2478,"name":"Glute-Ham Raise","muscle":"jambes","equipment":"barre","desc":"Agenouillez-vous sur un développeur fessier ou demandez à un partenaire de vous tenir les chevilles. En gardant les hanches droites, abaissez votre torse vers le sol sous contrôle, puis retroussez-vous en contractant les ischio-jambiers et les fessiers.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-2480","wgerId":2480,"name":"Easy Continuous Swim (Freestyle)","muscle":"epaules","equipment":"none","desc":"Nagez en style libre à un rythme détendu et régulier sans vous arrêter — pensez au rythme de la conversation, pas à la course. Concentrez-vous sur des mouvements lisses et uniformes plutôt que sur la vitesse ou la technique de respiration ; c'est juste pour faire bouger votre corps et accélérer votre rythme cardiaque.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-923","wgerId":923,"name":"Lying Dumbbell Row SS Seated Shrug","muscle":"dos","equipment":"elastiques","desc":"couché sur le ventre sur un banc avec un léger angle","tips":["couché sur le ventre sur un banc avec un léger angle"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-958","wgerId":958,"name":"Biceps au TRX","muscle":"bras","equipment":"none","desc":"Saisissez les poignées des sangles TRX, inclinez le corps vers l'arrière, bras et jambes tendus, le corps aligné sur une seule ligne droite. (Il s'agit d'un exercice pour les bras, et non pour les abdominaux.)","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-959","wgerId":959,"name":"TRX Rows","muscle":"epaules","equipment":"none","desc":"Cet exercice sert de préparation aux Pull Ups.","tips":["Cet exercice sert de préparation aux Pull Ups."],"image":"https://wger.de/media/exercise-images/959/53a5e008-bc31-4ee0-9463-69a858c2ec18.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-927","wgerId":927,"name":"Suspended crossess","muscle":"pectoraux","equipment":"none","desc":"Exercice de suspension avec trx pour l'entraînement thoracique","tips":["Exercice de suspension avec trx pour l'entraînement thoracique"],"image":"https://wger.de/media/exercise-images/927/7b392101-9c47-4693-935e-a88b1887eec5.jpg.400x400_q85.jpg","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-983","wgerId":983,"name":"Genoux hauts","muscle":"jambes","equipment":"none","desc":"1. Courez sur place, en plaçant les genoux aussi haut que possible et en changeant de jambe à un rythme rapide","tips":["Courez sur place, en plaçant les genoux aussi haut que possible et en changeant de jambe à un rythme rapide"],"image":"https://wger.de/media/exercise-images/983/16245344-9957-4a24-8d61-f9939ed5f964.png.400x400_q85.png","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-993","wgerId":993,"name":"Corde à sauter : sauts de base","muscle":"jambes","equipment":"none","desc":"Cet exercice nécessite une corde à sauter. Assurez-vous que la longueur de la corde est adaptée à votre taille. Une mamière de vérifier est de saisir les deux poignées d'une main et de se tenir au milieu de la corde suspendue au sol avec un pied. Si la corde (sans les poignées) arrive juste sous votre poitrine, sa longueur est correcte. Une corde plus courte serait dangereuse, car vous risqueriez de vous cogner, et une corde plus longue serait mauvaise pour la forme. 1. Rapprochez vos pieds, pliez un peu les genoux, gardez la tête et le corps droits, gardez les coudes rentrés, ouvrez les bras. 2. Faites tourner uniquement vos poignets avec su","tips":["Faites tourner uniquement vos poignets avec suffisamment de force pour faire tourner la corde","Sautez juste assez haut pour faire passer la corde sous vos pieds","Répétez à partir de l'étape"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-996","wgerId":996,"name":"Escaladeurs de montagne","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez par la position debout des pompes ou de la planche haute.Les mains doivent se trouver directement sous vos épaules.Gardez la tête dans le prolongement du dos, face au sol.Les pieds doivent être écartés d'environ la largeur des hanches. Étapes : 1. Déplacez un genou vers le centre de votre corps, vers vos coudes, en gardant l'autre jambe tendue. 2. Dans un mouvement de saut rapide, redressez la jambe pliée et tirez l'autre genou vers votre corps. 3. Répétez l'étape 2 en alternant les jambes. Remarques : Tout au long de l'exercice, votre dos doit rester aussi droit que possible – évitez d'avoir une bosse ou un dos","tips":["Déplacez un genou vers le centre de votre corps, vers vos coudes, en gardant l'autre jambe tendue","Dans un mouvement de saut rapide, redressez la jambe pliée et tirez l'autre genou vers votre corps","Répétez l'étape"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-997","wgerId":997,"name":"Burpees (4 phases)","muscle":"jambes","equipment":"none","desc":"Position de départ : Tenez-vous droit, les pieds écartés de la largeur des hanches. Étapes : 1. Accroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit. 2. En gardant les mains sur le sol, sautez vos jambes vers l'arrière en position de planche haute. 3. Sautez vers l'avant pour revenir à la position de squat. 4. Répétez l'exercice.","tips":["Accroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit","En gardant les mains sur le sol, sautez vos jambes vers l'arrière en position de planche haute","Sautez vers l'avant pour revenir à la position de squat","Répétez l'exercice"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-981","wgerId":981,"name":"Marches","muscle":"fessiers","equipment":"barre","desc":"1. Tenez-vous debout face à une chaise 2. Montez sur la chaise 3. Descendez de la chaise 4. Répétez","tips":["Tenez-vous debout face à une chaise","Montez sur la chaise","Descendez de la chaise"],"image":"https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-985","wgerId":985,"name":"Pompes avec rotation","muscle":"pectoraux","equipment":"none","desc":"1. Faites une pompe standard : 1.a Allongez-vous sur le ventre1.b Placez vos mains près de vos oreilles1.c Utilisez vos bras pour soulever votre ventre jusqu'à ce que les bras soient droits, en gardant le dos droit1.d Pliez les bras jusqu'à ce que la poitrine touche presque le sol, en vous assurant que le dos est droit1.e Soulevez à nouveau votre ventre et revenez à l'étape 1.c 2. Faites pivoter votre corps sur le côté pour que le dos soit droit, que la main inférieure soutenant le corps soit complètement étendue et que seuls la main et le pied inférieurs touchent le sol 3. Répétez, en changeant de côté à chaque fois","tips":["Faites une pompe standard :","Répétez, en changeant de côté à chaque fois"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-990","wgerId":990,"name":"Extensions de la hanche","muscle":"fessiers","equipment":"none","desc":"1. Mettez-vous à quatre pattes 2. Poussez un pied en arrière jusqu'à ce qu'il soit complètement étendu, en vous concentrant sur les muscles fessiers 3. Restez une seconde, puis revenez à la position initiale 4. Répétez, en alternant les pieds","tips":["Mettez-vous à quatre pattes","Poussez un pied en arrière jusqu'à ce qu'il soit complètement étendu, en vous concentrant sur les muscles fessiers","Restez une seconde, puis revenez à la position initiale","Répétez, en alternant les pieds"],"image":"https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-805","wgerId":805,"name":"Extension triceps à la poulie","muscle":"bras","equipment":"none","desc":"L'extension triceps à la corde à la poulie est un exercice populaire qui cible les triceps. Il est facile à apprendre et à exécuter, ce qui en fait un favori aussi bien des débutants que des pratiquants confirmés. Il se réalise généralement sur un nombre modéré à élevé de répétitions, par exemple 8 à 12 répétitions ou plus par série, dans le cadre d'un entraînement du haut du corps ou axé sur les bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/805/7a437824-e2cc-46e1-804a-674f0ea31d25.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-912","wgerId":912,"name":"Straight Bar Cable Curls","muscle":"bras","equipment":"none","desc":"Debout devant la tour de câble à l'aide d'une barre droite","tips":["Debout devant la tour de câble à l'aide d'une barre droite"],"image":"https://wger.de/media/exercise-images/912/e10a034f-6370-4dd6-b1c2-416b27844529.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1971","wgerId":1971,"name":"Tirage Mentzer","muscle":"bras","equipment":"none","desc":"Tirage vertical face à la machine en prise serrée, en mettant l'accent sur les biceps. Augmente l'activation des biceps sur toute l'amplitude. Évitez de solliciter le grand dorsal.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1971/729af526-19a0-4d3d-a258-196c7575d139.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-31","wgerId":31,"name":"Axe Hold","muscle":"jambes","equipment":"elastiques","desc":"Prenez des haltères et tendez les bras sur le côté et maintenez-les aussi longtemps que vous le pouvez","tips":["Prenez des haltères et tendez les bras sur le côté et maintenez-les aussi longtemps que vous le pouvez"],"image":"https://wger.de/media/exercise-images/31/92f6451b-f89d-49d6-9531-8970ea420d97.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1972","wgerId":1972,"name":"Tirage vertical à un bras","muscle":"dos","equipment":"none","desc":"Asseyez-vous à la machine de tirage vertical et saisissez la poignée individuelle en prise neutre. Gardez le torse stable, la poitrine ouverte et les omoplates légèrement rétractées. Commencez bras complètement tendu au-dessus de la tête, puis tirez la poignée vers le haut de la poitrine en suivant une trajectoire contrôlée et légèrement diagonale. Concentrez-vous sur l'engagement du grand dorsal tout en gardant l'épaule basse et en évitant toute rotation du torse. Revenez lentement à la position de départ, en gardant le contrôle tout au long du mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-820","wgerId":820,"name":"Fingerboard 20 mm edge","muscle":"jambes","equipment":"none","desc":"Accrocher pendant 10 secondes sur une touche avec un bord de 20 mm","tips":["Accrocher pendant 10 secondes sur une touche avec un bord de 20 mm"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-908","wgerId":908,"name":"Zone 2 Running","muscle":"jambes","equipment":"none","desc":"Zone deux Cardio pour l'endurance, vous devriez être capable de parler tout en courant","tips":["Zone deux Cardio pour l'endurance, vous devriez être capable de parler tout en courant"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-961","wgerId":961,"name":"Swimming 50m sprints","muscle":"jambes","equipment":"none","desc":"50m sprints natation à 1min","tips":["50m sprints natation à 1min"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-57","wgerId":57,"name":"Marche de l'ours 2","muscle":"epaules","equipment":"none","desc":"-Répartissez votre poids sur les paumes et la plante des pieds, à la manière d'une position de pompe classique. -Déplacez-vous en avançant la paume droite et le pied gauche, puis la paume gauche et le pied droit. En gros, marchez comme un ours pesant. -Déplacez-vous aussi vite que possible. Mesurez vos répétitions/séries en distance (par exemple 40 mètres) ou en temps (par exemple 45 secondes). -Sollicite les pectoraux, les deltoïdes, les triceps, les trapèzes, le grand dorsal, les abdominaux et le bas du dos, les fléchisseurs de la hanche, les quadriceps, les fessiers et les mollets.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-975","wgerId":975,"name":"Curls à une main à la kettlebell","muscle":"bras","equipment":"elastiques","desc":"Debout, la kettlebell dans une main et le coude fléchi, partez d'une position complètement tendue jusqu'à ce que la main atteigne la hauteur de l'épaule. Pour exécuter le mouvement correctement, essayez de ne pas pousser avec le dos ni avec le corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/975/41d9267a-99bc-4e94-b1c4-0e39fe7a968f.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-976","wgerId":976,"name":"Medicine ball booklet crunch","muscle":"abdos","equipment":"none","desc":"L'utilisation d'une balle médicinale comme surcharge alourdira l'exercice.","tips":["L'utilisation d'une balle médicinale comme surcharge alourdira l'exercice."],"image":"https://wger.de/media/exercise-images/976/94649ea6-bf58-4fd9-90c1-b2ec96ee20cd.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-978","wgerId":978,"name":"Knee Raises","muscle":"abdos","equipment":"none","desc":"Le relèvement des jambes à 90 ° sur la barre est un exercice très intense qui implique tous les muscles abdominaux.","tips":["Le relèvement des jambes à 90 ° sur la barre est un exercice très intense qui implique tous les muscles abdominaux."],"image":"https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-804","wgerId":804,"name":"Sloper hanging","muscle":"jambes","equipment":"none","desc":"Accroché à des prises de sloper d'une touche pendant un certain nombre de secondes","tips":["Accroché à des prises de sloper d'une touche pendant un certain nombre de secondes"],"image":"https://wger.de/media/exercise-images/804/6f4b8bd9-fa05-49de-870b-1f79b595ce89.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-41","wgerId":41,"name":"Rollout abdominal à la barre","muscle":"abdos","equipment":"barre","desc":"Placez une barre au sol, à vos pieds. En vous penchant à partir de la taille, saisissez la barre en prise pronation à la largeur des épaules. Dans un mouvement lent et contrôlé, faites rouler la barre vers l'avant jusqu'à ce que votre dos soit droit. Faites rouler la barre en arrière en relevant les hanches et les fessiers pour revenir à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/41/34b37423-269f-43d4-9d29-d2a90eeaa6b4.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-962","wgerId":962,"name":"Vélo elliptique","muscle":"fessiers","equipment":"none","desc":"Il améliore la tonification musculaire, renforce les muscles des jambes (quadriceps, fessiers, mollets), favorise la vascularisation et augmente l'endurance. Le vélo elliptique est également très utile si vous cherchez à perdre du poids.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-909","wgerId":909,"name":"Reverse Nordic Curl","muscle":"jambes","equipment":"none","desc":"L'extension naturelle des jambes est une alternative à la machine d'extension des jambes sans équipement.","tips":["L'extension naturelle des jambes est une alternative à la machine d'extension des jambes sans équipement."],"image":"https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-979","wgerId":979,"name":"Leg raises pull up bar","muscle":"abdos","equipment":"none","desc":"avec une prise ferme avec les deux mains sur la barre, levez vos jambes tendues, jusqu'à ce que vous atteigniez un angle de 90 ° avec votre torse.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/979/27097a3a-5749-428d-b94c-6082afe390f6.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-79","wgerId":79,"name":"Tirages hauts buste penché","muscle":"dos","equipment":"elastiques","desc":"Penchez-vous légèrement vers l'avant en tenant deux haltères. Tirez les haltères vers la poitrine en gardant les coudes aussi hauts que possible.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/79/da58dfbf-748a-461b-891e-3d6bc9cc4be2.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-2448","wgerId":2448,"name":"Clamshell inversé","muscle":"fessiers","equipment":"none","desc":"Allongez-vous sur le côté, les hanches et les genoux fléchis, en gardant les genoux superposés l'un sur l'autre. Gardez d'abord les pieds joints, puis, tout en gardant les genoux en contact, levez le pied supérieur vers le haut. Abaissez lentement le pied en gardant le contrôle. Le mouvement doit se faire uniquement au niveau de la hanche ; évitez de basculer le bassin vers l'arrière. Le mouvement doit rester petit, contrôlé et centré sur la rotation de la hanche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-178","wgerId":178,"name":"Deadbug","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur le dos, les hanches et les genoux fléchis à 90°. Levez les deux bras vers le plafond. Plaquez le bas de votre dos contre le sol pour supprimer tout espace. Commencez en tendant une jambe et en touchant le sol avec le talon. À mesure que vous tendez une jambe, expirez autant que possible en gardant le bas du dos collé au sol. Lorsque vous ne pouvez plus expirer, ramenez votre genou vers la position de départ. Rendez l'exercice plus difficile en tenant un poids dans les mains, ou en abaissant simultanément le bras et la jambe opposés.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-292","wgerId":292,"name":"Pont fessier au sol","muscle":"fessiers","equipment":"none","desc":"Allongé sur le dos, les pieds bien à plat sur le sol. Soulevez les hanches de façon régulière aussi haut que possible et maintenez la position aussi longtemps que vous le pouvez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-802","wgerId":802,"name":"Barbell Lunges Walking","muscle":"fessiers","equipment":"barre","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-984","wgerId":984,"name":"Fentes","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous debout, le dos droit 2. Faites un grand pas en avant avec votre jambe gauche 3. Descendez votre bassin jusqu'à ce que votre genou droit touche presque le sol. 4. Remontez votre bassin 5. Revenez à la position debout en faisant un pas en arrière 6. Répétez l'opération en changeant de jambe à chaque fois","tips":["Tenez-vous debout, le dos droit","Faites un grand pas en avant avec votre jambe gauche","Descendez votre bassin jusqu'à ce que votre genou droit touche presque le sol","Remontez votre bassin","Revenez à la position debout en faisant un pas en arrière"],"image":"https://wger.de/media/exercise-images/984/5c7ffe68-e7b2-47f3-a22a-f9cc28640432.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-2481","wgerId":2481,"name":"Kick with Board","muscle":"fessiers","equipment":"none","desc":"Tenez une planche avec les deux mains, les bras étendus devant vous, le visage dans l'eau (soulevez la tête vers l'avant pour respirer en cas de besoin). Coup de pied de vos hanches, pas de vos genoux, en gardant vos jambes principalement droites avec une légère flexion et un coup de pied stable et compact. Cela renforce l'endurance des jambes et maintient votre corps horizontal sans avoir à vous soucier de vos bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-297","wgerId":297,"name":"Hollow hold","muscle":"abdos","equipment":"none","desc":"Installez-vous sur un tapis et allongez-vous sur le dos. Contractez les abdominaux, tendez les bras et les jambes et levez-les (votre tête et vos épaules sont également relevées). Veillez à ce que le bas de votre dos reste en contact avec le tapis.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1630","wgerId":1630,"name":"Blaze","muscle":"epaules","equipment":"barre","desc":"BLAZE est un entraînement HIIT pour tout le corps, conçu pour dynamiser votre condition cardiovasculaire et votre force. Dispensé dans un studio spécialement aménagé, BLAZE est un mélange unique d'arts martiaux, de cardio intense et de renforcement musculaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-208","wgerId":208,"name":"Dumbbells on Scott Machine","muscle":"bras","equipment":"elastiques","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-152","wgerId":152,"name":"Traction en supination","muscle":"bras","equipment":"none","desc":"La traction en supination est un exercice de musculation. On le pratique fréquemment dans le but de renforcer des muscles comme le grand dorsal et les biceps, qui assurent respectivement l'extension de l'épaule et la flexion du coude. Dans ce mouvement, les paumes sont tournées vers le corps. Il s'agit d'une forme de traction dont l'amplitude de mouvement est définie par rapport au menton de la personne.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/152/6c1a7459-266d-491a-bd50-7cbaea2bc771.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-998","wgerId":998,"name":"Burpees sans saut","muscle":"jambes","equipment":"none","desc":"Position de départ : Se tenir droit, les pieds écartés de la largeur des hanches. Étapes: 1. Accroupissez-vous et appuyez-vous sur le sol avec vos mains entre les genoux et devant vos pieds, le dos droit. 2. En gardant les mains au sol, donnez une impulsion pour envoyer vos jambes vers l'arrière en position de planche haute. 3. Donnez une nouvelle impulsion pour revenir à la position accroupie. 4. Sautez. 5. Répétez.","tips":["Accroupissez-vous et appuyez-vous sur le sol avec vos mains entre les genoux et devant vos pieds, le dos droit","En gardant les mains au sol, donnez une impulsion pour envoyer vos jambes vers l'arrière en position de planche haute","Donnez une nouvelle impulsion pour revenir à la position accroupie"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-988","wgerId":988,"name":"Squats bulgares gauches","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous droit devant une chaise et faites un grand pas. Placez la partie supérieure de l'un de vos pieds sur la chaise 2. Pliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol 3. Revenez à la position de départ et répétez.","tips":["Tenez-vous droit devant une chaise et faites un grand pas","Pliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol","Revenez à la position de départ et répétez"],"image":"https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-989","wgerId":989,"name":"Squats bulgares droites","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous droit devant une chaise et faites un grand pas. Placez la partie supérieure de l'un de vos pieds sur la chaise 2. Pliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol 3. Revenez à la position de départ et répétez.","tips":["Tenez-vous droit devant une chaise et faites un grand pas","Pliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol","Revenez à la position de départ et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-991","wgerId":991,"name":"Fentes avant gauches","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous debout avec le dos droit 2. Faites un grand pas en avant avec votre jambe gauche 3. Abaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou droit 4. Ramenez votre bassin vers le haut 5. Répétez à partir de l'étape 3.","tips":["Tenez-vous debout avec le dos droit","Faites un grand pas en avant avec votre jambe gauche","Abaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou droit","Ramenez votre bassin vers le haut","Répétez à partir de l'étape"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-992","wgerId":992,"name":"Fentes avant droites","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous debout avec le dos droit 2. Faites un grand pas en avant avec votre jambe droite 3. Abaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou gauche 4. Ramenez votre bassin vers le haut 5. Répétez à partir de l'étape 3.","tips":["Tenez-vous debout avec le dos droit","Faites un grand pas en avant avec votre jambe droite","Abaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou gauche","Ramenez votre bassin vers le haut","Répétez à partir de l'étape"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-999","wgerId":999,"name":"Fentes arrière","muscle":"fessiers","equipment":"none","desc":"Position de départ : Tenez-vous droit, les pieds écartés à la largeur des hanches. Étapes : 1. Faites un pas en arrière avec une jambe afin qu'elle puisse se fléchir confortablement à un angle de 90 degrés. 2. Fléchissez lentement les deux genoux pour former des angles de 90 degrés. 3. Revenez à la position de départ. 4. Répétez en alternant les jambes.","tips":["Faites un pas en arrière avec une jambe afin qu'elle puisse se fléchir confortablement à un angle de","Fléchissez lentement les deux genoux pour former des angles de","Revenez à la position de départ","Répétez en alternant les jambes"],"image":"https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1000","wgerId":1000,"name":"Dips au sol","muscle":"bras","equipment":"none","desc":"Position de départ : Asseyez-vous, les bras derrière vous pour soutenir le dos. Vos doigts doivent pointer vers l'avant. Vos genoux doivent être fléchis, les pieds joints. Étapes : 1. Soulevez les hanches du sol en tendant les bras. 2. Fléchissez les coudes en abaissant les hanches. 3. Tendez les bras pour revenir à la position précédente. 4. Répétez les étapes 2 et 3. Notes : La difficulté de l'exercice dépend de la hauteur à laquelle vous montez les hanches.","tips":["Soulevez les hanches du sol en tendant les bras","Fléchissez les coudes en abaissant les hanches","Tendez les bras pour revenir à la position précédente","Répétez les étapes","Notes : La difficulté de l'exercice dépend de la hauteur à laquelle vous montez les hanches"],"image":"https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1001","wgerId":1001,"name":"Planche haute","muscle":"abdos","equipment":"none","desc":"Starting position: Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight. Steps: 1. Maintain the starting position for the entire duration of the exercise.","tips":["Maintain the starting position for the entire duration of the exercise"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1002","wgerId":1002,"name":"Position de l'enfant","muscle":"jambes","equipment":"none","desc":"Starting position: Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching. Steps: 1. Move your knees so that they're about hip-width apart. 2. On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground. 3. Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally. 4. Stay in this pose. Tips: * To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.","tips":["Move your knees so that they're about hip-width apart","On an exhale, move your pelvis back to sit on your heels","Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally","Stay in this pose"],"image":"https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1006","wgerId":1006,"name":"Rentré de menton","muscle":"jambes","equipment":"none","desc":"Position de départ : Asseyez-vous ou tenez-vous debout, le dos droit. Étapes : 1. À l'aide des doigts posés sur le menton, rentrez lentement le menton en ramenant la tête vers l'arrière pour l'aligner avec la colonne vertébrale. 2. Maintenez pendant 5 secondes. 3. Revenez à la position normale de la tête et répétez.","tips":["Maintenez pendant","Revenez à la position normale de la tête et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1007","wgerId":1007,"name":"Tour de tête","muscle":"jambes","equipment":"none","desc":"Position de départ : Asseyez-vous ou tenez-vous debout, le dos droit et les épaules basses. Étapes : 1. Asseyez-vous ou tenez-vous debout, le dos droit. Épaules baissées. 2. Tournez la tête vers la gauche aussi loin que possible. Arrêtez-vous lorsque vous rencontrez un obstacle et maintenez cette position pendant 5 secondes. 3. Revenez à la position centrale. 4. Répétez en changeant de côté.","tips":["Asseyez-vous ou tenez-vous debout, le dos droit","Tournez la tête vers la gauche aussi loin que possible","Revenez à la position centrale","Répétez en changeant de côté"],"image":"https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1010","wgerId":1010,"name":"Flexion du cou","muscle":"jambes","equipment":"none","desc":"Starting position: Sit upright on a chair or a firm pillow. Steps: 1. Breathe out and tilt your head forward, chin to chest, putting hands behind your head. 2. Use your hands to pull your head down lightly and press against your hands with your head to balance out the force. 3. Hold for a bit. 4. Relax your arms and head, opening up a bit with your shoulders. 5. Keep repeating this from step 2 onward.","tips":["Breathe out and tilt your head forward, chin to chest, putting hands behind your head","Use your hands to pull your head down lightly and press against your hands with your head to balance out the force","Hold for a bit","Relax your arms and head, opening up a bit with your shoulders","Keep repeating this from step"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-222","wgerId":222,"name":"Tirage à la face (Face pull)","muscle":"dos","equipment":"none","desc":"Fixez une corde à une poulie réglée environ à hauteur de poitrine. Reculez de manière à soutenir la charge bras complètement tendus, et adoptez une position décalée (un pied en avant). Fléchissez légèrement les genoux pour une base stable. Rétractez les omoplates (serrez-les comme pour pincer un doigt entre elles) et tirez le centre de la corde légèrement vers le haut, en direction du visage. Un bon repère consiste à penser à écarter les extrémités de la corde, et non simplement à tirer vers l'arrière. À l'approche de votre visage, effectuez une rotation externe de manière à ce que vos articulations des doigts soient tournées vers le plafond.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1018","wgerId":1018,"name":"Inclinaisons de la tête","muscle":"jambes","equipment":"none","desc":"Position de départ : Asseyez-vous ou tenez-vous debout, le dos droit. Étapes : 1. Inclinez la tête d'un côté et maintenez un instant. 2. Ramenez la tête en position neutre et maintenez un instant. 3. Inclinez la tête de l'autre côté et maintenez un instant. 4. Ramenez à nouveau la tête en position neutre et maintenez un instant. 5. Répétez.","tips":["Inclinez la tête d'un côté et maintenez un instant","Ramenez la tête en position neutre et maintenez un instant","Inclinez la tête de l'autre côté et maintenez un instant","Ramenez à nouveau la tête en position neutre et maintenez un instant"],"image":"https://wger.de/media/exercise-images/1018/5bbd3879-b6fc-4aaa-9e8e-33ae9a688112.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-986","wgerId":986,"name":"Fentes latérales gauches","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules 2. Pliez un genou jusqu'à ce que votre cuisse soit parallèle au sol. Le genou plié doit être aligné avec le pied 3. Revenez à la position de départ et répétez.","tips":["Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules","Pliez un genou jusqu'à ce que votre cuisse soit parallèle au sol","Revenez à la position de départ et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-987","wgerId":987,"name":"Fentes latérales droites","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules 2. Pliez un genou jusqu'à ce que votre cuisse soit parallèle au sol. Le genou plié doit être aligné avec le pied 3. Revenez à la position de départ et répétez.","tips":["Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules","Pliez un genou jusqu'à ce que votre cuisse soit parallèle au sol","Revenez à la position de départ et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-994","wgerId":994,"name":"Cercles avant des bras","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous debout, le dos bien droit. 2. Gardez vos bras droits, amenez les devant vous, puis vers le bas, puis derrière votre dos, puis au dessus de votre tête, puis ramenez les en position initiale, devant vous. 3. Continuez à faire des cercles avec vos bras comme décrit à l'étape 2.","tips":["Tenez-vous debout, le dos bien droit","Continuez à faire des cercles avec vos bras comme décrit à l'étape"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-995","wgerId":995,"name":"Cercle arrière des bras","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous debout, le dos droit. 2. Gardez vos bras tendus, amenez-les devant vous, levez-les au-dessus de votre tête, puis continuez le mouvement derrière votre dos jusqu'à revenir en position initiale. 3. Continuez à faire des cercles comme décrit à l'étape 2.","tips":["Tenez-vous debout, le dos droit","Continuez à faire des cercles comme décrit à l'étape"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1004","wgerId":1004,"name":"Rotation de l'épaule vers l'avant","muscle":"jambes","equipment":"none","desc":"Starting position: Sit or stand with your back straight. Steps: 1. Place your hands on your shoulders. 2. Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.","tips":["Place your hands on your shoulders","Repeatedly rotate both shoulder joints in a circular motion at a moderate pace"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1005","wgerId":1005,"name":"Rotation de l'épaule vers l'arrière","muscle":"jambes","equipment":"none","desc":"Starting position: Sit or stand with your back straight. Steps: 1. Place your hands on your shoulders. 2. Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.","tips":["Place your hands on your shoulders","Repeatedly rotate both shoulder joints in a circular motion at a moderate pace"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1008","wgerId":1008,"name":"Étirement du cou à gauche","muscle":"jambes","equipment":"none","desc":"Starting position: Sit or stand with your back straight. Steps: 1. Tilt your head to the side. 2. Take the hand closer to your head and use it to grab your head from the other side. 3. Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still. 4. Maintain this tension until the end of the exercise.","tips":["Tilt your head to the side","Take the hand closer to your head and use it to grab your head from the other side","Maintain this tension until the end of the exercise"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1009","wgerId":1009,"name":"Étirement du cou à droite","muscle":"jambes","equipment":"none","desc":"Starting position: Sit or stand with your back straight. Steps: 1. Tilt your head to the side. 2. Take the hand closer to your head and use it to grab your head from the other side. 3. Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still. 4. Maintain this tension until the end of the exercise.","tips":["Tilt your head to the side","Take the hand closer to your head and use it to grab your head from the other side","Maintain this tension until the end of the exercise"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1013","wgerId":1013,"name":"Étirement de l'angulaire de l'omoplate gauche","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez debout ou assis. Tournez la tête vers la gauche, d'environ 45 degrés ou juste au-dessus du mamelon. Placez la main droite dans le dos ou asseyez-vous dessus. Avec la main gauche, tenez l'arrière de votre tête. Penchez légèrement la tête vers le bas. Étapes : 1. Une fois la position de départ adoptée, appuyez la tête contre la main gauche avec une légère force. Votre main doit résister avec une force égale, de sorte que la tête ne bouge pas. Maintenez cette position.","tips":["Une fois la position de départ adoptée, appuyez la tête contre la main gauche avec une légère force"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1014","wgerId":1014,"name":"Étirement de l'angulaire de l'omoplate droit","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez debout ou assis. Tournez la tête vers la droite, d'environ 45 degrés ou juste au-dessus du mamelon. Placez la main gauche dans le dos ou asseyez-vous dessus. Avec la main droite, tenez l'arrière de votre tête. Penchez légèrement la tête vers le bas. Étapes : 1. Une fois la position de départ adoptée, appuyez la tête contre la main droite avec une légère force. Votre main doit résister avec une force égale, de sorte que la tête ne bouge pas. Maintenez cette position.","tips":["Une fois la position de départ adoptée, appuyez la tête contre la main droite avec une légère force"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1003","wgerId":1003,"name":"Haltères de kettlebell","muscle":"jambes","equipment":"elastiques","desc":"Starting position: Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward. Steps: 1. Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement. 2. Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart. 3. While contacting your abs and glutes, stand straight up. 4. Hinge at the hips again to bring the kettlebell back down, similarly to step 1. 5. Repeat from step 3. Tips: * Be sure you're performing the movements correctly, as ","tips":["Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles","Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart","While contacting your abs and glutes, stand straight up","Hinge at the hips again to bring the kettlebell back down, similarly to step","Repeat from step"],"image":"https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1012","wgerId":1012,"name":"Curls biceps alternés","muscle":"bras","equipment":"elastiques","desc":"Position de départ : Commencez debout, un haltère dans chaque main, le dos droit et les pieds écartés à la largeur des hanches. Vos bras doivent être détendus et pointer vers le bas. Vos genoux doivent être légèrement fléchis, les abdominaux contractés et les épaules basses. Étapes : 1. Fléchissez un bras au niveau du coude en ramenant l'haltère vers l'épaule. Le haut de votre bras doit rester immobile pendant ce mouvement. 2. Abaissez l'haltère jusqu'à ce que le bras retrouve sa position détendue de départ. 3. Répétez en changeant de bras.","tips":["Fléchissez un bras au niveau du coude en ramenant l'haltère vers l'épaule","Abaissez l'haltère jusqu'à ce que le bras retrouve sa position détendue de départ","Répétez en changeant de bras"],"image":"https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-145","wgerId":145,"name":"Rotations du tronc à la poulie","muscle":"abdos","equipment":"none","desc":"Réglez la poulie à câble légèrement en dessous de la hauteur de la poitrine. Gardez le corps tourné vers l'avant et les hanches stables. Saisissez la poignée de la poulie, tendez complètement les bras et amenez-les vers l'avant en traversant votre corps. Maintenez la position pendant 1 seconde à la fin du mouvement, puis revenez lentement à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-284","wgerId":284,"name":"Hercules Pillars","muscle":"bras","equipment":"none","desc":"Saisissez deux câbles au milieu pour qu'ils soient tous les deux tendus et maintenus","tips":["Saisissez deux câbles au milieu pour qu'ils soient tous les deux tendus et maintenus"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-914","wgerId":914,"name":"Reverse EZ Bar Cable Curls","muscle":"bras","equipment":"none","desc":"Debout devant la tour de câble en utilisant un SZ Bar","tips":["Debout devant la tour de câble en utilisant un SZ Bar"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1969","wgerId":1969,"name":"Extension triceps unilatérale à la poulie","muscle":"bras","equipment":"none","desc":"L'extension triceps unilatérale à la poulie est un exercice d'isolation unilatéral qui cible le triceps brachial. En travaillant un bras à la fois, il aide à corriger les déséquilibres de force entre les côtés tout en sollicitant la sangle abdominale pour la stabilité. Position de départ : Tenez-vous face à la machine à poulie, les pieds écartés à la largeur des épaules. Fixez une poignée individuelle à la poulie haute. Saisissez la poignée d'une main en prise pronation, le coude fléchi à environ 90° et collé contre le corps. Gardez la sangle abdominale gainée et le dos droit. Exécution : Poussez la poignée vers le bas dans un mouvement contr","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-910","wgerId":910,"name":"Nordic Curl","muscle":"jambes","equipment":"none","desc":"Le Nordic curl (leg curl nordique) est l'un des meilleurs exercices pour le bas du corps afin de développer la force de la chaîne postérieure des jambes, d'améliorer la santé des genoux et de prévenir les blessures.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-913","wgerId":913,"name":"Reverse Preacher Curl (Close Grip)","muscle":"bras","equipment":"barre","desc":"Assis à l'envers sur un banc de biceps avec une prise serrée","tips":["Assis à l'envers sur un banc de biceps avec une prise serrée"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-925","wgerId":925,"name":"Développé incliné à la Smith machine","muscle":"pectoraux","equipment":"none","desc":"### * **Exécution** * **Position de départ :** * Déverrouillez la barre et tenez-la au-dessus du haut de votre poitrine, bras complètement tendus. * Gardez vos omoplates **rétractées et plaquées contre le banc**. * **Phase de descente (excentrique) :** * Abaissez lentement la barre jusqu'à juste en dessous de votre clavicule ou du haut de votre poitrine. * Gardez le contrôle, ne faites pas rebondir la barre. * **Phase de poussée (concentrique) :** * Poussez la barre vers le haut en ligne droite jusqu'à l'extension complète des bras. * Concentrez-vous sur la **contraction du haut de vos pectoraux** en haut du mouvement. * **Verrouillez et répé","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/925/67dbb1c9-b378-46f9-adb6-1f55b3d3007a.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-132","wgerId":132,"name":"Burpees avec pompes","muscle":"jambes","equipment":"none","desc":"Position de départ : Tenez-vous droit, les pieds écartés de la largeur des hanches. Étapes : 1. Accroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit. 2. En gardant les mains sur le sol, lancez vos jambes vers l'arrière en position de planche haute. 3. Effectuez une pompe. 4. Remettez vos pieds vers l'avant pour revenir à la position de squat. 5. Répétez.","tips":["Accroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit","En gardant les mains sur le sol, lancez vos jambes vers l'arrière en position de planche haute","Effectuez une pompe","Remettez vos pieds vers l'avant pour revenir à la position de squat"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-129","wgerId":129,"name":"Exercice de développé pectoral à la machine","muscle":"pectoraux","equipment":"none","desc":"Il offre un moyen efficace mais simple de travailler le haut du corps. Sans poids à équilibrer ni technique complexe à maîtriser, le développé pectoral vous laisse libre de vous concentrer sur votre entraînement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/129/b263c968-e067-4750-916a-d8758a7df23e.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-161","wgerId":161,"name":"Pullover avec haltère en travers du banc","muscle":"dos","equipment":"elastiques","desc":"Saisissez un haltère de poids modéré de manière à ce que vos paumes soient à plat contre la face inférieure des disques supérieurs et que vos pouces entourent la barre. Allongez-vous sur le dos en travers d'un banc plat, de sorte que seuls le haut de votre dos et vos épaules soient en contact avec le banc. Vos pieds doivent être écartés d'environ la largeur des épaules et votre tête doit pendre légèrement vers le bas. L'haltère étant tenu à bout de bras directement au-dessus de votre poitrine, fléchissez les bras d'environ 15 degrés et gardez-les fléchis pendant tout le mouvement. Abaissez lentement l'haltère vers l'arrière et vers le bas en ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/161/b9b1803e-2817-40bf-8ac7-e398ca86d8b4.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-182","wgerId":182,"name":"Deadhang","muscle":"jambes","equipment":"none","desc":"Deadhang effectué sur une arête avec ou sans poids supplémentaire (arête adujst ou poids pour ajuster la difficulté)","tips":["Deadhang effectué sur une arête avec ou sans poids supplémentaire (arête adujst ou poids pour ajuster la difficulté)"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-177","wgerId":177,"name":"Cyclisme","muscle":"abdos","equipment":"none","desc":"Le cyclisme, aussi appelé vélo, désigne l'utilisation de la bicyclette pour le transport, les loisirs, l'exercice ou le sport. Les personnes qui pratiquent le cyclisme sont appelées cyclistes. Outre les bicyclettes à deux roues, le cyclisme inclut également la pratique du monocycle, du tricycle, du quadricycle, du vélo couché et d'autres véhicules à propulsion humaine similaires.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-926","wgerId":926,"name":"Machine chest fly","muscle":"pectoraux","equipment":"none","desc":"machine assise, dos droit, exercice lent","tips":["machine assise, dos droit, exercice lent"],"image":"https://wger.de/media/exercise-images/926/ae9deb5d-a1e9-4c30-b1e3-c128ba5d4969.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-301","wgerId":301,"name":"Extensions lombaires (hyperextensions)","muscle":"dos","equipment":"none","desc":"Allongez-vous sur le coussin du banc à lombaires, le nombril au niveau du bord avant, en laissant le haut du corps pendre librement. Contractez tous les muscles de votre dos et relevez le buste jusqu'à l'horizontale, mais pas plus haut. Redescendez lentement, en maintenant une contraction musculaire régulière et continue.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/128/Hyperextensions-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-285","wgerId":285,"name":"Sauts genoux hauts","muscle":"jambes","equipment":"none","desc":"- Commencez avec les jambes légèrement plus écartées que la largeur des épaules - Descendez en squat au poids du corps - Arrivé au point bas du squat, propulsez-vous explosivement vers le haut en sautant tout en ramenant simultanément les genoux vers la poitrine en plein vol. Gardez les genoux ramenés jusqu'au sommet de votre saut. - Réceptionnez-vous sur les deux pieds, en veillant à ne pas verrouiller les genoux afin d'éviter une tension excessive sur vos articulations. Enchaînez sur la répétition suivante aussi rapidement que possible, mais toujours avec contrôle.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png.400x400_q85.png","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-915","wgerId":915,"name":"Bus Drivers","muscle":"epaules","equipment":"none","desc":"Assis avec une plaque de poids, utilisée comme roue, dans les deux mains ; levé légèrement en dessous du niveau des yeux","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/915/fe8ebece-dff8-4700-b84c-9110e2e074f5.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-279","wgerId":279,"name":"Hand Grip","muscle":"jambes","equipment":"none","desc":"poignée flexible chromée pour les mains pour renforcer les muscles de l'avant-bras","tips":["poignée flexible chromée pour les mains pour renforcer les muscles de l'avant-bras"],"image":"https://wger.de/media/exercise-images/279/36605bc8-d7e1-43e1-87c1-b9cb50db62b2.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-294","wgerId":294,"name":"Hip thrust","muscle":"fessiers","equipment":"barre","desc":"La barre doit reposer directement sur le haut de vos cuisses, juste en dessous de l'aine. Vos pieds doivent se trouver directement sous vos genoux. Poussez vos hanches vers le haut de manière à former une ligne droite de vos genoux jusqu'à vos épaules. Utilisez un coussin pour plus de confort.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-289","wgerId":289,"name":"Tirage haut (High pull)","muscle":"epaules","equipment":"none","desc":"Utilisez une barre légère et effectuez une tirée explosive en partant d'un niveau situé sous les rotules. Soulevez la barre de façon explosive en utilisant les hanches, jusqu'au niveau des épaules. Tempo : 2111","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-2449","wgerId":2449,"name":"Clamshell vers clamshell inversé","muscle":"fessiers","equipment":"none","desc":"Allongez-vous sur le côté, les hanches et les genoux fléchis, en gardant les jambes superposées. Levez le genou supérieur en position de clamshell et maintenez la jambe relevée pendant tout le mouvement. À partir de là, alternez entre l'ouverture du genou vers le haut et l'élévation du pied vers le haut, en passant par la rotation externe puis interne de la hanche. Gardez le mouvement lent et contrôlé. Ne laissez pas la jambe supérieure reposer sur la jambe inférieure entre les répétitions.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-2482","wgerId":2482,"name":"Bobbing Exhale Drill","muscle":"abdos","equipment":"none","desc":"Tenez-vous debout dans l'eau profonde de la poitrine. Prenez une respiration, immergez complètement votre visage et expirez lentement et complètement par le nez et/ou la bouche pendant tout le temps que vous êtes sous l'eau — un bourdonnement doux peut aider à garder l'expiration stable et contrôlée. Une fois que vous êtes vide d'air, levez la tête, respirez à nouveau et redescendez. Répétez continuellement. L'objectif est d'entraîner votre corps à ce que toutes vos expirations se produisent sous l'eau, donc tout ce que vous avez à faire à la surface est d'inhaler.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-423","wgerId":423,"name":"Muscle-up","muscle":"bras","equipment":"none","desc":"Le corps est ensuite tiré explosivement vers le haut par les bras dans une traction radiale, avec plus de vitesse qu'une traction classique. Lorsque la barre approche du haut de la poitrine, les poignets sont rapidement fléchis pour amener les avant-bras au-dessus de la barre. Le corps est penché vers l'avant et les coudes sont tendus en activant les triceps. Le mouvement est considéré comme terminé lorsque la barre est au niveau de la taille et que les bras sont complètement tendus. Pour redescendre, les bras sont fléchis au niveau du coude et le corps est ramené vers le sol ; l'exercice peut alors être répété. Comme il s'agit d'un exercice ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1019","wgerId":1019,"name":"Planche latérale droite","muscle":"abdos","equipment":"none","desc":"1. Allongez-vous sur le côté, le coude inférieur à angle droit, le bras dépassant 2. Soulevez votre bassin du sol en soulevant votre épaule inférieure, en gardant l'avant-bras sur le sol ; votre tête, votre bassin et vos pieds doivent être en ligne droite 3. Maintenez cette position","tips":["Allongez-vous sur le côté, le coude inférieur à angle droit, le bras dépassant","Maintenez cette position"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-495","wgerId":495,"name":"Curl en pronation (reverse curl)","muscle":"bras","equipment":"barre","desc":"Le curl à la barre en pronation est une variante du curl pour les biceps dans laquelle les paumes sont tournées vers le bas. Le passage d'une prise en supination à une prise en pronation sollicite davantage les muscles de l'avant-bras et le brachial antérieur dans l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-505","wgerId":505,"name":"Crunch sur banc à lombaires (roman chair)","muscle":"abdos","equipment":"none","desc":"Crunchs sur banc à lombaires (roman chair). Gardez le buste droit et les abdominaux contractés ; ne remontez pas complètement à la verticale et ne vous allongez pas non plus à plat, afin de maintenir une tension constante sur vos abdominaux.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1020","wgerId":1020,"name":"Pistol squats droites","muscle":"fessiers","equipment":"none","desc":"1. Tenez-vous debout sur une jambe, l'autre jambe droite et légèrement en avant 2. Pliez lentement un genou, descendez en position accroupie et gardez votre dos et votre autre jambe droits 3. Soulevez-vous lentement du squat, en redressant le genou plié et en gardant l'autre jambe droite 4. Répéter","tips":["Tenez-vous debout sur une jambe, l'autre jambe droite et légèrement en avant","Pliez lentement un genou, descendez en position accroupie et gardez votre dos et votre autre jambe droits","Soulevez-vous lentement du squat, en redressant le genou plié et en gardant l'autre jambe droite"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1021","wgerId":1021,"name":"Lever du mollet droit","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous debout sur le sol ou sur le bord d'une marche pour augmenter l'amplitude des mouvements. Levez un pied en plaçant la partie supérieure sur votre mollet 2. Soulevez vos talons jusqu'à ce que vous soyez debout sur les orteils 3. Restez dans cette position pendant trois secondes, puis abaissez votre pied sans toucher le sol avec votre talon.","tips":["Tenez-vous debout sur le sol ou sur le bord d'une marche pour augmenter l'amplitude des mouvements","Soulevez vos talons jusqu'à ce que vous soyez debout sur les orteils","Restez dans cette position pendant trois secondes, puis abaissez votre pied sans toucher le sol avec votre talon"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-382","wgerId":382,"name":"L Hold","muscle":"jambes","equipment":"none","desc":"Hold the L position for as long as possible","tips":["Hold the L position for as long as possible"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-323","wgerId":323,"name":"Écarté à la poulie (cable cross-over)","muscle":"pectoraux","equipment":"none","desc":"Commencez avec les câbles à environ hauteur d'épaules, un dans chaque main. Faites un pas en avant de manière à ce qu'un pied soit devant l'autre, pour la stabilité et pour que les câbles soient sous tension. Amenez les mains l'une vers l'autre devant vous. Essayez de faire en sorte que vos mains se chevauchent (de façon à ce que les câbles se croisent) de quelques centimètres.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/71/Cable-crossover-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-394","wgerId":394,"name":"Tirage à la poulie basse (rowing bas)","muscle":"dos","equipment":"none","desc":"Asseyez-vous, posez les pieds sur les cales d'appui et saisissez la barre avec une prise large. Tirez la charge d'un mouvement rapide vers votre nombril, et non plus haut. Pendant le mouvement, gardez les bras et les coudes près du corps. Vos épaules sont resserrées. Laissez redescendre la charge lentement jusqu'à ce que vos bras soient complètement tendus.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/143/Cable-seated-rows-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-395","wgerId":395,"name":"Tirage à la poulie basse, prise serrée","muscle":"dos","equipment":"none","desc":"L'exercice est identique au tirage classique à la poulie basse, mais avec une prise serrée : Asseyez-vous, posez les pieds sur les cales d'appui et saisissez la barre avec une prise large. Tirez la charge d'un mouvement rapide vers votre nombril, et non plus haut. Pendant le mouvement, gardez les bras et les coudes près du corps. Vos épaules sont resserrées. Laissez redescendre la charge lentement jusqu'à ce que vos bras soient complètement tendus.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-439","wgerId":439,"name":"Overhand Cable Curl","muscle":"bras","equipment":"none","desc":"Mains à hauteur d'épaule, fléchissez les bras vers la tête, puis reculez.","tips":["Mains à hauteur d'épaule, fléchissez les bras vers la tête, puis reculez."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-917","wgerId":917,"name":"Straight Bar Cable Front Raise","muscle":"epaules","equipment":"none","desc":"Retour à la tour de câble, câble entre les jambes, SZ Bar","tips":["Retour à la tour de câble, câble entre les jambes, SZ Bar"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1634","wgerId":1634,"name":"Pullover/rowing à la corde","muscle":"dos","equipment":"none","desc":"Installez un banc devant la machine de tirage à la poulie basse. Penchez-vous au-dessus du banc pour effectuer un rowing/pullover à la corde qui cible le grand dorsal. Voir l'image.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1634/9a4704d3-1b25-43e3-b244-3885f4d3db87.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1015","wgerId":1015,"name":"Cercles du cou dans le sens horaire","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez assis ou debout. Laissez tomber votre tête vers le bas en amenant le menton vers la poitrine, mais sans forcer. Étapes : Dans un mouvement lent et fluide, la tête détendue et sans pousser dans aucune direction : 1. inclinez la tête vers votre épaule droite. 2. puis ramenez la tête en arrière, le visage vers le haut. 3. puis inclinez la tête vers votre épaule gauche. 4. et revenez vers la position de départ. Continuez à répéter ce mouvement dans un même geste lent et fluide.","tips":["inclinez la tête vers votre épaule droite","puis ramenez la tête en arrière, le visage vers le haut","puis inclinez la tête vers votre épaule gauche","et revenez vers la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1016","wgerId":1016,"name":"Cercles du cou dans le sens antihoraire","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez assis ou debout. Laissez tomber votre tête vers le bas en amenant le menton vers la poitrine, mais sans forcer. Étapes : Dans un mouvement lent et fluide, la tête détendue et sans pousser dans aucune direction : 1. inclinez la tête vers votre épaule gauche. 2. puis ramenez la tête en arrière, le visage vers le haut. 3. puis inclinez la tête vers votre épaule droite. 4. et revenez vers la position de départ. Continuez à répéter ce mouvement dans un même geste lent et fluide.","tips":["inclinez la tête vers votre épaule gauche","puis ramenez la tête en arrière, le visage vers le haut","puis inclinez la tête vers votre épaule droite","et revenez vers la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1017","wgerId":1017,"name":"Demi-cercles du cou","muscle":"jambes","equipment":"none","desc":"Position de départ : Commencez assis ou debout. Inclinez la tête contre l'une de vos épaules, mais sans forcer. Étapes : Dans un même mouvement lent et fluide, la tête détendue et sans pousser dans aucune direction : 1. amenez la tête vers le bas, en direction de la poitrine. 2. puis inclinez-la en arrière contre votre autre épaule. 3. puis revenez à nouveau vers la poitrine. 4. et enfin vers la position de départ. Continuez à répéter ce mouvement.","tips":["amenez la tête vers le bas, en direction de la poitrine","puis inclinez-la en arrière contre votre autre épaule","puis revenez à nouveau vers la poitrine","et enfin vers la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1637","wgerId":1637,"name":"Tirage à un bras","muscle":"dos","equipment":"none","desc":"Assis au sol, utilisez une poulie haute avec une poignée simple pour effectuer des tirages verticaux en mettant l'accent sur un grand étirement du grand dorsal.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1637/a1fbe83a-a3e5-49f6-a2c2-5d5b533c2be8.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1638","wgerId":1638,"name":"Épaulé-développé à la barre","muscle":"epaules","equipment":"elastiques","desc":"Cet exercice consiste à soulever une barre du sol jusqu'aux épaules, puis à la pousser au-dessus de la tête. C'est un mouvement composé qui sollicite plusieurs groupes musculaires, notamment les jambes, le dos, les épaules et les bras. Il est souvent utilisé dans les programmes de force et de conditionnement physique pour améliorer la puissance globale et les qualités athlétiques.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1638/046c09b0-c35d-48d0-a552-39dd49f956d2.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-310","wgerId":310,"name":"Rowing aux haltères sur banc incliné","muscle":"jambes","equipment":"elastiques","desc":"1. En utilisant une prise neutre, allongez-vous en appui sur un banc incliné. 2. Prenez un haltère dans chaque main en prise neutre, en commençant les bras tendus. Ce sera votre position de départ. 3. Rétractez les omoplates et fléchissez les coudes pour tirer les haltères vers vos côtés. 4. Marquez une pause en haut du mouvement, puis revenez à la position de départ.","tips":["En utilisant une prise neutre, allongez-vous en appui sur un banc incliné","Prenez un haltère dans chaque main en prise neutre, en commençant les bras tendus","Rétractez les omoplates et fléchissez les coudes pour tirer les haltères vers vos côtés","Marquez une pause en haut du mouvement, puis revenez à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-916","wgerId":916,"name":"Smith Press","muscle":"epaules","equipment":"barre","desc":"Assis à un angle de près de 90 degrés, machine de forge","tips":["Assis à un angle de près de 90 degrés, machine de forge"],"image":"https://wger.de/media/exercise-images/916/9bf7555a-fec6-43a9-b343-aae496744e5e.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-314","wgerId":314,"name":"Essuie-glaces isométriques","muscle":"pectoraux","equipment":"none","desc":"Placez-vous en position de pompe, les mains légèrement plus écartées que la largeur des épaules. Déplacez le poids de votre corps aussi loin que possible vers un côté, en laissant le coude de ce côté se fléchir. Inversez le mouvement en passant entièrement de l'autre côté. Revenez à la position de départ et répétez le nombre de répétitions souhaité.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-320","wgerId":320,"name":"Sauts en étoile","muscle":"jambes","equipment":"none","desc":"1. Debout, pieds joints et bras le long du corps 2. Sauter jusqu'à une position où les jambes sont écartées et les mains se touchent au-dessus de la tête. 3. Répétez","tips":["Debout, pieds joints et bras le long du corps","Sauter jusqu'à une position où les jambes sont écartées et les mains se touchent au-dessus de la tête"],"image":"https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-346","wgerId":346,"name":"Landmine press","muscle":"epaules","equipment":"barre","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-319","wgerId":319,"name":"Jogging","muscle":"jambes","equipment":"none","desc":"Enfilez vos chaussures, sortez et commencez à courir à un rythme modéré.","tips":["Enfilez vos chaussures, sortez et commencez à courir à un rythme modéré."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-957","wgerId":957,"name":"Élévation bras et jambe à quatre pattes","muscle":"epaules","equipment":"none","desc":"Dans cet exercice, les muscles du dos ainsi que les muscles de l'arrière de la jambe et de l'arrière du bras sont activés en levant simultanément le bras et la jambe opposés en position à quatre pattes. Il améliore aussi l'équilibre et la proprioception. Le mouvement s'effectue de façon symétrique. 1. Mettez-vous en position à quatre pattes. 2. Rentrez le ventre, puis levez votre jambe droite et votre bras gauche. 3. Vous devez garder le ventre rentré pendant 8 secondes. 4. Au bout de 8 secondes, abaissez lentement votre bras et votre jambe. 5. Puis relâchez vos muscles.","tips":["Mettez-vous en position à quatre pattes","Rentrez le ventre, puis levez votre jambe droite et votre bras gauche","Vous devez garder le ventre rentré pendant","Au bout de","Puis relâchez vos muscles"],"image":"https://wger.de/media/exercise-images/957/0fd94587-6021-4763-856e-7227f5fcba2a.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-406","wgerId":406,"name":"Exercice de coiffe des rotateurs allongé","muscle":"jambes","equipment":"elastiques","desc":"Il s'agit d'un exercice pour les problèmes de la coiffe des rotateurs. Muscle principal : l'infra-épineux ; muscle secondaire : le petit rond. Allongez-vous sur le côté. Gardez le coude calé contre la taille et fléchi à 90°. Effectuez une rotation vers le ventre. Ajoutez du poids selon votre niveau.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-468","wgerId":468,"name":"Rétraction des omoplates à plat ventre - bras le long du corps","muscle":"dos","equipment":"none","desc":"Allongé sur le ventre, la tête posée sur une serviette. Tendez les bras bien droit sur les côtés. Levez lentement les bras en rapprochant les omoplates l'une de l'autre, et maintenez la position pendant 3 secondes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-454","wgerId":454,"name":"Pompes piquées","muscle":"pectoraux","equipment":"none","desc":"Push Up performed from a pike position (optional to have feet elevated).","tips":["Push Up performed from a pike position (optional to have feet elevated)."],"image":"https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-918","wgerId":918,"name":"Seated Dumbbell Side Lateral","muscle":"epaules","equipment":"elastiques","desc":"assis légèrement penché en avant au début de l'exercice","tips":["assis légèrement penché en avant au début de l'exercice"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-919","wgerId":919,"name":"T-Bar row","muscle":"dos","equipment":"barre","desc":"plié avec poignée triangulaire, genoux légèrement pliés","tips":["plié avec poignée triangulaire, genoux légèrement pliés"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-516","wgerId":516,"name":"Front Wood Chop","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1029","wgerId":1029,"name":"Rotation thoracique à quatre pattes, côté droit","muscle":"jambes","equipment":"none","desc":"**Position de départ :** Commencez à quatre pattes, les genoux écartés de la largeur des épaules. Placez votre main droite derrière votre tête tout en gardant votre main gauche tendue et posée au sol. **Étapes :** 1. À l'inspiration, amenez votre coude droit vers votre main gauche, en gardant la main droite derrière la tête. 2. À l'expiration, faites pivoter votre coude droit de manière à le pointer vers le plafond. 3. Répétez.","tips":["À l'inspiration, amenez votre coude droit vers votre main gauche, en gardant la main droite derrière la tête","À l'expiration, faites pivoter votre coude droit de manière à le pointer vers le plafond"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1639","wgerId":1639,"name":"Tirage facial avec haltères buste penché","muscle":"epaules","equipment":"elastiques","desc":"**Cet exercice consiste à utiliser des haltères pour effectuer un \"face pull penché en avant\" (bent over face pull), qui cible le haut du dos et les épaules. Le mouvement implique de tirer les poids vers le visage tout en gardant les coudes hauts et en serrant les omoplates l'une contre l'autre.**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1639/8927346e-f5ca-4795-bdf1-5ac9309401e7.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-2483","wgerId":2483,"name":"Wall-Hold Rotation","muscle":"abdos","equipment":"none","desc":"Tenez le mur ou le bord de la piscine avec une main, le corps horizontal à la surface, les jambes donnant des coups de pied doucement derrière vous. Gardez votre visage dans l'eau, en expirant continuellement, puis tournez la tête sur le côté — sans la soulever — de sorte qu'un masque reste dans l'eau pendant que l'autre nettoie la surface. Respirez rapidement, puis faites pivoter votre visage vers le bas jusqu'au point mort. Cela isole le mouvement de rotation de la tête sans aucun coup de bras à prendre en compte.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-675","wgerId":675,"name":"Turkish Get-Up","muscle":"epaules","equipment":"elastiques","desc":"Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps.","tips":["Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-722","wgerId":722,"name":"Weighted Step-ups","muscle":"fessiers","equipment":"none","desc":"étapes de la boîte avec haltères et 45 de chaque côté","tips":["étapes de la boîte avec haltères et 45 de chaque côté"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1087","wgerId":1087,"name":"Épaulés-jetés en puissance avec haltères depuis la suspension","muscle":"jambes","equipment":"elastiques","desc":"Debout, tenez-vous bien droit avec vos haltères, en les maintenant le long du corps. Effectuez une charnière au niveau des hanches pour les abaisser jusqu'aux genoux (image 1). Redressez-vous avec un léger saut, en utilisant l'élan pour tirer les haltères jusqu'à vos épaules (image 2). Tenez-vous bien droit, puis redescendez les haltères le long du corps de façon contrôlée et répétez. Gardez le mouvement rapide et explosif ; si votre fréquence cardiaque ne grimpe pas en flèche, c'est que vous les exécutez mal.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1087/d85f4e02-b20c-457c-bdfb-0b00e2d14150.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1088","wgerId":1088,"name":"Soulevé de terre sumo avec haltère","muscle":"jambes","equipment":"elastiques","desc":"Abaissez votre haltère au sol entre vos jambes. Adoptez une position large et, le dos droit, accroupissez-vous. L'haltère posé à la verticale, saisissez-le par le haut de la « tête » (image 1). En gardant la poitrine relevée et la sangle abdominale gainée, repoussez le sol pour vous redresser jusqu'à la position debout (image 2). Répétez. Si vous atteignez facilement 20 à 30 répétitions, utilisez deux haltères.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-500","wgerId":500,"name":"Reverse Plank","muscle":"jambes","equipment":"none","desc":"Planche avec l'estomac vers le plafond","tips":["Planche avec l'estomac vers le plafond"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-527","wgerId":527,"name":"Run","muscle":"jambes","equipment":"none","desc":"Courir ou faire du jogging à l'extérieur dans un parc, sur les pistes, …","tips":["Courir ou faire du jogging à l'extérieur dans un parc, sur les pistes, …"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-672","wgerId":672,"name":"Trunk Rotation With Cable","muscle":"abdos","equipment":"none","desc":"Rotation du tronc assis avec câble","tips":["Rotation du tronc assis avec câble"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-922","wgerId":922,"name":"Seated Cable Mid Trap Shrug","muscle":"dos","equipment":"none","desc":"assis droit vers l'arrière, légère prise au sommet","tips":["assis droit vers l'arrière, légère prise au sommet"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1635","wgerId":1635,"name":"Modified pulldown","muscle":"dos","equipment":"none","desc":"Avec un banc incliné devant le pulldown, utilisez une poignée serrée pour faire des pulldowns latfocalisés.","tips":["Avec un banc incliné devant le pulldown, utilisez une poignée serrée pour faire des pulldowns latfocalisés."],"image":"https://wger.de/media/exercise-images/1635/b8c34e3a-7474-41ea-99e3-8d7fdb1e12d6.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-974","wgerId":974,"name":"Curl à la kettlebell à deux mains","muscle":"bras","equipment":"elastiques","desc":"Tenez-vous debout bien droit et saisissez la kettlebell à deux mains. Effectuez le mouvement de flexion du coude, en partant d'une position complètement tendue jusqu'à ce que votre main atteigne la hauteur des épaules. Écartez un peu les jambes pour la stabilité et, pour réaliser l'exercice correctement, essayez de ne pas pousser avec le dos ni avec le corps en général. Changez le poids de la kettlebell pour ajuster la difficulté.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1713","wgerId":1713,"name":"Étirement des pectoraux dans l'encadrement de porte","muscle":"pectoraux","equipment":"none","desc":"1. Placez l'avant-bras à la verticale contre un encadrement de porte ou un objet fixe, à hauteur de la tête 2. Avancez d'un pas au-delà du bras, en le maintenant immobile contre l'objet, afin d'étirer les pectoraux","tips":["Placez l'avant-bras à la verticale contre un encadrement de porte ou un objet fixe, à hauteur de la tête","Avancez d'un pas au-delà du bras, en le maintenant immobile contre l'objet, afin d'étirer les pectoraux"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-539","wgerId":539,"name":"Incline Bench Press - MP","muscle":"pectoraux","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"https://wger.de/media/exercise-images/61/Close-grip-bench-press-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-577","wgerId":577,"name":"Flexion latérale du tronc avec haltère","muscle":"abdos","equipment":"elastiques","desc":"Également appelées flexions latérales avec haltère. Tenez-vous debout dans l'alignement des hanches, les genoux légèrement fléchis, en conservant la courbure naturelle de la colonne vertébrale, un bras tendu le long du corps, et saisissez l'haltère d'une main. Effectuez des flexions latérales du buste, lentes et contrôlées, jusqu'à atteindre un angle d'environ 45°.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-578","wgerId":578,"name":"Rotation externe allongé sur le côté","muscle":"jambes","equipment":"none","desc":"Avec un poids dans une main, allongez-vous sur le côté opposé au poids. Gardez les genoux légèrement fléchis. Maintenez le coude collé contre le flanc et tendez l'avant-bras droit devant vous. Tout en continuant de maintenir le coude contre le flanc, faites pivoter l'avant-bras de 90 degrés vers le haut. Il est utile de placer une serviette sous l'aisselle pour faciliter l'exécution correcte de cet exercice. Placer un support sous la tête pendant toute la durée de l'exercice est également une bonne idée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-595","wgerId":595,"name":"Saut à la corde - Standard","muscle":"jambes","equipment":"none","desc":"Effectuez un seul saut à pieds joints à chaque tour de corde. Travaillez un mouvement fluide et rythmé, en rebondissant légèrement sur la pointe des pieds.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-556","wgerId":556,"name":"Side Bends on Machine","muscle":"abdos","equipment":"elastiques","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-624","wgerId":624,"name":"Stationary Bike","muscle":"jambes","equipment":"none","desc":"Conduisez un vélo stationnaire avec diverses tensions.","tips":["Conduisez un vélo stationnaire avec diverses tensions."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-655","wgerId":655,"name":"Extension des avant-bras avec haltère","muscle":"bras","equipment":"elastiques","desc":"1. Commencez par prendre un haltère dans chaque main, les paumes tournées vers le torse. Gardez le dos droit, pliez légèrement les genoux et penchez-vous vers l'avant au niveau de la taille. Votre torse doit être presque parallèle au sol. Veillez à garder la tête haute. Les parties supérieures des bras doivent être proche du torse et parallèle au sol. Les avant-bras doivent être dirigés vers le sol lorsque vous tenez les haltères. Un angle de 90 degrés doit être formé entre l'avant-bras et le bras. C'est votre position de départ. 2. Maintenant, tout en gardant les bras immobiles, expirez et utilisez vos triceps pour soulever les haltères jusq","tips":["Commencez par prendre un haltère dans chaque main, les paumes tournées vers le torse","Répétez le mouvement pour le nombre de répétitions prescrit"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-636","wgerId":636,"name":"Superman","muscle":"fessiers","equipment":"none","desc":"Allongez-vous à plat ventre, les bras tendus devant vous au sol et les jambes posées à plat. Levez simultanément les bras et les jambes, comme si vous voliez, et contractez le bas du dos. Veillez à bien respirer et, selon votre niveau de forme physique, maintenez la position pendant au moins deux à cinq secondes par répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-661","wgerId":661,"name":"Triceps à la machine","muscle":"bras","equipment":"none","desc":"Asseyez-vous et saisissez fermement la barre avec les mains. Poussez maintenant le poids vers le haut (sans tendre complètement les bras), puis abaissez-le lentement. Comme pour les autres exercices de triceps, il est important de ne pas bouger les bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-623","wgerId":623,"name":"Enrouleur de poignet debout","muscle":"jambes","equipment":"none","desc":"Saisissez un enrouleur de poignet à deux mains, debout, les pieds écartés à environ la largeur des épaules. Si votre salle ne dispose pas d'un enrouleur de poignet, vous pouvez facilement en fabriquer un. Il vous suffit d'un disque de 2 à 5 kg, d'une corde fine et solide d'environ 1 mètre de long, et d'un bâton ou d'une barre de 15 à 20 cm. Fixez solidement la corde au milieu de la barre ou du bâton, puis attachez l'autre extrémité de la corde au disque. Pour commencer cet exercice, saisissez la barre ou le bâton à deux mains en prise pronation. Tendez les deux bras droit devant vous, parallèlement au sol. Enroulez ensuite le poids depuis le ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-683","wgerId":683,"name":"Power Clean","muscle":"pectoraux","equipment":"barre","desc":"Haltérophilie olympique","tips":["Haltérophilie olympique"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-688","wgerId":688,"name":"Upper External Oblique","muscle":"abdos","equipment":"none","desc":"Exercice pour les muscles obliques externes supérieurs","tips":["Exercice pour les muscles obliques externes supérieurs"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-716","wgerId":716,"name":"Glissements muraux","muscle":"bras","equipment":"none","desc":"Tenez-vous debout, les talons, les épaules, l'arrière de la tête et les hanches en contact avec le mur. Commencez avec les bras tendus sur les côtés et les coudes pliés à 90 degrés. Tendez les bras tout en restant contre le mur, sans décoller le dos du mur en le cambrant, en imitant un mouvement de développé épaules.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-687","wgerId":687,"name":"Overhead Press","muscle":"epaules","equipment":"barre","desc":"Consulte la description complète sur wger.de.","tips":["Consulte la description complète sur wger.de."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1027","wgerId":1027,"name":"Étirement de la prière surélevé","muscle":"dos","equipment":"barre","desc":"**Position de départ :** Agenouillez-vous devant un banc, suffisamment loin pour que votre buste puisse se loger entre vos genoux et le banc. Le dos droit, posez vos coudes sur le banc, les paumes jointes, les mains pointées vers le haut. **Étapes :** 1. À l'expiration, étirez votre poitrine vers le sol sans bouger le bas du dos. En même temps, rapprochez vos mains de vos épaules, en gardant les paumes jointes et les coudes sur le banc. 2. Maintenez la position quelques secondes. 3. À l'inspiration, relâchez le dos pour revenir à la position de départ. 4. Répétez.","tips":["À l'expiration, étirez votre poitrine vers le sol sans bouger le bas du dos","Maintenez la position quelques secondes","À l'inspiration, relâchez le dos pour revenir à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1028","wgerId":1028,"name":"Rotation thoracique à quatre pattes à gauche","muscle":"jambes","equipment":"none","desc":"**Position de départ :** Placez-vous à quatre pattes, les genoux écartés à la largeur des épaules. Posez votre main gauche derrière votre tête tout en gardant votre main droite tendue et en contact avec le sol. **Étapes :** 1. À l'inspiration, déplacez votre coude gauche vers votre main droite, en gardant votre main gauche derrière la tête. 2. À l'expiration, déplacez votre coude gauche de manière à le pointer vers le plafond. 3. Répétez.","tips":["À l'inspiration, déplacez votre coude gauche vers votre main droite, en gardant votre main gauche derrière la tête","À l'expiration, déplacez votre coude gauche de manière à le pointer vers le plafond"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1080","wgerId":1080,"name":"Pompes hindoues","muscle":"epaules","equipment":"none","desc":"Exercice destiné à renforcer les épaules et les pectoraux. Son nom vient du fait qu'il débute dans la posture de yoga « chien tête en bas », passe à la posture du « cobra » mais sans poser les jambes ni le buste au sol, pour finir enfin par une pompe classique. L'exercice peut aussi être exécuté en sens inverse (retour à la position de départ). Comme variante, après avoir réalisé la pompe, on peut lever les hanches pour revenir à la posture du chien tête en bas.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1081","wgerId":1081,"name":"Dislocations d'épaules","muscle":"jambes","equipment":"none","desc":"**Position de départ :** Tenez-vous debout, le dos droit, un élastique, une serviette ou un manche à balai dans les mains. Les mains tendues devant le corps et l'élastique tendu entre elles, écartez les mains pour les placer toutes deux à environ 45 degrés du corps, les pouces vers le bas. Si vous utilisez plutôt une serviette ou un manche à balai, saisissez-le en prise pronation. **Étapes :** 1. En gardant les bras tendus, effectuez une rotation au niveau des épaules pour amener vos bras au-dessus de la tête, puis vers le bas en direction des fessiers. 2. Effectuez une rotation des épaules dans le sens inverse : au-dessus de la tête, puis ve","tips":["Effectuez une rotation des épaules dans le sens inverse : au-dessus de la tête, puis vers l'aine"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1082","wgerId":1082,"name":"Rowing penché vers rotation externe","muscle":"jambes","equipment":"none","desc":"**Position de départ :** Tenez-vous derrière une chaise ou devant une table. Penchez-vous au niveau de la taille pour poser votre front sur le dossier de la chaise ou sur la table, en gardant le dos droit. Vos bras doivent pendre droit vers le bas, dirigés vers le sol. **Étapes :** 1. Montez vos coudes à hauteur d'épaules. Vos avant-bras doivent pointer vers le bas, perpendiculaires à vos bras. Vos bras doivent être à la même hauteur que votre dos et perpendiculaires à votre colonne vertébrale. 2. Maintenez un instant. 3. Effectuez une rotation au niveau des coudes pour amener vos mains le plus haut possible. 4. Maintenez un instant. 5. Effec","tips":["Montez vos coudes à hauteur d'épaules","Maintenez un instant","Effectuez une rotation au niveau des coudes pour amener vos mains le plus haut possible","Maintenez un instant","Effectuez une rotation au niveau des coudes pour revenir à la position précédente"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1083","wgerId":1083,"name":"YWT","muscle":"jambes","equipment":"none","desc":"**Position de départ :** Allongez-vous, de préférence sur un tapis. Tendez vos bras au-dessus de la tête en position « Y » (les bras pointant vers le haut en diagonale, à environ 45 degrés). Vos pouces doivent être dirigés vers le haut. **Étapes :** 1. Les bras en position Y, décollez légèrement votre poitrine du sol, en créant une tension de traction dans vos bras vers le haut. 2. Maintenez cette position pendant plusieurs secondes (15 à 30 secondes idéalement). 3. En gardant la poitrine relevée, pliez les coudes pour passer de la position Y à une position « W », les bras fléchis au niveau des coudes et en conservant la tension vers le haut.","tips":["Maintenez cette position pendant plusieurs secondes (","Maintenez à peu près aussi longtemps que pour la position Y","Maintenez à peu près aussi longtemps que pour la position W","Passez de la position T à la position W, puis de la position W à la position Y"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1086","wgerId":1086,"name":"Pompes prise serrée","muscle":"bras","equipment":"none","desc":"Placez-vous dans une position de planche solide, en rapprochant les mains jusqu'à ce qu'elles se touchent presque (image 1). Pliez les coudes pour amener lentement votre poitrine vers le sol (image 2). Gardez les coudes près du corps tout en poussant de manière explosive pour remonter. Répétez. Veillez à prendre votre temps à la descente de chaque répétition, en gardant une exécution irréprochable.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1086/b2ee8d9b-0480-4992-8494-c223b37c2696.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1089","wgerId":1089,"name":"Rotation avec ballon médicinal","muscle":"abdos","equipment":"none","desc":"En position assise, le buste pivote d'un côté à l'autre sans forcer, en s'approchant des genoux et en faisant toucher le sol au ballon de temps en temps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1089/49f51716-535d-41dd-aeb5-cff5bb906bc1.jpeg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1090","wgerId":1090,"name":"Vpushup","muscle":"pectoraux","equipment":"none","desc":"Soulevez votre corps du sol en poussant vos bras vers le haut","tips":["Soulevez votre corps du sol en poussant vos bras vers le haut"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1091","wgerId":1091,"name":"Touchers d'épaules en planche","muscle":"epaules","equipment":"none","desc":"Dans la position correcte de la planche, placez vos pieds légèrement plus écartés que la largeur des épaules. Levez alternativement une main pour toucher l'épaule opposée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1640","wgerId":1640,"name":"Squat avant avec haltères","muscle":"fessiers","equipment":"elastiques","desc":"**Cet exercice consiste à tenir un haltère dans chaque main à hauteur d'épaule et à effectuer un squat. Il cible les muscles du bas du corps, notamment les quadriceps, les ischio-jambiers et les fessiers, tout en engageant également le tronc (le *core*) et le haut du corps.**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1104","wgerId":1104,"name":"Walking","muscle":"jambes","equipment":"none","desc":"En marchant à l'extérieur ou à l'intérieur, essayez de garder un rythme de 100 pas par minute.","tips":["En marchant à l'extérieur ou à l'intérieur, essayez de garder un rythme de 100 pas par minute."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1125","wgerId":1125,"name":"Tirage vertical prise large en supination","muscle":"dos","equipment":"none","desc":"Mouvement vers le bas • Tirez la barre vers le bas de sorte qu'elle passe près de votre menton et touche le haut de votre poitrine. • Gardez le reste de votre corps immobile.","tips":["Mouvement vers le bas","Tirez la barre vers le bas de sorte qu'elle passe près de votre menton et touche le haut de votre poitrine.","Gardez le reste de votre corps immobile."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1641","wgerId":1641,"name":"Soulevé de terre unilatéral","muscle":"fessiers","equipment":"elastiques","desc":"**Cet exercice consiste à tenir un *kettlebell* (ou une *cloche*) dans une main et à se tenir sur une jambe tout en se penchant vers l'avant pour toucher le sol avec le *kettlebell*. Il cible les ischio-jambiers, les fessiers et le bas du dos, tout en améliorant également l'équilibre et la stabilité.**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1641/68d9488d-2596-420f-be0f-52aa70732c83.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1642","wgerId":1642,"name":"Hip Thrust avec haltère","muscle":"fessiers","equipment":"elastiques","desc":"Cet exercice consiste à s'asseoir sur le sol avec un haltère posé sur les hanches, puis à pousser les hanches vers le haut tout en contractant les fessiers. C'est un excellent exercice pour renforcer les fessiers et améliorer la mobilité des hanches.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-2484","wgerId":2484,"name":"Side-Kick Breathing (Kickboard)","muscle":"fessiers","equipment":"none","desc":"Push off the wall on your side (not flat on your stomach), one arm extended forward holding the board or just extended, kicking continuously. Keep your head in a neutral position looking at the bottom of the pool, and when you need air, rotate your head sideways (one ear stays in the water, other faces up) to breathe, then rotate back to neutral. Swim a length like this, then repeat on the other side. This teaches the exact head position and rotation you'll use once full stroke breathing comes in.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1101","wgerId":1101,"name":"Horizontal traction isometry","muscle":"dos","equipment":"none","desc":"Effectuer un tirage isométrique chronométré sur la barre","tips":["Effectuer un tirage isométrique chronométré sur la barre"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-9","wgerId":9,"name":"2 Handed Kettlebell Swing","muscle":"jambes","equipment":"elastiques","desc":"Balançoire Kettlebell style russe à deux mains","tips":["Balançoire Kettlebell style russe à deux mains"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1648","wgerId":1648,"name":"Crunch lesté","muscle":"abdos","equipment":"elastiques","desc":"Le Crunch lesté cible principalement les **grands droits de l'abdomen** (les fameuses \"tablettes de chocolat\").","tips":["Le Crunch lesté cible principalement les **grands droits de l'abdomen** (les fameuses \"tablettes de chocolat\")."],"image":"https://wger.de/media/exercise-images/1648/63ae02d6-6dd9-4e9e-84da-d4905e78a33c.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1011","wgerId":1011,"name":"Étirement du cou en avant","muscle":"jambes","equipment":"none","desc":"Starting position: Sit or stand with your back straight. Steps: 1. Open mouth wide. 2. Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head. 3. Very slowly close and open your mouth. 4. At the end, slowly return to starting position and close mouth.","tips":["Open mouth wide","Slowly tilt head back with mouth opened","Very slowly close and open your mouth","At the end, slowly return to starting position and close mouth"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1650","wgerId":1650,"name":"Flexion Latérale avec haltère","muscle":"abdos","equipment":"elastiques","desc":"Cet exercice consiste à tenir un **haltère** dans une main et à se pencher sur le côté pour travailler les **muscles obliques** sur le flanc du corps. Il peut être effectué **debout** ou **assis** et est souvent utilisé comme exercice de **renforcement du tronc** (*core strengthening*).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1650/1d7a5336-ec0b-4898-a474-78ba32789bf3.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1651","wgerId":1651,"name":"Fente arrière avec haltères","muscle":"fessiers","equipment":"elastiques","desc":"Cet exercice consiste à tenir un **haltère** dans chaque main et à reculer pour se mettre en position de **fente** (*lunge*), puis à revenir à la position debout. Il cible principalement les **fessiers**, les **ischio-jambiers** et les **quadriceps**.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1651/04ab2679-a04d-4d05-9c85-0d36e898328c.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1119","wgerId":1119,"name":"Remo maquina agarre estrecho","muscle":"dos","equipment":"none","desc":"Remo en máquina con barra en agarre estrecho","tips":["Remo en máquina con barra en agarre estrecho"],"image":"https://wger.de/media/exercise-images/1119/9b138ad2-5b80-42a8-bfff-93a960444ffe.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1653","wgerId":1653,"name":"Squat latéral avec haltère","muscle":"fessiers","equipment":"none","desc":"Cet exercice consiste à tenir un **haltère** dans une main et à effectuer un **squat** tout en faisant un **pas latéral** (*step to the side*). Il cible les **jambes**, les **fessiers** et les **muscles du tronc** (*core muscles*).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1653/c10c4e17-1e14-4cf9-930b-cc3a614f15dd.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1654","wgerId":1654,"name":"Élévation latérale à la machine","muscle":"epaules","equipment":"none","desc":"L'élévation latérale à la machine est un exercice d'isolation qui cible le faisceau moyen (latéral) du deltoïde afin de développer des épaules plus larges et plus dessinées. La trajectoire fixe de la machine offre une plus grande stabilité que les haltères, ce qui la rend idéale pour les débutants ou pour ceux qui souhaitent se concentrer uniquement sur l'activation musculaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1654/aa724a58-b3b5-4522-b278-1155416236a5.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1120","wgerId":1120,"name":"Remo maquina agarre estrecho supino","muscle":"dos","equipment":"none","desc":"Remo en máquina o polea con agarre cerrado supino","tips":["Remo en máquina o polea con agarre cerrado supino"],"image":"https://wger.de/media/exercise-images/1120/df9a5256-e977-44d0-bc9c-b53253faeb22.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1204","wgerId":1204,"name":"Cycling cardio session","muscle":"jambes","equipment":"none","desc":"Séance de cardio sur un vélo stationnaire Technogym Bike Excite 1000.","tips":["Séance de cardio sur un vélo stationnaire Technogym Bike Excite 1000."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1208","wgerId":1208,"name":"Squat du prisonnier","muscle":"fessiers","equipment":"none","desc":"Tenez-vous debout, la poitrine légèrement relevée, les pieds écartés à la largeur des hanches et les orteils pointant droit devant. Amenez vos mains derrière votre tête, les doigts légèrement entrelacés et les coudes pointant sur les côtés. Poussez vos hanches vers l'arrière et fléchissez les genoux, en gardant le haut du corps aussi droit que possible. Poussez vos genoux vers l'extérieur ; ils ne doivent jamais pointer l'un vers l'autre. Si le haut de votre corps se penche légèrement vers l'avant, veillez à ce qu'il ne s'arrondisse pas. Gardez toujours vos coudes au niveau de vos oreilles en contractant les muscles entre vos omoplates. Si vo","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1652","wgerId":1652,"name":"Soulevé de terre roumain avec haltères","muscle":"jambes","equipment":"elastiques","desc":"Cet exercice consiste à tenir un **haltère** dans chaque main et à se pencher vers l'avant au niveau des **hanches** tout en gardant le **dos droit**, puis à revenir à la position debout. Il cible principalement les **ischio-jambiers** et les **fessiers**.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1109","wgerId":1109,"name":"Curl concentration à la poulie","muscle":"bras","equipment":"none","desc":"Le curl concentration est un exercice classique pour développer les biceps un bras à la fois. Il peut être exécuté penché en avant ou à genoux, mais il est le plus souvent réalisé assis sur un banc. Il est excellent pour accentuer le pic du biceps et sert souvent à conclure une séance de biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1109/00b0a0bf-c14a-4f13-bb14-62c09030a1aa.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1127","wgerId":1127,"name":"Tirage vertical en prise serrée et supination","muscle":"dos","equipment":"none","desc":"Mouvement vers le bas • Tirez la barre vers le bas de sorte qu'elle passe près de votre menton et touche la partie supérieure de votre poitrine. • Gardez le reste de votre corps immobile.","tips":["Mouvement vers le bas","Gardez le reste de votre corps immobile."],"image":"https://wger.de/media/exercise-images/1127/4942b7c0-6bda-4983-88e5-86547c3d445e.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-911","wgerId":911,"name":"Incline Skull Crush","muscle":"bras","equipment":"none","desc":"Assis dans un angle de 45 degrés, en utilisant DB pour faire un écrasement incliné du crâne","tips":["Assis dans un angle de 45 degrés, en utilisant DB pour faire un écrasement incliné du crâne"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1131","wgerId":1131,"name":"Extension des fessiers à la poulie","muscle":"fessiers","equipment":"none","desc":"Cet exercice vous permet de travailler la partie supérieure, ou la plus volumineuse, des fessiers. C'est pourquoi il ne devrait jamais manquer dans votre programme d'exercices isolés destinés à entraîner les fessiers. Tenez-vous debout devant une machine à poulie et repérez la poulie basse. Fixez ensuite la sangle de cheville pour travailler à la poulie basse. Quant à votre posture, vous devez rester droit en permanence. Veillez tout particulièrement à votre dos pour le maintenir droit et éviter les blessures. Il est conseillé de vous tenir à la machine pour un meilleur équilibre. Avec la jambe qui supporte la charge du câble, effectuez lente","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1131/3bcf3024-2dcc-4995-9694-55aa2c2e4a9a.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1136","wgerId":1136,"name":"Tirage poitrine en prise neutre","muscle":"bras","equipment":"none","desc":"Le tirage vertical est un exercice important pour renforcer le dos et améliorer la posture, ce qui peut contribuer à une vie plus saine. Pour réaliser correctement cet exercice et éviter les blessures, il est important de suivre quelques étapes clés : 1. Placez-vous devant la machine à poulie, les genoux légèrement fléchis et les pieds au sol. 2. Saisissez la poignée du câble, paumes se faisant face et mains écartées à la largeur des épaules. 3. Tirez la poignée vers le bas jusqu'à ce qu'elle touche votre poitrine ou s'en approche, en maintenant la position pendant une ou deux secondes. 4. Remontez lentement la poignée jusqu'à la position de ","tips":["Placez-vous devant la machine à poulie, les genoux légèrement fléchis et les pieds au sol","Saisissez la poignée du câble, paumes se faisant face et mains écartées à la largeur des épaules"],"image":"https://wger.de/media/exercise-images/1136/5778a8e9-c606-4843-89c8-9d9469eeb6e4.PNG.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1137","wgerId":1137,"name":"Pullover à la poulie haute","muscle":"dos","equipment":"none","desc":"Tenez-vous debout face à la machine, les pieds légèrement écartés, en saisissant la barre en prise pronation, les bras tendus, les mains écartées à la largeur des épaules. - En gardant le dos fixe et les abdominaux contractés, inspirez et descendez la barre vers vos cuisses tout en gardant les bras tendus (ou les coudes légèrement fléchis). Expirez en fin de mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1137/42f22229-c0a0-4bfc-aca6-66fe5e1ab10d.PNG.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1093","wgerId":1093,"name":"Rowing Machine","muscle":"epaules","equipment":"none","desc":"Asseyez-vous sur un rameur avec le dos droit.","tips":["Asseyez-vous sur un rameur avec le dos droit."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1094","wgerId":1094,"name":"Développé couché assis","muscle":"pectoraux","equipment":"barre","desc":"Réglez la machine de développé pectoral de sorte que les poignées soient alignées avec le bas de votre poitrine lorsque vous êtes assis. Veillez à être assis le dos bien plaqué contre le dossier. Saisissez une poignée dans chaque main, sortez la poitrine et gardez la tête appuyée contre l'appui-tête. Respirez profondément et poussez lentement les poignées vers l'avant jusqu'à ce que vos bras soient presque complètement tendus. Marquez une pause juste avant le verrouillage des coudes, puis ramenez lentement les poignées à la position de départ. Marquez une pause juste avant que les poignées ne s'immobilisent complètement, puis effectuez une au","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-84","wgerId":84,"name":"Rowing penché en supination","muscle":"dos","equipment":"barre","desc":"Identique au rowing *classique*, mais avec une prise inversée (les paumes pointant vers l'avant) : Saisissez la barre avec une prise large (un peu plus large que les épaules) et penchez-vous en avant. Votre haut du corps n'est pas tout à fait parallèle au sol, mais forme un léger angle. La poitrine reste sortie pendant tout l'exercice. Tirez maintenant la barre d'un mouvement rapide vers votre nombril, sans monter plus haut. Redescendez lentement à la position initiale. Ne donnez pas d'élan avec le corps et gardez les bras près du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/110/Reverse-grip-bent-over-rows-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1096","wgerId":1096,"name":"Abduction debout","muscle":"jambes","equipment":"none","desc":"Travailler une posture stable, principalement sur une seule jambe, est essentiel pour les deux côtés. D'une part, cela prévient les inconforts et, d'autre part, cela établit une base solide. Le pratiquant adopte la position debout habituelle et, le haut du corps stable, tente de lever à plusieurs reprises la jambe non chargée, de la fléchir au niveau de la hanche et du genou, puis de la rabaisser. Le mouvement est également répété de l'autre côté. L'exercice travaille la stabilité des muscles entourant la hanche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1138","wgerId":1138,"name":"Incline bench pulldown","muscle":"dos","equipment":"none","desc":"Allongé face cachée sur le banc incliné face à la machine à câbles, effectuez le pullldown.","tips":["Allongé face cachée sur le banc incliné face à la machine à câbles, effectuez le pullldown."],"image":"https://wger.de/media/exercise-images/1138/6c35fd79-ef35-4cf3-abf5-9c969457b8d4.PNG.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1098","wgerId":1098,"name":"Seated rear delt rise","muscle":"dos","equipment":"elastiques","desc":"Assis, plié à 45 degrés vers l'avant. Bras complètement tendus, soulevez les bras jusqu'à la hauteur des épaules et redescendez","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1098/fa5328a2-64cb-4afb-a283-b3d948ddaf3f.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1099","wgerId":1099,"name":"Maintien latéral dynamique","muscle":"abdos","equipment":"elastiques","desc":"Passez un élastique autour d'une kettlebell et soulevez la kettlebell par l'élastique. Laissez-la pendre le long de votre flanc et tenez-vous en équilibre sur une jambe, puis changez de jambe tout en maintenant la position. Répétez avec l'autre main.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1100","wgerId":1100,"name":"Wall balls","muscle":"epaules","equipment":"none","desc":"Obtenez une balle de médecine, position de largeur d'épaule, accroupissez-vous, poussez la balle aussi haut que possible contre le mur et attrapez","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1185","wgerId":1185,"name":"Triceps Pushdown","muscle":"bras","equipment":"none","desc":"Poussée du triceps sur le câble à l'aide de la barre lat.","tips":["Poussée du triceps sur le câble à l'aide de la barre lat."],"image":"https://wger.de/media/exercise-images/1185/c5ca283d-8958-4fd8-9d59-a3f52a3ac66b.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1102","wgerId":1102,"name":"Alternate back lunges","muscle":"fessiers","equipment":"none","desc":"Les muscles postérieurs des fesses, des ischio-jambiers, du soléaire et du gastrocnémien sont plus entraînés","tips":["Les muscles postérieurs des fesses, des ischio-jambiers, du soléaire et du gastrocnémien sont plus entraînés"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1103","wgerId":1103,"name":"Pont en marche","muscle":"abdos","equipment":"none","desc":"Partez d'une position debout, les genoux légèrement fléchis et les mains posées au sol. À partir de là, avancez avec les mains en gardant les fessiers contractés et sans perdre le contrôle du bas du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1186","wgerId":1186,"name":"One Arm Bent Row","muscle":"dos","equipment":"none","desc":"Un bras plié sur la rangée sur le câble avec une machine","tips":["Un bras plié sur la rangée sur le câble avec une machine"],"image":"https://wger.de/media/exercise-images/1186/1987a039-cf35-437e-bbdc-40c53dd7d053.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1105","wgerId":1105,"name":"Seated Knee Tuck","muscle":"abdos","equipment":"none","desc":"Asseyez-vous sur le sol ou sur un tapis. Placez les bras légèrement derrière vous. Levez les jambes. Maintenant, étendez vos jambes et tirez-les vers l'arrière.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1105/36776818-799a-40bf-9eca-aebb3aa5008f.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1194","wgerId":1194,"name":"Pallof press","muscle":"epaules","equipment":"none","desc":"Le Pallof press est un exercice anti-rotation qui entraîne les grands et petits muscles autour de la colonne vertébrale à résister à la rotation. * Tenez-vous parallèle à la machine à poulie ou au point d'ancrage de l'élastique et saisissez la poignée ou l'élastique à deux mains. * Assurez-vous que votre torse est bien de face, amenez vos mains au centre de votre poitrine et poussez lentement vers l'avant. * Ramenez lentement vos mains vers la poitrine et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1194/074e1766-4208-4a67-a211-9721772d99b0.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1111","wgerId":1111,"name":"Pompes | Inclinées","muscle":"pectoraux","equipment":"barre","desc":"Les pompes inclinées ciblent principalement les muscles de la poitrine (grand et petit pectoral), mais sollicitent aussi, dans une moindre mesure, les triceps, les épaules et la sangle abdominale. Comme le haut du corps est surélevé, la pompe inclinée sollicite moins les triceps que les pompes classiques, ce qui peut être bénéfique pour les personnes souhaitant cibler spécifiquement les muscles de la poitrine.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1112","wgerId":1112,"name":"Pompes déclinées","muscle":"pectoraux","equipment":"barre","desc":"Les pompes déclinées sont une autre version modifiée de la pompe traditionnelle qui sollicite les muscles du haut du corps d'une manière différente. Pour effectuer une pompe déclinée, surélevez vos pieds sur une surface surélevée, telle qu'un banc, une chaise ou une marche, tout en plaçant vos mains au sol en position de pompe. Abaissez votre corps vers le sol tout en maintenant une ligne droite de vos épaules à vos chevilles, puis remontez à la position de départ Contrairement à la pompe inclinée, la pompe déclinée met davantage l'accent sur les épaules et les triceps, tout en engageant les muscles de la poitrine dans une moindre mesure. En ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1112/81f40bee-4adf-4317-8476-1a87706e3031.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1113","wgerId":1113,"name":"Pompes | Parallettes","muscle":"pectoraux","equipment":"none","desc":"Les pompes sur parallettes sont une variante de la pompe traditionnelle, exécutée avec les mains posées sur des barres parallèles appelées parallettes. Pour réaliser une pompe sur parallettes, placez-vous en position de pompe avec les mains sur les parallettes et les pieds au sol. Abaissez votre corps vers le sol en gardant les coudes près du corps, puis poussez pour revenir à la position de départ. Les pompes sur parallettes mettent davantage l'accent sur la poitrine et les épaules que les pompes traditionnelles, car elles permettent une plus grande amplitude de mouvement au niveau de l'articulation de l'épaule. Cette amplitude accrue peut é","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1114","wgerId":1114,"name":"Rest (for timed workouts)","muscle":"jambes","equipment":"none","desc":"Lorsque vous créez un entraînement basé sur le temps, ajoutez-le pour ajouter du temps de repos dans le programme","tips":["Lorsque vous créez un entraînement basé sur le temps, ajoutez-le pour ajouter du temps de repos dans le programme"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1115","wgerId":1115,"name":"Échauffement en fentes 3D","muscle":"jambes","equipment":"elastiques","desc":"Pour l'échauffement, utilisez des haltères légers, un dans chaque main. Effectuez des fentes dans des directions alternées : vers l'avant, sur le côté, vers l'arrière et à 45 degrés.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1116","wgerId":1116,"name":"Dumbbell farmer's carry","muscle":"jambes","equipment":"elastiques","desc":"Prenez la moitié de votre poids corporel dans chaque main et marchez.","tips":["Prenez la moitié de votre poids corporel dans chaque main et marchez."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1132","wgerId":1132,"name":"Extension des fessiers à la machine","muscle":"fessiers","equipment":"none","desc":"L'extension de hanche au banc à lombaires (GHD) est l'un des meilleurs exercices pour les fessiers. Bien que l'exercice cible principalement les fessiers, il est également excellent pour le bas du dos, les mollets et les ischio-jambiers.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1141","wgerId":1141,"name":"Arabesque","muscle":"jambes","equipment":"none","desc":"Reportez tout votre poids sur une seule jambe et maintenez cette position, en gardant les hanches et le bassin à niveau pendant toute la durée du mouvement. Le dos en position neutre, penchez-vous vers l'avant en projetant votre jambe vers l'arrière, puis revenez lentement à la position neutre en contractant vos fessiers.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1141/c7be1cd1-46c5-4a86-a114-5f0fe861c3e0.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1143","wgerId":1143,"name":"Back extensión","muscle":"dos","equipment":"none","desc":"Espalda en maquina de extensión con peso","tips":["Espalda en maquina de extensión con peso"],"image":"https://wger.de/media/exercise-images/1143/6e21cb6c-da09-4bcd-b9d2-1ef75237b763.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1192","wgerId":1192,"name":"Curls biceps alternés avec haltères","muscle":"bras","equipment":"elastiques","desc":"Tenez deux haltères, les bras tendus, les mains le long du corps, les paumes tournées vers l'intérieur. Fléchissez un bras à la fois et montez la charge dans un mouvement rapide. En même temps, faites pivoter votre bras de 90 degrés tout au début du mouvement. Au point le plus haut, faites pivoter un peu plus les haltères vers l'extérieur. Sans pause, redescendez le bras lentement, puis faites de même avec l'autre bras. Ne laissez pas votre corps se balancer pendant l'exercice ; tout le travail est effectué par les biceps, qui sont les seuls muscles qui doivent bouger (faites attention aux coudes).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1192/651a4535-8210-4dbd-8f06-61d95fdd9963.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1193","wgerId":1193,"name":"Russian twist","muscle":"dos","equipment":"elastiques","desc":"1. Tenez un haltère, un disque de barre ou tout autre objet lourd à deux mains, mais veillez à ce qu'il ne soit pas trop lourd et à pouvoir garder une bonne posture. 2. Penchez-vous en arrière jusqu'à former un angle de 45 degrés par rapport au sol. Pour un défi supplémentaire, décollez vos pieds du sol. 3. Faites pivoter vos bras d'un côté jusqu'à la hauteur de votre poitrine, touchez le sol pour un défi supplémentaire, puis faites de même de l'autre côté. Lorsque vous êtes revenu à votre position de départ après avoir effectué les deux côtés, cela compte pour 1 répétition.","tips":["Penchez-vous en arrière jusqu'à former un angle de"],"image":"https://wger.de/media/exercise-images/1193/70ca5d80-3847-4a8c-8882-c6e9e485e29e.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1195","wgerId":1195,"name":"Pas chassés + squats","muscle":"jambes","equipment":"none","desc":"Les pieds un peu plus écartés que la largeur des épaules et en restant bas pour imiter une position défensive, vous devez avancer avec votre jambe directrice et pousser avec votre jambe d'appui. Après trois pas chassés, faites pivoter votre corps de 180 degrés sur la jambe directrice (extérieure) et effectuez un squat. Continuez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1196","wgerId":1196,"name":"Exercices au mur","muscle":"jambes","equipment":"none","desc":"Exercices pour renforcer la musculature du genou et de la jambe. * Exercices latéraux au mur, marche - https://youtu.be/9RiTlJ6Mmek * Exercices latéraux au mur, ouverture - https://youtu.be/ADRlN8-Wfdg * Exercices latéraux au mur, croisement - https://youtu.be/hGH2sj0Tzu4","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1198","wgerId":1198,"name":"Rowing inversé","muscle":"bras","equipment":"none","desc":"Gardez le corps droit, rétractez vos omoplates et tirez votre poitrine vers la barre pour un entraînement efficace du dos et du haut du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1198/864906ac-4ac7-4e52-a886-c6bb97950a9f.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1200","wgerId":1200,"name":"Tibialis raises","muscle":"jambes","equipment":"none","desc":"1. Je me lève droit 2. Soulevez les boules de vos pieds, en vous reposant sur vos talons.","tips":["Je me lève droit","Soulevez les boules de vos pieds, en vous reposant sur vos talons"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1201","wgerId":1201,"name":"Squat du dragon","muscle":"jambes","equipment":"none","desc":"Commencez debout, les pieds écartés à la largeur des hanches. Croisez votre pied droit derrière vous vers le coin arrière gauche de la pièce tout en fléchissant les deux genoux. Revenez et répétez en alternant les côtés. Gardez vos hanches et vos épaules orientées vers l'avant pendant que vous croisez les pieds et fléchissez les genoux.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1202","wgerId":1202,"name":"Abduction de hanche en décubitus latéral","muscle":"jambes","equipment":"none","desc":"* Commencez allongé sur le côté, la jambe supérieure tendue et la jambe inférieure fléchie pour le soutien. * Soulevez votre jambe supérieure du sol * *(facultatif) -* Maintenez la position en haut Ressources : * Vidéo YouTube de 40 secondes : https://www.youtube.com/watch?v=g9FtnmsIYgI","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1203","wgerId":1203,"name":"Extensions des mollets, jambe gauche","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous au sol ou sur le bord d'une marche pour augmenter l'amplitude de mouvement. 2. Levez un pied. 3. Soulevez votre talon jusqu'à vous tenir sur la pointe des pieds. 4. *(variable)* Restez dans cette position pendant trois secondes 5. Redescendez lentement votre pied jusqu'à presque toucher le sol avec votre talon ; ne laissez pas claquer votre pied !","tips":["Tenez-vous au sol ou sur le bord d'une marche pour augmenter l'amplitude de mouvement","Levez un pied","Soulevez votre talon jusqu'à vous tenir sur la pointe des pieds","*(variable)* Restez dans cette position pendant trois secondes","Redescendez lentement votre pied jusqu'à presque toucher le sol avec votre talon ; ne laissez pas claquer votre pied !"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1205","wgerId":1205,"name":"Curl des poignets, haltères","muscle":"jambes","equipment":"elastiques","desc":"1. Assis sur un banc, saisissez l'haltère, les paumes tournées vers le haut et les mains écartées à la largeur des épaules. Posez vos avant-bras sur vos cuisses et laissez vos poignets dépasser au-delà de vos genoux. 2. Effectuez le mouvement en enroulant vos paumes et vos poignets vers votre visage. 3. (facultatif/variable) Marquez une pause en haut. 4. Revenez lentement à la position de départ.","tips":["Assis sur un banc, saisissez l'haltère, les paumes tournées vers le haut et les mains écartées à la largeur des épaules","Effectuez le mouvement en enroulant vos paumes et vos poignets vers votre visage","(facultatif/variable) Marquez une pause en haut","Revenez lentement à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1207","wgerId":1207,"name":"Coup de pied du scorpion","muscle":"jambes","equipment":"none","desc":"**Mettez-vous en position de pompe, les épaules directement au-dessus des mains et les pieds écartés à la largeur des hanches.** **Assurez-vous que votre corps forme une ligne droite de la tête aux talons.** **Ramenez maintenant votre genou droit vers votre poitrine. Tout en gardant le genou fléchi, levez votre jambe droite le plus haut possible, le bas de votre jambe droite pointant droit vers le haut.** **Faites maintenant pivoter vos hanches de sorte que votre pied droit passe au-dessus de votre jambe gauche.** **Continuez à pivoter et déplacez votre pied droit vers le sol jusqu'à être contraint de rouler sur l'extérieur de votre pied gauc","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1210","wgerId":1210,"name":"Superman avec bras en position T","muscle":"jambes","equipment":"none","desc":"Allongez-vous sur le ventre, les jambes plus écartées que la largeur des épaules et les pieds relevés. Vos bras sont tendus sur les côtés et forment un T avec le haut de votre corps, les paumes au sol. Soulevez maintenant le haut de votre corps, vos bras et vos jambes aussi haut que possible tout en gardant votre corps sous tension. Tournez vos pouces vers le plafond et rapprochez vos omoplates. Tout en gardant le haut de votre corps et tous vos membres en l'air, rapprochez vos jambes puis écartez-les de nouveau, en les maintenant constamment en l'air. Pour les répétitions restantes, ne bougez que vos jambes, en les ouvrant et en les fermant.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-260","wgerId":260,"name":"Sit-outs complets","muscle":"fessiers","equipment":"none","desc":"(A) Mettez-vous en position de planche haute, sur les mains et la pointe des pieds.(B) Reportez votre poids sur votre main gauche en tournant votre corps vers la droite ; fléchissez votre jambe droite derrière vous et tendez votre bras droit vers le haut. Revenez au centre et répétez de l'autre côté. Continuez en alternant les côtés.**Pour faciliter :** ne levez pas le bras après avoir fléchi la jambe derrière vous.**Pour intensifier :** tenez en équilibre, bras et jambe tendus, pendant deux temps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1215","wgerId":1215,"name":"Ange de neige inversé","muscle":"dos","equipment":"none","desc":"Allongez-vous à plat ventre, les bras tendus devant vous au sol et les jambes posées à plat. Levez vos deux bras et déplacez-les lentement vers vos côtés. Puis ramenez-les en arrière.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1241","wgerId":1241,"name":"Exercise Band Dorsiflexion","muscle":"jambes","equipment":"elastiques","desc":"Cet exercice utilise une bande d'exercice. Elle cible le Soleus et le Tibialis antérieur.","tips":["Cet exercice utilise une bande d'exercice. Elle cible le Soleus et le Tibialis antérieur."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1242","wgerId":1242,"name":"Flexion plantaire avec élastique","muscle":"jambes","equipment":"elastiques","desc":"La flexion plantaire avec élastique est un excellent moyen de faire le lien entre l'amplitude de mouvement en flexion plantaire et les extensions des mollets plus exigeantes en charge. Cela permet de renforcer les muscles du mollet, de solliciter le tendon d'Achille et d'améliorer l'amplitude de mouvement en flexion plantaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1218","wgerId":1218,"name":"Pompes sur les genoux","muscle":"epaules","equipment":"none","desc":"1. Commencez par vous agenouiller sur le sol, en gardant les genoux joints. Placez vos mains sur le sol devant vous, légèrement plus larges que la largeur des épaules. 2. Assurez-vous que votre corps forme une ligne droite de la tête aux genoux. Les mains doivent être positionnées sous les épaules. 3. Abaissez votre torse vers le sol en pliant les coudes tout en maintenant la stabilité du tronc. Les genoux restent en contact avec le sol. 4. Poussez à travers les mains pour remonter à la position de départ. Assurez-vous de maintenir une contraction des muscles de la poitrine, des épaules et des bras en haut du mouvement. 5. Effectuez le nombre","tips":["Commencez par vous agenouiller sur le sol, en gardant les genoux joints","Assurez-vous que votre corps forme une ligne droite de la tête aux genoux","Abaissez votre torse vers le sol en pliant les coudes tout en maintenant la stabilité du tronc","Poussez à travers les mains pour remonter à la position de départ","Effectuez le nombre souhaité de répétitions, en contrôlant le mouvement et en maintenant une bonne forme"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1219","wgerId":1219,"name":"Tractions australiennes","muscle":"epaules","equipment":"none","desc":"1. Allongez-vous sous une barre fixe ou une barre de suspension, positionnée à une hauteur appropriée. 2. Placez-vous sur le dos sous la barre, en saisissant la barre avec une prise en supination (paumes tournées vers vous). 3. Ajustez votre position pour que votre corps soit aligné de manière droite des pieds à la tête. Les bras doivent être complètement étendus, les épaules stabilisées, et les jambes alignées avec le reste du corps. 4. Fléchissez les coudes et tirez votre poitrine vers la barre, en contractant les muscles du dos. Imaginez que vous essayez de rapprocher vos omoplates l'une de l'autre. 5. Maintenez la contraction au sommet du","tips":["Allongez-vous sous une barre fixe ou une barre de suspension, positionnée à une hauteur appropriée","Placez-vous sur le dos sous la barre, en saisissant la barre avec une prise en supination (paumes tournées vers vous)","Ajustez votre position pour que votre corps soit aligné de manière droite des pieds à la tête","Fléchissez les coudes et tirez votre poitrine vers la barre, en contractant les muscles du dos","Maintenez la contraction au sommet du mouvement pendant un moment pour maximiser l'activation musculaire"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1714","wgerId":1714,"name":"Exercice pendulaire de l'épaule avec haltère","muscle":"epaules","equipment":"elastiques","desc":"1. Penchez-vous vers l'avant pour poser votre main sur une chaise ou un autre objet, en tenant un haltère dans l'autre main 2. Balancez doucement l'haltère selon un mouvement circulaire","tips":["Balancez doucement l'haltère selon un mouvement circulaire"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-2485","wgerId":2485,"name":"Stroke-and-Roll Drill","muscle":"epaules","equipment":"none","desc":"Poussez, nagez quelques coups, et chaque respiration roule complètement sur votre dos pendant 2-3 respirations, puis revenez au style libre. Cela vous apprend à faire pivoter votre corps en tant qu'unité plutôt que de simplement tourner la tête, et aide à éliminer la peur de ne pas avoir votre visage dans l'eau.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1234","wgerId":1234,"name":"Hip thrust à une jambe avec haltère","muscle":"fessiers","equipment":"elastiques","desc":"Le hip thrust à une jambe s'effectue en plaçant le haut du dos sur un banc de musculation, en levant une jambe et en étendant la hanche de l'autre jambe afin d'obtenir une contraction isolée du fessier. En travaillant chaque côté séparément, vous pouvez isoler complètement vos fessiers de manière unilatérale, ce qui procure un stimulus d'entraînement maximal.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1715","wgerId":1715,"name":"Rotation externe de l'épaule avec haltère","muscle":"epaules","equipment":"elastiques","desc":"1. Allongez-vous sur le côté en tenant un haltère dans votre main supérieure 2. Calez votre coude contre votre flanc et posez la main devant vous 3. Faites pivoter l'épaule de sorte que la main se relève 4. Redescendez la main","tips":["Allongez-vous sur le côté en tenant un haltère dans votre main supérieure","Calez votre coude contre votre flanc et posez la main devant vous","Faites pivoter l'épaule de sorte que la main se relève","Redescendez la main"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1275","wgerId":1275,"name":"Plantarflexion Stretch with Band","muscle":"jambes","equipment":"elastiques","desc":"Cet étirement concerne les chevilles, ainsi que le tibial antérieur.","tips":["Cet étirement concerne les chevilles, ainsi que le tibial antérieur."],"image":"https://wger.de/media/exercise-images/1275/0652d306-93eb-42f0-b564-7c3261ea809a.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1223","wgerId":1223,"name":"Claps over the head","muscle":"epaules","equipment":"none","desc":"Tenez-vous debout, les pieds écartés de la largeur des épaules. Levez les bras et tapez sur votre tête","tips":["Tenez-vous debout, les pieds écartés de la largeur des épaules. Levez les bras et tapez sur votre tête"],"image":"https://wger.de/media/exercise-images/1223/bf20836a-23b0-4f50-8b98-cfdd97684527.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1224","wgerId":1224,"name":"Drag curls aux haltères","muscle":"bras","equipment":"elastiques","desc":"Tenez un haltère dans chaque main, les paumes tournées vers l'avant. Tirez vos coudes vers l'arrière et montez les haltères jusqu'à la hauteur de votre poitrine. Redescendez lentement l'haltère et répétez l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-369","wgerId":369,"name":"Extension des jambes (leg extension)","muscle":"jambes","equipment":"none","desc":"L'extension des jambes est un exercice de musculation avec résistance qui cible les quadriceps des jambes. L'exercice se réalise à l'aide d'une machine appelée machine à extension des jambes. Il existe différents fabricants de ces machines et chacune est légèrement différente. La plupart des salles de sport et de musculation disposent de cette machine dans leurs installations. L'extension des jambes est un exercice isolé qui cible un groupe musculaire spécifique, les quadriceps. Il ne doit pas être considéré comme un entraînement complet des jambes, comme le squat ou le soulevé de terre. L'exercice consiste à fléchir la jambe au niveau du gen","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/369/78c915d1-e46d-4d30-8124-65d68664c3ef.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1716","wgerId":1716,"name":"Pompe inclinée pour les épaules","muscle":"epaules","equipment":"barre","desc":"1. Placez vos mains sur le banc en position de pompe 2. Éloignez votre poitrine du banc pour écarter vos omoplates 3. **En gardant les coudes tendus**, abaissez votre poitrine vers le banc de sorte que vos omoplates se rapprochent 4. Éloignez de nouveau votre poitrine du banc","tips":["Placez vos mains sur le banc en position de pompe","Éloignez votre poitrine du banc pour écarter vos omoplates","**En gardant les coudes tendus**, abaissez votre poitrine vers le banc de sorte que vos omoplates se rapprochent","Éloignez de nouveau votre poitrine du banc"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1225","wgerId":1225,"name":"Curls biceps larges aux haltères","muscle":"bras","equipment":"elastiques","desc":"Tenez un haltère dans chaque main, les mains écartées un peu plus que la largeur des épaules et les paumes tournées vers l'avant. Fléchissez vos coudes et montez les haltères jusqu'à vos épaules. Redescendez lentement et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1225/39a0b7e7-9780-425d-84f5-56d10d1690ac.gif","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1226","wgerId":1226,"name":"Curl biceps à développé aux haltères","muscle":"bras","equipment":"elastiques","desc":"Fléchissez vos coudes et montez les haltères jusqu'à vos épaules. Poussez les haltères au-dessus de votre tête tout en faisant pivoter vos bras pour que vos paumes soient tournées vers l'avant. Inversez le mouvement pour redescendre. Répétez l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1226/a6154dbd-67a0-4a36-8748-0f5af3865e83.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1209","wgerId":1209,"name":"Pompe trois points à largeur d'épaules","muscle":"pectoraux","equipment":"none","desc":"Mettez-vous en position de pompe, les épaules directement au-dessus des mains et les pieds écartés de la largeur des hanches. Rentrez votre nombril vers votre colonne vertébrale et contractez vos abdominaux. Levez votre pied gauche d'environ cinq centimètres du sol. Pointez vos orteils vers le bas. Ne bougez pas vos hanches. Votre corps forme une ligne droite de la tête aux talons pendant tout l'exercice. Pliez maintenant les coudes, abaissez votre poitrine vers le sol et repoussez-vous vers le haut. Répétez l'exercice de l'autre côté.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1227","wgerId":1227,"name":"Rowing pour deltoïdes postérieurs aux haltères","muscle":"epaules","equipment":"elastiques","desc":"Tenez un haltère dans chaque main. Penchez-vous au niveau des hanches pour rendre votre dos presque parallèle au sol. Laissez vos bras pendre vers le bas. Gardez vos bras dans l'alignement de vos épaules. Fléchissez et levez vos coudes vers les côtés jusqu'à ce que vos bras soient parallèles au sol. Redescendez lentement et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1227/57415c3c-2963-4130-9f6f-79f6a96113b6.gif","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1217","wgerId":1217,"name":"Pompe sur les doigts","muscle":"pectoraux","equipment":"none","desc":"1. Position des mains : - Commencez en position de planche, les mains directement sous les épaules. - Écartez largement vos doigts et placez-les fermement au sol. 2. Placement des doigts : - Décollez progressivement vos paumes du sol en reportant le poids sur vos doigts. - Veillez à répartir la charge de manière uniforme entre le bout de vos doigts et vos pouces. 3. Alignement du corps : - Maintenez une ligne droite de la tête aux talons afin de solliciter votre sangle abdominale. - Gardez votre corps dans une position contrôlée et stable tout au long de l'exercice. 4. Phase de descente : - Pliez lentement les coudes en abaissant votre poitri","tips":["Position des mains : - Commencez en position de planche, les mains directement sous les épaules","Placement des doigts : - Décollez progressivement vos paumes du sol en reportant le poids sur vos doigts","Alignement du corps : - Maintenez une ligne droite de la tête aux talons afin de solliciter votre sangle abdominale","Phase de descente : - Pliez lentement les coudes en abaissant votre poitrine vers le sol","Phase de poussée : - Poussez sur le bout de vos doigts pour tendre vos bras et revenir à la position de départ"],"image":"https://wger.de/media/exercise-images/1217/590e65db-de60-4727-b7eb-55f80af56043.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1228","wgerId":1228,"name":"Développé couché serré aux haltères","muscle":"pectoraux","equipment":"elastiques","desc":"Allongez-vous sur le dos sur un banc plat. Tenez un haltère dans chaque main. Levez vos bras vers le plafond, les paumes se faisant face et les haltères pressés l'un contre l'autre. Abaissez lentement les haltères vers votre poitrine, puis poussez-les lentement vers le haut. Répétez l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-599","wgerId":599,"name":"Arraché","muscle":"epaules","equipment":"barre","desc":"Tenez-vous debout, les pieds écartés à la largeur des hanches et les tibias contre la barre. Saisissez la barre à une largeur double de celle des épaules et, en gardant le bas du dos plat, poussez vos talons dans le sol pour commencer à soulever la barre. Lorsqu'elle est au-dessus de vos genoux, étendez explosivement vos hanches et haussez vos épaules. Laissez l'élan emporter la charge au-dessus de la tête.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1216","wgerId":1216,"name":"Tractions de recrutement","muscle":"jambes","equipment":"none","desc":"Repérez quelques tailles de réglettes spécifiques sur une poutre d'entraînement, placez-vous en suspension en dessous avec la poutre au-dessus de votre tête, et tirez avec un effort maximal, un bras à la fois, pendant 3 à 5 secondes. Pour vous positionner, installez-vous avec un grand angle au coude (120 à 150 degrés) et non en pleine extension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1233","wgerId":1233,"name":"Étirement des biceps debout à droite","muscle":"epaules","equipment":"none","desc":"Tenez-vous debout avec votre bras droit près d'un mur. Tendez votre bras droit et placez votre main droite sur le mur, puis tournez doucement votre corps vers la gauche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1233/d7d6f9e1-7834-4cca-bd3b-f9def33ff44d.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1230","wgerId":1230,"name":"Étirement des triceps à gauche","muscle":"bras","equipment":"none","desc":"Placez votre main gauche dans votre dos, utilisez votre main droite pour saisir votre coude gauche et tirez-le doucement. Maintenez cette position pendant quelques secondes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1230/9fd1e2fd-f2c4-432d-b3ae-5e5f24085777.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1274","wgerId":1274,"name":"Sitting Calf Stretch (Dorsiflexion)","muscle":"jambes","equipment":"none","desc":"C'est un étirement léger pour le mollet qui est idéal pour la rééducation.","tips":["C'est un étirement léger pour le mollet qui est idéal pour la rééducation."],"image":"https://wger.de/media/exercise-images/1274/bcffdf52-3c36-4b0c-b787-fb84f20bf82d.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-142","wgerId":142,"name":"Rotation externe à la poulie","muscle":"epaules","equipment":"none","desc":"Étapes : 1. Commencez par fixer un élastique autour d'un poteau ou dans un endroit sûr où il ne se détachera pas, à hauteur du coude. 2. Placez-vous sur le côté de l'élastique et, avec la main opposée à l'élastique, tendez le bras et saisissez la poignée. 3. Ramenez l'élastique vers votre poitrine en gardant le coude plié à un angle de 90 degrés, puis tournez lentement votre bras vers l'arrière de manière à effectuer une rotation externe. 4. Continuez vers l'extérieur aussi loin que possible afin de ressentir un étirement dans vos épaules, maintenez la position le temps d'un décompte, puis revenez à la position de départ. 5. Répétez pour auta","tips":["Placez-vous sur le côté de l'élastique et, avec la main opposée à l'élastique, tendez le bras et saisissez la poignée","Ramenez l'élastique vers votre poitrine en gardant le coude plié à un angle de","Répétez pour autant de répétitions et de séries que vous le souhaitez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1231","wgerId":1231,"name":"Étirement des triceps à droite","muscle":"bras","equipment":"none","desc":"Placez votre main droite dans votre dos, utilisez votre main gauche pour saisir votre coude droit et tirez-le doucement. Maintenez cette position pendant quelques secondes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1231/b10457ce-5fa5-4d20-a32f-3c7100c6a9d9.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1232","wgerId":1232,"name":"Étirement des biceps debout à gauche","muscle":"epaules","equipment":"none","desc":"Tenez-vous debout avec votre bras gauche près d'un mur. Tendez votre bras gauche et placez votre main gauche sur le mur, puis tournez doucement votre corps vers la droite.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1232/2b6de046-5806-49e3-bf36-b6fae16af021.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1117","wgerId":1117,"name":"Rowing assis à la poulie","muscle":"dos","equipment":"none","desc":"1. Asseyez-vous sur la machine, les pieds bien posés, un peu plus écartés que la largeur des épaules. Poussez sur les talons et contractez les fessiers. Saisissez la poignée du câble. 2. Redressez-vous bien droit, les genoux légèrement fléchis. Contractez les abdominaux et le bas du dos afin de maintenir votre torse perpendiculaire au sol. 3. Roulez les épaules vers l'arrière et vers le bas. Resserrez-les l'une vers l'autre pendant le tirage, comme si vous pinciez un crayon entre vos omoplates. En faisant cela, tirez la poignée vers vous jusqu'à ce qu'elle arrive juste au-dessus de votre nombril. 4. Marquez ici une pause un instant avant de r","tips":["Asseyez-vous sur la machine, les pieds bien posés, un peu plus écartés que la largeur des épaules","Redressez-vous bien droit, les genoux légèrement fléchis","Roulez les épaules vers l'arrière et vers le bas","Marquez ici une pause un instant avant de relâcher la poignée, en continuant de serrer les omoplates","Répétez le mouvement"],"image":"https://wger.de/media/exercise-images/1117/2555c4c3-a84d-47db-b83b-cbf721f12e45.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1270","wgerId":1270,"name":"Écarté à la poulie basse","muscle":"pectoraux","equipment":"none","desc":"Réglez la machine à poulie : positionnez la poulie au réglage le plus bas possible. Choisissez vos poignées : vous pouvez utiliser des poignées à prise neutre (paumes se faisant face) ou des poignées droites selon votre préférence. La prise neutre est peut-être plus douce pour vos poignets. Tenez-vous avec une bonne posture : tenez-vous debout, les pieds écartés de la largeur des épaules, les genoux légèrement fléchis et la sangle abdominale engagée. Conservez une légère cambrure dans le bas du dos tout au long de l'exercice. Saisissez les poignées : prenez les poignées avec la prise choisie et reculez d'un petit pas ou deux jusqu'à obtenir u","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1656","wgerId":1656,"name":"Développé poitrine à la poulie, en décliné","muscle":"pectoraux","equipment":"none","desc":"Développé poitrine à un bras réalisé à la machine à poulie. Utilisez l'autre bras pour stabiliser le poids du corps afin de vous concentrer sur la force de la poussée plutôt que sur l'équilibre du corps. Commencez avec la main aussi près que possible de la poitrine, puis poussez contre le câble selon une légère inclinaison vers le bas, en visant le centre de votre poitrine.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1717","wgerId":1717,"name":"Neck extension","muscle":"bras","equipment":"none","desc":"Exercice triceps unilatéral avec le dos à la poulie, avec la poulie en haut","tips":["Exercice triceps unilatéral avec le dos à la poulie, avec la poulie en haut"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1718","wgerId":1718,"name":"Remo alto polea alta","muscle":"abdos","equipment":"none","desc":"Rangée de poulies haute avec support à l'aide d'une seule poignée","tips":["Rangée de poulies haute avec support à l'aide d'une seule poignée"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1238","wgerId":1238,"name":"Équilibre de la grenouille","muscle":"epaules","equipment":"none","desc":"Position de départ : Tenez-vous debout, les pieds écartés de la largeur des épaules et les orteils pointés vers l'avant, face à un mur ou à un banc pour vous soutenir si nécessaire. Pliez les genoux en position de squat. Placez vos mains au sol devant vous, écartées de la largeur des épaules, les doigts bien écartés. Assurez-vous que vos coudes sont sous vos épaules et que votre corps forme une ligne droite de la tête aux talons. Phase ascendante : Poussez avec vos pieds et vos mains pour soulever votre corps du sol. Tendez vos jambes et vos bras en gardant votre corps aligné. Contractez votre sangle abdominale et vos fessiers pour maintenir ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1239","wgerId":1239,"name":"Étirement des mollets debout","muscle":"jambes","equipment":"none","desc":"Cet étirement cible le gastrocnémien (le principal muscle du mollet de la jambe, qui fléchit le genou et le pied). Il est facile à réaliser n'importe où. Il vous suffit d'un mur ou d'une chaise.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1239/5026373a-a7b4-4e26-a0aa-c46634205196.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1092","wgerId":1092,"name":"Entraînement au sac de frappe","muscle":"epaules","equipment":"none","desc":"L'entraînement au sac de frappe améliore la définition musculaire des deltoïdes, des deltoïdes postérieurs, des triceps et des biceps, tout en constituant un excellent exercice cardio.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1240","wgerId":1240,"name":"Standing Soleus Stretch","muscle":"jambes","equipment":"none","desc":"Cet étirement cible la partie Soleus de votre mollet. Il peut être effectué avec un mur ou une chaise.","tips":["Cet étirement cible la partie Soleus de votre mollet. Il peut être effectué avec un mur ou une chaise."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1243","wgerId":1243,"name":"Extension des mollets sur deux jambes","muscle":"jambes","equipment":"none","desc":"L'extension des talons sur deux jambes est importante pour renforcer et développer le contrôle et la stabilité autour de la cheville et du genou, et pour assurer l'équilibre et le contrôle de la hanche et du bassin.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1243/53d4fabe-c994-4907-873f-8d82813a9832.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1244","wgerId":1244,"name":"Exercice de yoga : la vache et le chat","muscle":"epaules","equipment":"none","desc":"Mettez-vous d'abord à quatre pattes. Les mains sont placées sous les épaules. Les doigts sont largement écartés et garantissent une position stable. L'idéal est de répartir le poids de la partie avant de votre corps sur vos pouces et vos index. Placez maintenant vos jambes écartées de la largeur des hanches sur le tapis de yoga. Vos cuisses doivent être à la verticale, sous vos hanches. Veillez à ce que votre poids soit réparti de manière égale entre vos mains et vos genoux. Votre tête est dans le prolongement de votre colonne vertébrale et votre regard est dirigé vers le tapis. Votre dos est en position neutre. Inspirez profondément et comme","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1245","wgerId":1245,"name":"Front Lever","muscle":"dos","equipment":"none","desc":"The front lever is a figure where the body is kept in a horizontal position parallel to the floor.","tips":["The front lever is a figure where the body is kept in a horizontal position parallel to the floor."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1246","wgerId":1246,"name":"Roll out au TRX","muscle":"abdos","equipment":"none","desc":"Tenez les poignées dans vos mains, tendez vos bras et gardez-les parallèles à hauteur de poitrine. Le mouvement à effectuer consiste à ouvrir vos bras dans l'alignement de vos épaules tout en penchant votre corps vers l'avant. Essayez de ne pas étendre vos épaules au-delà de 90° et gardez vos abdominaux et vos fessiers contractés. Muscles sollicités : le transverse de l'abdomen, le grand droit de l'abdomen et les muscles érecteurs du rachis.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1248","wgerId":1248,"name":"Ice cream maker","muscle":"dos","equipment":"none","desc":"Depuis la phase finale d'une traction, nous nous repoussons vers l'arrière avec les épaules jusqu'à atteindre la position de front lever. À partir de là, nous nous tirons de nouveau vers le haut pour revenir à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1252","wgerId":1252,"name":"Front lever pull-up","muscle":"bras","equipment":"none","desc":"in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.","tips":["in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1214","wgerId":1214,"name":"Front lever groupé","muscle":"epaules","equipment":"none","desc":"Les muscles sollicités lors du front lever, les plus soumis à la contrainte, sont principalement les extenseurs tels que : le grand dorsal, le grand rond, le deltoïde postérieur et le chef long du biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1259","wgerId":1259,"name":"Obliques au TRX","muscle":"abdos","equipment":"none","desc":"1. Placez vos pieds dans les sangles et adoptez une position de planche haute, les mains directement sous les épaules. 2. Ramenez vos genoux vers votre coude droit, puis repoussez-les vers l'extérieur et vers le centre.","tips":["Placez vos pieds dans les sangles et adoptez une position de planche haute, les mains directement sous les épaules","Ramenez vos genoux vers votre coude droit, puis repoussez-les vers l'extérieur et vers le centre"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1260","wgerId":1260,"name":"Curl marteau au TRX","muscle":"bras","equipment":"none","desc":"Placez les poignées comme si elles étaient le prolongement des sangles. Nous positionnerons nos bras tendus vers l'avant et notre corps penché vers l'arrière, complètement droit. Les biceps s'activeront lorsque vous plierez les coudes pour rapprocher votre corps des sangles. Le mouvement de contraction se terminera par un léger mouvement des mains vers l'extérieur, du fait de la prise utilisée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1261","wgerId":1261,"name":"Curl biceps gorille au TRX","muscle":"bras","equipment":"none","desc":"Nous nous tiendrons face aux sangles du TRX et les saisirons les poings se faisant face, dirigés vers l'avant, les bras complètement tendus et écartés d'environ la largeur des épaules. Nous garderons notre corps droit, incliné vers l'arrière, comme dans les exercices précédents, puisque nous soulèverons notre corps vers les sangles du TRX en activant nos biceps. Notre corps sera droit, les pieds à plat sur le sol. Cette fois, nous placerons nos bras ouverts sur les côtés et à hauteur de poitrine. Le mouvement à réaliser est une contraction vers la poitrine. Pour cela, nous plierons les coudes afin que, en activant nos biceps, nous puissions t","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1262","wgerId":1262,"name":"Curl biceps à un bras au TRX","muscle":"bras","equipment":"none","desc":"Étape 1 : Tenez-vous confortablement et saisissez les poignées du système de suspension. Étape 2 : Penchez-vous vers l'arrière en reportant votre poids sur un bras, la colonne vertébrale en position neutre. Étape 3 : Effectuez lentement un curl pour amener le poids de votre corps vers le haut. Tournez le bras en supination et contractez à l'approche de la position finale. Étape 4 : Redescendez et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1263","wgerId":1263,"name":"Pont arrière","muscle":"jambes","equipment":"none","desc":"Allongez-vous au sol, le dos posé sur le sol et les jambes pliées, les pieds à plat sur le sol, en laissant environ 20 cm entre vos pieds et vos fessiers. Vos mains restent à plat sur le sol, pressées contre vos oreilles, les doigts pointés vers vos orteils. Vos coudes sont pliés et pointés vers le plafond. C'est la position de départ. Poussez maintenant vos hanches aussi haut que possible en décollant votre corps du sol, et continuez à pousser sur vos mains en tendant vos coudes et vos genoux, jusqu'à ce que votre dos soit entièrement cambré (pont lombaire). Votre tête se décolle également du sol et doit être au niveau de vos coudes, le rega","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1266","wgerId":1266,"name":"Extension des triceps au TRX","muscle":"bras","equipment":"none","desc":"Fixez le TRX ou un autre système de suspension en hauteur, les poignées pendant à hauteur de poitrine ou légèrement plus bas. Faites des essais pour trouver la hauteur qui vous permet de vous installer au mieux. Tenez-vous devant les poignées et saisissez-les paumes vers le bas. Contractez vos abdominaux, serrez vos fessiers, inspirez et penchez-vous vers l'avant en décollant vos talons du sol. Gardez vos coudes tendus. Inspirez de nouveau et abaissez-vous lentement en pliant les coudes. Descendez jusqu'à ce que vos coudes forment un angle de 90 degrés (jusqu'au point où vos poignets se trouvent au-dessus de vos coudes). Maintenez la position","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1269","wgerId":1269,"name":"Dips au TRX","muscle":"bras","equipment":"none","desc":"Commencez les mains sur le système de suspension et les pieds au sol. Vos mains doivent être sous vos épaules, les pieds légèrement vers l'avant. Abaissez-vous en amenant vos hanches entre les poignées et en pliant les coudes. Tendez les coudes pour revenir à la position de départ et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1273","wgerId":1273,"name":"Pullover","muscle":"pectoraux","equipment":"elastiques","desc":"Doublé comme un exercice du dos et de la poitrine, le pull haltère peut entraîner à la fois vos pectoraux et vos lats.","tips":["Doublé comme un exercice du dos et de la poitrine, le pull haltère peut entraîner à la fois vos pectoraux et vos lats."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1280","wgerId":1280,"name":"Tirage vertical en prise serrée pour les biceps","muscle":"bras","equipment":"none","desc":"Sur une machine de tirage vertical, tenez la barre en gardant vos mains relativement rapprochées. Utilisez une prise en supination (c'est-à-dire que le dos de votre main doit être tourné vers la machine). Tirez ensuite la barre en ligne droite vers le sol. Veillez à ce que vos biceps soient les principaux moteurs du mouvement. Vous sentirez probablement vos épaules et votre grand dorsal travailler, mais assurez-vous que vos biceps travaillent davantage.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1282","wgerId":1282,"name":"Isometria trazioni impugnatura inversa","muscle":"dos","equipment":"none","desc":"Trazioni in isometria con impugnatura inversa","tips":["Trazioni in isometria con impugnatura inversa"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1283","wgerId":1283,"name":"Rowing avec haltères incliné, poitrine soutenue","muscle":"bras","equipment":"barre","desc":"Réglez un banc inclinable à un angle de 45 degrés. Allongez-vous sur le ventre, la tête juste au-dessus du bord du banc. Saisissez un haltère dans chaque main et installez-vous avec une bonne posture : la sangle abdominale et le grand dorsal engagés, les épaules en position neutre. Tirez les haltères vers le haut de l'abdomen et contractez le dos au sommet de la répétition. Enfin, redescendez les haltères à la position de départ et répétez jusqu'à avoir effectué toutes les répétitions.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1283/e7262f70-7512-408a-8d00-4c499ef632fc.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1284","wgerId":1284,"name":"Pompe pseudo planche","muscle":"epaules","equipment":"none","desc":"Vous devez avoir la ligne des épaules en avant de vos poignets et effectuer une pompe en maintenant les épaules dans la même position.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1285","wgerId":1285,"name":"Talons fesses","muscle":"jambes","equipment":"none","desc":"Touchez vos talons jusqu'aux fesses, tout en restant statique ou en mouvement","tips":["Touchez vos talons jusqu'aux fesses, tout en restant statique ou en mouvement"],"image":"https://wger.de/media/exercise-images/1285/1ab8005d-41e4-4505-9a7d-5277d59bb3cd.jpg.400x400_q85.jpg","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1286","wgerId":1286,"name":"Planche dynamique","muscle":"abdos","equipment":"none","desc":"1. Commencez en position de planche, avec vos mains directement sous vos épaules et vos pieds écartés à la largeur des hanches. 2. Contractez vos abdominaux pour maintenir votre corps en ligne droite de la tête aux pieds. 3. À partir de cette position, pliez légèrement les genoux et sautez avec les deux pieds vers l'intérieur, en les rapprochant de votre tronc autant que possible. 4. Dès que vos pieds touchent le sol, poussez avec force pour sauter à nouveau et revenir à la position de planche initiale. 5. Continuez à répéter ce mouvement de saut, en gardant le contrôle et en maintenant la stabilité de votre tronc tout au long de l'exercice. ","tips":["Contractez vos abdominaux pour maintenir votre corps en ligne droite de la tête aux pieds","Gardez votre regard fixé sur le sol pour maintenir un bon alignement de la colonne vertébrale"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1287","wgerId":1287,"name":"Élévations vers le plafond","muscle":"abdos","equipment":"none","desc":"Pour réaliser cet exercice, allongez-vous sur le dos, les bras tendus au-dessus de la tête. Contractez ensuite vos abdominaux et décollez votre torse du sol tout en tendant vos bras vers le plafond afin d'atteindre le plus haut possible. Revenez lentement à la position de départ en contrôlant le mouvement. Ces élévations renforcent les muscles abdominaux et améliorent la souplesse de la colonne vertébrale. Elles peuvent être intégrées à diverses routines d'entraînement pour travailler la force et la stabilité de la sangle abdominale.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1288","wgerId":1288,"name":"Planche latérale dynamique","muscle":"abdos","equipment":"none","desc":"La planche latérale dynamique consiste à se positionner sur le côté, en appui sur un coude et sur le côté du pied, puis à abaisser et relever les hanches tout en gardant le corps en ligne droite.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1289","wgerId":1289,"name":"Curls avec haltères assis","muscle":"bras","equipment":"elastiques","desc":"Les curls avec haltères assis sont un exercice efficace pour les biceps qui isole les muscles en stabilisant le haut du corps, ce qui réduit l'élan susceptible de nuire à l'efficacité de l'exercice. Cet exercice se réalise assis, avec un haltère dans chaque main, en se concentrant sur un mouvement contrôlé afin de maximiser la sollicitation des biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1290","wgerId":1290,"name":"Curl à la barre en prise inversée","muscle":"bras","equipment":"barre","desc":"Tenez la barre en prise pronation (paumes vers le bas), les mains écartées d'environ la largeur des épaules. Assurez-vous que votre dos est droit, les épaules légèrement tirées en arrière et les bras complètement tendus. Fléchissez les bras pour ramener la barre vers votre poitrine dans un mouvement contrôlé, en gardant les coudes près du corps. Le mouvement doit être fluide, sans élan ni balancement. Une fois la barre au niveau de la poitrine, marquez une brève pause pour maximiser la contraction des biceps et des avant-bras. Abaissez lentement la barre jusqu'à la position de départ dans un mouvement contrôlé, en tendant complètement les bra","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1290/c05818bf-1c81-46df-9f24-42e354265388.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1292","wgerId":1292,"name":"Reverse-grip pull-ups","muscle":"bras","equipment":"none","desc":"Pull-ups sur la barre avec vos pouces pointés vers l'extérieur.","tips":["Pull-ups sur la barre avec vos pouces pointés vers l'extérieur."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1293","wgerId":1293,"name":"One armed push-ups","muscle":"pectoraux","equipment":"none","desc":"Effectuez des pompes d'une main, en alternant les côtés","tips":["Effectuez des pompes d'une main, en alternant les côtés"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1662","wgerId":1662,"name":"Extension des triceps à la poulie - rotation interne","muscle":"bras","equipment":"none","desc":"Exercice à un bras, le câble tenu au niveau de l'épaule opposée et le coude fléchi. Tournez vers le câble, puis tendez le coude en travers du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1657","wgerId":1657,"name":"Curl au pupitre - rotation interne","muscle":"bras","equipment":"elastiques","desc":"Curl à un bras qui peut être réalisé avec un haltère et un banc à pupitre (banc Larry Scott), ou avec une machine à curl pupitre. Tournez le corps vers la charge.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1302","wgerId":1302,"name":"JM Press","muscle":"bras","equipment":"barre","desc":"Le JM press maintient vos épaules immobiles et repose sur la flexion et l'extension du coude pour déplacer la charge grâce à la force de vos triceps. Cela signifie que vous profitez de tous les avantages des meilleurs exercices de renforcement des triceps sans surmener cette articulation fragile qu'est l'épaule. Un grand classique, gagnant sur tous les plans !","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1303","wgerId":1303,"name":"Rowing Helms","muscle":"dos","equipment":"elastiques","desc":"Installation : Placez votre poitrine sur l'extrémité d'un banc, en utilisant une serviette ou tout autre objet rembourré pour protéger votre poitrine. Votre poitrine doit être en contact avec le banc au niveau de la ligne des mamelons. Votre dos doit être presque parallèle au sol. Exécution : Au début de l'exercice, concentrez-vous sur le fait de tirer vos coudes vers l'arrière jusqu'à ressentir une tension maximale dans le grand dorsal. Si vous souhaitez solliciter aussi les trapèzes pendant l'exercice, relâchez vos omoplates lorsque les charges pendent vers le bas, puis rapprochez-les au moment où vous commencez la répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1304","wgerId":1304,"name":"Rowing Meadows","muscle":"dos","equipment":"barre","desc":"Le rowing Meadows est un tirage unilatéral réalisé avec un montage landmine, en prise pronation et avec une position décalée des pieds. Penchez votre torse vers l'avant et saisissez la barre. Posez l'autre avant-bras sur la jambe avant. Amorcez le mouvement en poussant le coude vers l'arrière tout en rétractant l'omoplate. Gardez l'épaule qui travaille basse. Tirez en direction de votre hanche arrière jusqu'à ce que le coude arrive au niveau de votre torse.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1307","wgerId":1307,"name":"Planche frontale","muscle":"abdos","equipment":"none","desc":"La planche est un exercice au poids du corps. Mouvement polyvalent, la planche ne cible pas seulement vos abdominaux, mais aussi la colonne vertébrale et les hanches. La planche renforce et raffermit l'ensemble de votre corps, améliore votre posture et votre équilibre, réduit la masse grasse et peut contribuer à stimuler votre métabolisme. Des exercices comme la « position de la planche » aident à renforcer l'endurance des muscles abdominaux stabilisateurs. Elle peut également aider à soulager les douleurs dorsales liées à un affaiblissement de la fonction des muscles stabilisateurs du corps. La planche est un exercice polyvalent qui sollicit","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1668","wgerId":1668,"name":"Extension Triceps Poulie Basse à Un Bras","muscle":"bras","equipment":"none","desc":"Réglez la poulie au bas de la machine à câble et saisissez-la \\*\\*sans utiliser d'accessoire\\*\\*. \\*\\*Étendez le câble directement au-dessus de votre tête. Tout en gardant votre dos droit et votre bras supérieur immobile, abaissez le câble derrière votre tête jusqu'à ce que vous sentiez un bon étirement dans vos triceps, puis étendez-le à nouveau vers le haut jusqu'à ce que votre \\*\\*coude soit verrouillé (ou complètement tendu).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-2486","wgerId":2486,"name":"Recovery Bobbing","muscle":"abdos","equipment":"none","desc":"Même mouvement que le Bobbing Exhale Drill, mais fait dans une eau légèrement plus profonde (de sorte que vous ne touchez pas le fond) et à un rythme plus lent et plus détendu — considérez-le comme un exercice de récupération/réinitialisation plutôt que comme un exercice difficile. Utilisez-le entre les exercices plus difficiles pour réinitialiser votre rythme respiratoire et vous calmer si vous vous sentez pressé ou désynchronisé.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1666","wgerId":1666,"name":"Curl - épaule surélevée","muscle":"bras","equipment":"elastiques","desc":"Placez le coude de manière à ce qu'il soit à peu près au niveau de l'épaule. Fléchissez le bras pour ramener la charge vers votre épaule. Concentrez-vous sur l'étirement pendant la phase excentrique du curl.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1294","wgerId":1294,"name":"Single-leg hamstring curl","muscle":"jambes","equipment":"none","desc":"Plus précisément, les muscles impliqués sont : le biceps fémoral, le semimembranosus et le semitendinosus.","tips":["Plus précisément, les muscles impliqués sont : le biceps fémoral, le semimembranosus et le semitendinosus."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1314","wgerId":1314,"name":"Jumping jack HD","muscle":"jambes","equipment":"none","desc":"Le jumping jack est un exercice pliométrique. La pliométrie regroupe des mouvements aérobiques explosifs qui augmentent la vitesse, la rapidité et la puissance, et qui sollicitent l'ensemble du corps. Le jumping jack cible les bras, les épaules, les abdominaux, les muscles des hanches et les fléchisseurs de hanche, et fait aussi travailler les cuisses, les tendons du genou et les quadriceps. Les sauts sont bénéfiques pour la santé car ils associent travail cardiovasculaire et renforcement musculaire. Comme les sauts font monter le rythme cardiaque, ils peuvent aussi améliorer votre condition cardiovasculaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1380","wgerId":1380,"name":"Pull-apart avec élastique","muscle":"jambes","equipment":"elastiques","desc":"* Tiens l'élastique avec les bras tendus devant toi, à hauteur des épaules. * Garde les coudes légèrement fléchis, mais fixes. * Tire l'élastique vers l'extérieur en écartant les bras jusqu'à ce qu'il touche ou approche ta poitrine. * Ramène lentement les bras à la position initiale en contrôlant la tension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1353","wgerId":1353,"name":"Développé serré aux haltères (hex press)","muscle":"pectoraux","equipment":"elastiques","desc":"* Engagez les muscles * Placez vos pieds bien écartés * Mouvement contrôlé * Mouvement lent * Ramenez les charges vers le bas de votre poitrine / votre ventre","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1388","wgerId":1388,"name":"Soulevé de terre roumain sur une jambe","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous droit et tenez des charges dans les deux mains si vous utilisez du poids. 2. Gainez vos abdominaux et décollez une jambe du sol. 3. Gardez le dos droit, basculez au niveau des hanches en abaissant votre torse vers l'avant, en veillant à ne pas faire pivoter vos hanches. 4. Descendez jusqu'à sentir un étirement dans l'ischio-jambier de votre jambe d'appui, puis revenez en position debout. Répétez des deux côtés.","tips":["Tenez-vous droit et tenez des charges dans les deux mains si vous utilisez du poids","Gainez vos abdominaux et décollez une jambe du sol","Descendez jusqu'à sentir un étirement dans l'ischio-jambier de votre jambe d'appui, puis revenez en position debout"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1318","wgerId":1318,"name":"Montées de genoux sautées HD","muscle":"abdos","equipment":"none","desc":"Vous pouvez utiliser cet exercice aussi bien comme échauffement dynamique avant l'entraînement que l'ajouter à votre routine de cardio pour brûler des graisses. Les montées de genoux sautées sont un exercice pliométrique. La pliométrie regroupe des mouvements aérobiques explosifs qui augmentent la vitesse, la rapidité et la puissance, et qui sollicitent l'ensemble du corps. Les montées de genoux sautées ciblent les obliques, les muscles des jambes, les muscles des hanches et les fléchisseurs de hanche, et font aussi travailler les cuisses, les tendons du genou, les quadriceps et les épaules. Les sauts sont bénéfiques pour la santé car ils ass","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1320","wgerId":1320,"name":"Dips sur banc au sol HD","muscle":"bras","equipment":"none","desc":"Les dips triceps au sol sont un exercice polyarticulaire car ils sollicitent plusieurs groupes musculaires simultanément. Bien que cet exercice au poids du corps cible principalement les triceps, il fait aussi travailler vos pectoraux et l'avant de vos épaules. Les dips triceps au sol sont l'un des exercices les plus efficaces pour augmenter la force des bras et développer une musculature sèche au niveau des bras. Les dips triceps au sol sont un exercice en chaîne cinétique fermée, ce qui signifie que vous effectuez les mouvements autour d'un point fixe. Cela augmente la force de compression sur vos articulations et améliore ainsi la stabilit","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1366","wgerId":1366,"name":"Dumbbell Split Squat","muscle":"fessiers","equipment":"elastiques","desc":"* Exécution contrôlée * Pas d'élan * Exécuter lentement","tips":["* Exécution contrôlée * Pas d'élan * Exécuter lentement"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1370","wgerId":1370,"name":"Dumbbell Deadlift","muscle":"jambes","equipment":"elastiques","desc":"* Exécution contrôlée * Ne pas utiliser l'élan * Exécution lente","tips":["* Exécution contrôlée * Ne pas utiliser l'élan * Exécution lente"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1324","wgerId":1324,"name":"Fente au poids du corps HD","muscle":"jambes","equipment":"none","desc":"Les fentes au poids du corps sont un exercice de callisthénie efficace pour renforcer le bas du corps, améliorer l'équilibre et la stabilité, et développer une force fonctionnelle. Elles constituent un choix populaire pour les séances au poids du corps, les entraînements à la maison, et peuvent aussi s'intégrer à un programme de renforcement musculaire plus complet.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1325","wgerId":1325,"name":"Lateral Push Off","muscle":"jambes","equipment":"none","desc":"Poussez le sol et atterrissez sur une jambe et retrouvez l'équilibre avant de sauter à l'autre jambe","tips":["Poussez le sol et atterrissez sur une jambe et retrouvez l'équilibre avant de sauter à l'autre jambe"],"image":"https://wger.de/media/exercise-images/1325/d8372291-6725-452a-9711-6321c061e354.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1296","wgerId":1296,"name":"Croisement à la poulie basse - NB","muscle":"pectoraux","equipment":"none","desc":"Le croisement à la poulie basse est un mouvement d'isolation qui utilise une colonne de poulies pour cibler la partie supérieure des pectoraux. On le retrouve couramment dans les séances de musculation du haut du corps et axées sur la poitrine, souvent en complément de développés ou d'écartés réalisés sous d'autres angles afin de cibler toutes les portions des pectoraux.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1296/c42782fe-337a-44f4-9079-7f6dedab4885.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1670","wgerId":1670,"name":"Balancements de jambe (avant-arrière)","muscle":"jambes","equipment":"none","desc":"Tenez-vous bien droit à côté d'un mur ou d'un support stable. Balancez une jambe vers l'avant et vers l'arrière dans un mouvement contrôlé, en gardant le torse droit et les abdominaux gainés. Alternez les jambes après avoir terminé les répétitions.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1298","wgerId":1298,"name":"Extension des triceps croisée à la poulie haute - NB","muscle":"bras","equipment":"none","desc":"L'extension des triceps croisée à la poulie haute est un exercice d'isolation destiné à cibler les triceps, en particulier le chef long. Elle utilise des câbles et des poignées saisies avec les mains croisées, ce qui permet un mouvement de poussée particulier, efficace pour développer la force des triceps. Contrairement aux exercices qui utilisent une barre droite ou une corde, cette variante peut être plus confortable pour vos poignets et vos coudes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1298/ec4b83ec-5a8f-4303-9050-99ec4389bc2a.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1672","wgerId":1672,"name":"Abduction des hanches assis","muscle":"fessiers","equipment":"none","desc":"Position de départ : * Réglez la hauteur du siège de manière à ce que vos genoux soient alignés avec l'axe de pivot de la machine. * Asseyez-vous le dos bien plaqué contre le dossier, en gardant une bonne posture. * Placez l'extérieur de vos cuisses contre les leviers rembourrés de la machine. * Posez vos pieds à plat sur les repose-pieds ou la plateforme de la machine. * Saisissez les poignées ou les côtés du siège pour la stabilité. * Assurez-vous que votre colonne vertébrale est neutre et que vos abdominaux sont légèrement gainés. Mouvement : * Expirez en poussant lentement vos jambes vers l'extérieur contre les coussins de résistance. * C","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1378","wgerId":1378,"name":"Élévations latérales à la poulie (un bras)","muscle":"epaules","equipment":"none","desc":"L'élévation latérale à la poulie à un bras est une variante de l'élévation latérale et un exercice utilisé pour développer les muscles des épaules. 1. Réglez une poulie à la position la plus basse possible et fixez-y une poignée. 2. Passez le bras devant votre corps et saisissez la poignée en prise neutre. 3. Gardez le coude légèrement fléchi, tirez la poignée à travers votre corps et soulevez latéralement. 4. Abaissez lentement la poignée pour revenir à la position de départ, de façon contrôlée.","tips":["Réglez une poulie à la position la plus basse possible et fixez-y une poignée","Passez le bras devant votre corps et saisissez la poignée en prise neutre","Gardez le coude légèrement fléchi, tirez la poignée à travers votre corps et soulevez latéralement","Abaissez lentement la poignée pour revenir à la position de départ, de façon contrôlée"],"image":"https://wger.de/media/exercise-images/1378/7c1fcf34-fb7e-45e7-a0c1-51f296235315.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1659","wgerId":1659,"name":"Tirage vertical - un bras croisé devant le corps","muscle":"dos","equipment":"none","desc":"Asseyez-vous à la machine de tirage vertical, le corps placé en diagonale de sorte qu'une seule jambe soit sous le coussin. Tirez le câble vers le bas avec le bras opposé. Cela oblige le câble à traverser votre corps pendant la traction vers le bas. Cet exercice accentue l'étirement du grand dorsal.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1333","wgerId":1333,"name":"Forearm Curls (underhand grip)","muscle":"jambes","equipment":"elastiques","desc":"* Engagez les muscles * N'utilisez pas d'élan * Mouvement contrôlé * Mouvement lent","tips":["* Engagez les muscles * N'utilisez pas d'élan * Mouvement contrôlé * Mouvement lent"],"image":"https://wger.de/media/exercise-images/1333/89f43354-32e3-473a-9bcf-caca51f1a8e3.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1660","wgerId":1660,"name":"Développé pectoraux à la poulie - incliné","muscle":"pectoraux","equipment":"none","desc":"Développé pectoraux à un bras réalisé à la machine à poulie. Utilisez l'autre bras pour stabiliser le poids du corps afin de vous concentrer sur la force de la poussée plutôt que sur l'équilibre du corps. Commencez avec la main le plus près possible de la poitrine, puis poussez contre le câble selon une légère inclinaison, en direction du centre de votre poitrine.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1661","wgerId":1661,"name":"Poussée des triceps à la poulie","muscle":"bras","equipment":"none","desc":"Exercice à un bras qui commence avec la main près de la poitrine, le coude fléchi et écarté vers l'extérieur. Poussez vers l'avant et vers le bas contre le câble en tendant le coude.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1336","wgerId":1336,"name":"Extension des triceps au-dessus de la tête (haltère)","muscle":"bras","equipment":"elastiques","desc":"* Gardez les coudes fixes * Engagez les muscles * N'utilisez pas d'élan * Mouvement contrôlé * Mouvement lent * Ne tendez pas à l'excès","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1336/ebf88217-df26-4ef7-94cb-f0c2220c6abe.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1338","wgerId":1338,"name":"Élévation des épaules (haltère)","muscle":"epaules","equipment":"elastiques","desc":"* Engagez les muscles * N'utilisez pas d'élan * Mouvement contrôlé * Mouvement lent * Gardez toujours les bras fléchis * Ne tendez pas à l'excès","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1338/9d157b4d-5af0-43c1-bd34-f52144ba1b54.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1679","wgerId":1679,"name":"Wall angels (anges au mur)","muscle":"dos","equipment":"none","desc":"L'exercice des **wall angels** cible principalement les **muscles du haut du dos et des épaules**, ce qui aide à améliorer la **posture**, la **mobilité des épaules** et le **contrôle des omoplates**.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1680","wgerId":1680,"name":"Étirement en figure quatre assis","muscle":"fessiers","equipment":"barre","desc":"Asseyez-vous sur un banc. Les pieds à plat sur le sol. Placez votre cheville gauche sur votre genou droit. Votre genou droit reste à plat. Gardez le dos droit. Poussez doucement votre genou gauche vers le bas.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1348","wgerId":1348,"name":"Extensions du bas du dos","muscle":"jambes","equipment":"none","desc":"* Engagez les muscles * Soulevez légèrement le bassin * Mouvement contrôlé * Mouvement lent * N'utilisez pas d'élan * Gardez le haut du corps droit","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1348/a3769120-2445-49f2-97d3-afc1238bfc2a.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1360","wgerId":1360,"name":"Épaulé-développé avec deux kettlebells","muscle":"epaules","equipment":"elastiques","desc":"Exercice de musculation pour tout le corps. Cet exercice offre un large éventail de bénéfices en termes de force et de volume musculaire, et il est extrêmement fonctionnel.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1361","wgerId":1361,"name":"Double Kettlebell Front Squat","muscle":"fessiers","equipment":"elastiques","desc":"Le kettlebell front squat est un exercice composé et multi-articulaire qui fait travailler plusieurs groupes musculaires.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1363","wgerId":1363,"name":"Blackroll","muscle":"jambes","equipment":"none","desc":"* Mouvements contrôlés * Mouvements lents * Ne pas utiliser l'élan","tips":["* Mouvements contrôlés * Mouvements lents * Ne pas utiliser l'élan"],"image":"https://wger.de/media/exercise-images/1363/1dba566b-e799-4bde-abb0-c011a3c75e52.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1373","wgerId":1373,"name":"box jumps","muscle":"fessiers","equipment":"none","desc":"Jump from a standing position onto the box, stretch your body, then step down again (do not jump)","tips":["Jump from a standing position onto the box, stretch your body, then step down again (do not jump)"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1374","wgerId":1374,"name":"Rotary Torso Machine","muscle":"abdos","equipment":"none","desc":"- Lent et stable - Pas trop de poids","tips":["- Lent et stable - Pas trop de poids"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1376","wgerId":1376,"name":"Recumbent Bike","muscle":"jambes","equipment":"none","desc":"Pour cet exercice, un vélo couché est nécessaire. Il vous suffit de vous asseoir dessus, de définir le niveau et l'heure et de commencer l'entraînement","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1377","wgerId":1377,"name":"Rotation du torse","muscle":"abdos","equipment":"none","desc":"Exercice de rotation du torse debout. Ciblez vos abdominaux et améliorez votre souplesse avec cet exercice dynamique debout ! L'exercice de rotation du torse debout consiste à faire pivoter votre torse tout en gardant les pieds et les hanches stables, en sollicitant vos obliques et en étirant l'ensemble du haut de votre corps. Ce mouvement permet de : renforcer la sangle abdominale ; augmenter la souplesse de la colonne vertébrale et du torse ; améliorer la posture et l'équilibre ; améliorer les performances athlétiques globales. Réalisez 3 séries de 10 à 15 répétitions, en pivotant de chaque côté, pour ressentir les bienfaits de cet exercice","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1377/12e7a231-d36a-4992-bf57-ff7bfe0f3ae4.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1381","wgerId":1381,"name":"Haut du dos","muscle":"epaules","equipment":"none","desc":"L'exercice Haut du dos convient pour renforcer les muscles profonds, avec une attention particulière portée aux deltoïdes, aux rhomboïdes et aux muscles du haut du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1312","wgerId":1312,"name":"Squat au poids du corps HD","muscle":"jambes","equipment":"none","desc":"Le squat est un type d'exercice au poids du corps. C'est l'un des exercices les plus populaires pour la force et la prise de muscle. Le squat est particulièrement efficace pour cibler les muscles des jambes et des hanches. Le squat est un exercice facile à réaliser pour les débutants. Il peut aider à renforcer les muscles des jambes, à raffermir les muscles des hanches et à brûler des calories pour perdre du poids. Il raffermit les fessiers et les jambes. Les squats sont très efficaces pour tonifier et renforcer vos jambes en agissant sur les fessiers, les fléchisseurs de hanche, les quadriceps, les ischio-jambiers et les muscles de l'intérie","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1384","wgerId":1384,"name":"Pullover Machine","muscle":"dos","equipment":"none","desc":"Machine à pull-over, assise, coudes sur coussinets","tips":["Machine à pull-over, assise, coudes sur coussinets"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1683","wgerId":1683,"name":"Curl Zottman","muscle":"bras","equipment":"elastiques","desc":"Les paumes tournées vers l'avant, fléchissez les bras pour monter les charges vers vos épaules. Tournez les mains de manière à orienter les paumes vers le bas, puis redescendez lentement les charges. Enfin, tournez de nouveau les paumes vers l'avant.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-650","wgerId":650,"name":"Thruster","muscle":"epaules","equipment":"barre","desc":"1. Commencez par effectuer un squat avant (front squat) 2. En position haute, poussez la barre au-dessus de votre tête (comme pour un développé) 3. Abaissez la barre jusqu'aux épaules","tips":["Commencez par effectuer un squat avant (front squat)","En position haute, poussez la barre au-dessus de votre tête (comme pour un développé)","Abaissez la barre jusqu'aux épaules"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1387","wgerId":1387,"name":"Battements de jambe tendue","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds écartés de la largeur des hanches, et tendez un bras devant vous. Balancez cette jambe vers le haut devant vous puis ramenez-la vers le bas en la gardant aussi tendue que possible et les orteils pointés vers le haut. Répétez avec l'autre jambe.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1387/a2cf7eda-5540-4105-b30e-1c2f2679a6c7.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1390","wgerId":1390,"name":"Toucher des orteils","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds rapprochés. Fléchissez au niveau des hanches et abaissez le haut du corps vers vos orteils. Tendez les mains vers vos pieds et essayez de toucher vos orteils, le sol, ou de descendre aussi bas que possible le long de vos jambes sans forcer.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1684","wgerId":1684,"name":"Thruster avec haltères","muscle":"jambes","equipment":"elastiques","desc":"Commencez avec les haltères posés sur vos épaules et descendez en squat. Poussez pour vous redresser et levez les haltères au-dessus de la tête. Ramenez les haltères sur vos épaules et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1686","wgerId":1686,"name":"Pont fessier avec développé d'un bras","muscle":"pectoraux","equipment":"elastiques","desc":"Un haltère dans une main, réalisez un pont fessier. Tenez ensuite l'haltère au-dessus de votre poitrine : c'est la position de départ de la répétition. Abaissez l'haltère jusqu'à ce que votre coude touche le sol ou se trouve à environ 45 degrés en dessous de votre épaule si vous utilisez un banc. Poussez l'haltère pour revenir à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1687","wgerId":1687,"name":"Bear crawl avec tirage croisé","muscle":"epaules","equipment":"elastiques","desc":"Placez un haltère à hauteur des hanches environ et adoptez une position de bear crawl (marche de l'ours). Décollez les genoux du sol et maintenez la position. Avec la main opposée, attrapez l'haltère et tirez-le de l'autre côté. Replacez votre main au sol et répétez avec l'autre main.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1372","wgerId":1372,"name":"Triceps Dips (Assisted)","muscle":"bras","equipment":"none","desc":"Le trempage assisté des triceps est un exercice de gymnastique qui cible les triceps et implique également la poitrine.","tips":["Le trempage assisté des triceps est un exercice de gymnastique qui cible les triceps et implique également la poitrine."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1391","wgerId":1391,"name":"Marche de l'éléphant","muscle":"jambes","equipment":"none","desc":"Fléchissez au niveau des hanches jusqu'à ressentir un étirement à l'arrière des genoux. Pliez une jambe pendant que l'autre reste tendue, puis pliez l'autre genou de manière fluide tout en tendant le premier.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1392","wgerId":1392,"name":"Good morning","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds écartés au-delà de la largeur des épaules (position large), et placez vos mains sur vos hanches. Fléchissez au niveau des hanches et abaissez le haut du corps vers le sol en gardant le dos droit, puis redressez-vous.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1392/a02c9c7d-f42d-43e0-9946-1b99b014daee.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1393","wgerId":1393,"name":"Étirement des ischio-jambiers sur une jambe","muscle":"jambes","equipment":"none","desc":"Asseyez-vous au sol, une jambe tendue devant vous et l'autre repliée vers vous. Tendez les deux mains vers l'avant en essayant de toucher les orteils de votre jambe tendue.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1394","wgerId":1394,"name":"Flexion assise (sit & reach)","muscle":"jambes","equipment":"none","desc":"Asseyez-vous au sol, les jambes tendues devant vous. Tendez les deux mains vers l'avant en essayant de dépasser vos orteils ou d'aller aussi loin que possible. Revenez à la position de départ et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1395","wgerId":1395,"name":"Balancements de jambe croisés","muscle":"jambes","equipment":"none","desc":"Tenez-vous à un mur ou à un appui à proximité pour vous stabiliser. Balancez une jambe devant votre corps en la croisant, puis ramenez-la vers l'arrière et sur le côté. Répétez en augmentant progressivement votre amplitude de mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1396","wgerId":1396,"name":"Pancake debout","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout et écartez les jambes le plus possible en position de grand écart facial. Fléchissez ensuite au niveau des hanches en les poussant vers l'arrière tout en gardant le dos droit.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1398","wgerId":1398,"name":"Étirement de l'ischio-jambier vers la poitrine","muscle":"jambes","equipment":"none","desc":"Asseyez-vous au sol et pliez une jambe en ramenant le genou vers vous. Placez votre main derrière l'ischio-jambier et tirez doucement votre jambe vers la poitrine, en ressentant un étirement à l'arrière de la cuisse. Tendez ensuite votre jambe en la dépliant vers le plafond.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1399","wgerId":1399,"name":"Déroulé du buste (roll down)","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds écartés de la largeur des hanches, et déroulez lentement le haut du corps vers l'avant, une vertèbre à la fois, jusqu'à ce que vos mains touchent le sol ou aussi bas que vous le pouvez sans forcer. Remontez à la position de départ avec le même contrôle.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1400","wgerId":1400,"name":"Étirement des ischio-jambiers jambes croisées","muscle":"jambes","equipment":"none","desc":"Debout, croisez une jambe derrière l'autre (gardez cette jambe tendue). Penchez-vous vers le bas et essayez de toucher les orteils de cette jambe. Fléchissez légèrement l'autre jambe afin de pouvoir vous pencher.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1658","wgerId":1658,"name":"Curl au pupitre - rotation externe","muscle":"bras","equipment":"elastiques","desc":"Curl à un bras qui peut être réalisé avec un haltère et un banc Larry Scott (pupitre), ou sur une machine à curl au pupitre. Tournez le corps à l'opposé de la charge.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1406","wgerId":1406,"name":"Plank-to-Elbow Extension","muscle":"epaules","equipment":"none","desc":"L'extension de la planche au coude est un exercice dynamique qui combine la planche avec un mouvement d'extension du coude","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-2487","wgerId":2487,"name":"Cool-Down Swim","muscle":"epaules","equipment":"none","desc":"Nagez à un rythme facile et sans hâte — nage libre, dos droit ou simplement flottant/planant — sans vous concentrer sur la technique ou les exercices. Le seul objectif ici est de laisser votre rythme cardiaque baisser progressivement et vos muscles se détendre avant de sortir de la piscine.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1489","wgerId":1489,"name":"Plank Jacks","muscle":"fessiers","equipment":"none","desc":"Jumping jacks from the plank position.","tips":["Jumping jacks from the plank position."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1407","wgerId":1407,"name":"Squat cosaque","muscle":"fessiers","equipment":"none","desc":"Le squat cosaque est un exercice pluri-articulaire qui sollicite principalement les jambes et les fessiers, mais qui fait aussi intervenir les muscles stabilisateurs. C'est un excellent exercice pour améliorer la force, la mobilité et la stabilité de manière fonctionnelle.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1408","wgerId":1408,"name":"Chaise (wall-sit)","muscle":"fessiers","equipment":"none","desc":"La chaise (ou wall sit) est un exercice isométrique qui sollicite principalement les muscles des jambes, en améliorant l'endurance musculaire et la stabilité. Voici les muscles principaux et secondaires activés pendant l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1409","wgerId":1409,"name":"Dragon flag","muscle":"abdos","equipment":"none","desc":"Gardez le corps complètement gainé tout au long du mouvement, en évitant de creuser le bas du dos. Utilisez une prise ferme pour stabiliser le haut du corps. Commencez par des versions plus simples (par exemple avec les genoux fléchis) afin de développer la force et le contrôle.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1410","wgerId":1410,"name":"Plank with Alternating Leg Lift","muscle":"fessiers","equipment":"none","desc":"In a plank position, lift one leg alternately.","tips":["In a plank position, lift one leg alternately."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1411","wgerId":1411,"name":"Toucher des talons","muscle":"abdos","equipment":"none","desc":"- **Position de départ :** * Allongez-vous sur le dos sur un tapis de sport. * Fléchissez les genoux en gardant les pieds à plat au sol et écartés de la largeur des hanches. * Placez vos bras le long du corps, paumes tournées vers l'intérieur, légèrement décollées du sol. - **Gainez le tronc :** * Décollez légèrement la tête, les épaules et le haut du dos du sol. * Gardez la nuque neutre et le menton légèrement rentré. - **Réalisez le mouvement :** * Inclinez-vous latéralement vers la droite en tendant votre main droite vers votre talon droit. * Revenez au centre, puis inclinez-vous vers la gauche en tendant votre main gauche vers votre talon","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1412","wgerId":1412,"name":"Crunchs bicyclette","muscle":"abdos","equipment":"none","desc":"Les crunchs bicyclette sont un exercice de gainage réalisé au sol. Allongez-vous sur le dos, les mains derrière la tête et les jambes tendues. Décollez les épaules du sol, ramenez un genou vers la poitrine et faites pivoter le torse de sorte que le coude opposé rejoigne le genou. Alternez les côtés dans un mouvement de pédalage, en veillant à garder des mouvements contrôlés et à solliciter la sangle abdominale tout au long de l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1457","wgerId":1457,"name":"Press around à la poulie","muscle":"epaules","equipment":"none","desc":"Réglez la poulie à hauteur de la poitrine et fixez-y une poignée en D. Saisissez la poignée en prise neutre et tenez-la près de la poitrine, le coude entièrement fléchi et collé au côté. Tournez-vous à l'opposé de la poulie de sorte que votre tronc soit à 45 degrés. Tenez l'autre côté de la machine à câbles fonctionnelle avec la main correspondante. Adoptez une position de pieds décalée pour un meilleur équilibre. Tout en gardant la poitrine bombée, tendez le coude à 45 degrés en travers de votre axe médian tout en gardant le bras parallèle au sol. Arrêtez-vous juste avant le verrouillage et contractez les pectoraux au sommet de l'amplitude d","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1414","wgerId":1414,"name":"Hack squats","muscle":"jambes","equipment":"none","desc":"Les hack squats ciblent le bas du corps et se réalisent sur une machine à hack squat ou avec une barre. Pour la variante à la machine, placez-vous sur la plateforme, les épaules sous les coussinets et les pieds légèrement avancés. Poussez sur vos talons pour soulever la charge, puis fléchissez les genoux pour abaisser la plateforme de manière contrôlée jusqu'à ce que vos cuisses soient parallèles au sol. Remontez à la position de départ. Pour la variante à la barre, tenez la barre derrière vos jambes, les bras tendus, et effectuez un mouvement semblable à un squat.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1415","wgerId":1415,"name":"Crunchs avec haltère","muscle":"abdos","equipment":"elastiques","desc":"Les crunchs avec haltère sont une variante lestée des crunchs classiques, conçue pour solliciter plus intensément les muscles abdominaux. Allongez-vous sur le dos, les genoux fléchis et les pieds à plat au sol. Tenez un haltère à deux mains près de votre poitrine ou au-dessus de votre tête. Décollez les épaules et le haut du dos du sol dans un mouvement de crunch en contractant la sangle abdominale. Redescendez lentement à la position de départ. Veillez à garder des mouvements contrôlés tout au long de l'exercice pour éviter toute tension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1458","wgerId":1458,"name":"Cross-Body Cable Y-Raise","muscle":"epaules","equipment":"none","desc":"Fixez une barre en D à la machine à câbles. Effectuez un mouvement qui s'apparente à tirer une épée de l'autre côté de votre corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1469","wgerId":1469,"name":"Bent over Cable Flye","muscle":"pectoraux","equipment":"none","desc":"Tenez le haut de votre corps à un angle d'environ 105 °.","tips":["Tenez le haut de votre corps à un angle d'environ 105 °."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1470","wgerId":1470,"name":"1-Arm Half-Kneeling Lat Pulldown","muscle":"dos","equipment":"none","desc":"Fixez une poignée en D à une poulie haute. Et utilisez vos muscles lat pour tirer le poids d'une seule main.","tips":["Fixez une poignée en D à une poulie haute. Et utilisez vos muscles lat pour tirer le poids d'une seule main."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1472","wgerId":1472,"name":"Cable Shrug-In","muscle":"dos","equipment":"none","desc":"Fixez deux poignées en D à deux câbles bas et haussez les épaules en utilisant vos pièges supérieurs.","tips":["Fixez deux poignées en D à deux câbles bas et haussez les épaules en utilisant vos pièges supérieurs."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1473","wgerId":1473,"name":"Reverse Cable Flye","muscle":"epaules","equipment":"none","desc":"Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa.","tips":["Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1481","wgerId":1481,"name":"Extension des triceps à la poulie en tirant la corde vers soi","muscle":"bras","equipment":"none","desc":"1. La position de départ de cette extension des triceps à la corde consiste à se tenir debout face à une machine à câbles, les poignées d'une corde dans les deux mains et les pieds écartés à la largeur des épaules. 2. Faites une légère charnière des hanches vers l'avant en gardant la poitrine droite, et amenez les épaules et les coudes derrière le corps, de sorte qu'en poussant la corde vers le bas, vous puissiez obtenir une contraction complète du chef long des triceps. 3. Tirez la corde de la machine à câbles aussi près du corps que possible et tendez les coudes jusqu'au verrouillage.","tips":["Tirez la corde de la machine à câbles aussi près du corps que possible et tendez les coudes jusqu'au verrouillage"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1484","wgerId":1484,"name":"Croisé de poulies omni","muscle":"pectoraux","equipment":"none","desc":"Ajustez les charges en fonction du mouvement. Lorsque vous tirez de haut en bas, augmentez la charge de 20 % à 40 % de plus que pour le mouvement de bas en haut. Cela tient compte du fait que, lorsqu'on travaille de haut en bas, les muscles du haut des pectoraux sont naturellement plus faibles que ceux du bas des pectoraux. Ajustez donc votre colonne de poids pour compenser. 1. Positionnez une poulie en position haute et l'autre au réglage le plus bas. Adoptez une position de pieds décalée entre les deux colonnes de poulies. 2. Pour la poulie réglée en bas, tirez-la vers le haut et en travers de votre corps. Cela cible efficacement le haut de","tips":["Positionnez une poulie en position haute et l'autre au réglage le plus bas","Pour la poulie réglée en bas, tirez-la vers le haut et en travers de votre corps","Pour la poulie réglée en haut, tirez-la vers le bas et en travers de votre corps"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1485","wgerId":1485,"name":"Extension des triceps à la corde avec balancement","muscle":"bras","equipment":"none","desc":"Placez vos pieds sous la corde et inclinez le haut du corps vers la corde. Reculez un pied. Poussez la corde vers le bas et basculez tout votre corps en arrière sur le pied arrière au moment de la poussée afin d'amener vos mains derrière le corps. N'oubliez pas de ramener la poitrine vers l'avant pendant la poussée. Lorsque vous relâchez lentement la corde, ramenez votre corps en avant sur le pied avant.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1424","wgerId":1424,"name":"Machine à curl biceps","muscle":"bras","equipment":"none","desc":"La machine à curl biceps est conçue pour isoler les muscles biceps et offrir une amplitude de mouvement contrôlée. Asseyez-vous sur la machine, le dos contre le dossier, et réglez le siège de sorte que vos bras soient alignés avec les poignées ou les coussinets de la machine. Saisissez fermement les poignées, en gardant les coudes fixes, et remontez les poignées en contractant vos biceps. Abaissez lentement les poignées vers la position de départ en gardant le contrôle tout au long du mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1425","wgerId":1425,"name":"Toe taps","muscle":"abdos","equipment":"none","desc":"Les toe taps sont un exercice de gainage réalisé allongé sur le dos. Allongez-vous à plat, les bras le long du corps et les jambes levées en position de table (genoux fléchis à 90 degrés). Abaissez lentement un pied pour toucher délicatement le sol, en gardant la sangle abdominale gainée et le bas du dos plaqué contre le sol. Revenez à la position de départ et alternez les jambes. Cet exercice renforce la sangle abdominale tout en minimisant les tensions sur le bas du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1426","wgerId":1426,"name":"Crunchs latéraux debout","muscle":"abdos","equipment":"none","desc":"Les crunchs latéraux debout sont un exercice dynamique qui cible les obliques tout en améliorant l'équilibre et la stabilité. Tenez-vous bien droit, les pieds écartés de la largeur des épaules et les mains derrière la tête, ou un haltère dans une main. Inclinez le torse d'un côté en contractant les obliques, tout en ramenant le coude vers la hanche (ou en crunchant vers la charge si vous utilisez un haltère). Revenez à la position de départ et alternez les côtés, ou effectuez toutes les répétitions d'un côté avant de changer.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1486","wgerId":1486,"name":"Tirage à la poulie haute en alternance","muscle":"dos","equipment":"none","desc":"1. Commencez par placer l'accessoire en position haute sur la machine à câbles et reculez d'environ 1 m par rapport à l'accessoire. Saisissez la poignée de la poulie dans la main gauche, environ à hauteur de la tête, le coude légèrement fléchi. Reculez le pied gauche. 2. Tirez le coude vers le tronc en effectuant une légère rotation et réalisez un tirage à un bras. Engagez le grand dorsal pendant la rotation. 3. Revenez à la position de départ avec la poulie et le pied gauche, puis saisissez la poignée de la poulie dans la main droite. Répétez ce mouvement du côté opposé, le pied droit reculé.","tips":["Commencez par placer l'accessoire en position haute sur la machine à câbles et reculez d'environ","Tirez le coude vers le tronc en effectuant une légère rotation et réalisez un tirage à un bras"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1429","wgerId":1429,"name":"Rotations d'épaule avec haltère","muscle":"epaules","equipment":"elastiques","desc":"Les rotations d'épaule avec haltère sont conçues pour renforcer les muscles de la coiffe des rotateurs et améliorer la stabilité et la mobilité de l'épaule. 1. **Rotation externe** : Tenez un haltère dans une main, le coude fléchi à 90 degrés et proche du corps. Faites pivoter votre avant-bras vers l'extérieur, à l'opposé du corps, en gardant le coude immobile. Revenez lentement à la position de départ. 2. **Rotation interne** : Tenez un haltère dans une main, le coude fléchi à 90 degrés et proche du corps. Faites pivoter votre avant-bras vers l'intérieur, vers le corps, puis revenez lentement à la position de départ. Réalisez l'exercice avec","tips":["**Rotation externe** : Tenez un haltère dans une main, le coude fléchi à","**Rotation interne** : Tenez un haltère dans une main, le coude fléchi à"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1430","wgerId":1430,"name":"Maintien de disques en pince","muscle":"epaules","equipment":"none","desc":"Le maintien de disques en pince est un exercice de force de préhension conçu pour solliciter les avant-bras et améliorer l'endurance de la prise. Choisissez un ou deux disques (les disques à bords lisses conviennent le mieux) et serrez-les ensemble entre votre pouce et vos doigts. Tenez les disques avec le bras tendu le long du corps ou légèrement avancé devant vous. Maintenez la prise aussi longtemps que possible, en gardant les épaules relâchées et la prise ferme. Cet exercice peut se faire pour une durée donnée ou un nombre de répétitions.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1433","wgerId":1433,"name":"Wood chops inversés (rotation du tronc)","muscle":"fessiers","equipment":"none","desc":"* Fixez un élastique en boucle à un rack en dessous de la hauteur des genoux * Saisissez l'autre extrémité de l'élastique à deux mains, comme si vous teniez une batte de baseball * Étirez l'élastique en lui faisant face * Commencez avec les mains sur le côté de vos hanches, les genoux fléchis * Faites pivoter vos hanches tout en déplaçant vos mains par-dessus l'épaule opposée * Imaginez le mouvement comme si vous frappiez une balle de baseball avec une batte","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1434","wgerId":1434,"name":"Lat Pull DB","muscle":"dos","equipment":"elastiques","desc":"* Pliez le haut du corps vers l'avant * Déplacez les haltères près de votre corps avec les bras légèrement pliés vers votre dos","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1435","wgerId":1435,"name":"Scapula Pulls","muscle":"dos","equipment":"none","desc":"* Accrochez-vous directement à une barre de traction * Tirez les omoplates ensemble, en déplaçant légèrement le corps vers le haut","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1436","wgerId":1436,"name":"Développé couché aux barres d'arrêt (barre)","muscle":"pectoraux","equipment":"barre","desc":"* Réglez les barres d'arrêt environ à la hauteur de votre point de blocage * Abaissez la barre, laissez-la reposer sur les barres d'arrêt pendant 1 s en maintenant la tension * Poussez la barre vers le haut avec un maximum de force","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1437","wgerId":1437,"name":"Squat aux barres d'arrêt","muscle":"jambes","equipment":"barre","desc":"* Réglez les barres d'arrêt environ à la hauteur de votre point de blocage * Abaissez la barre, laissez-la reposer sur les barres d'arrêt pendant 2 s en maintenant la tension * Redressez-vous avec un maximum de force","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1438","wgerId":1438,"name":"Clean","muscle":"fessiers","equipment":"barre","desc":"Nettoyage régulier des ascenseurs olympiques. Tirez la barre du sol, attrapez sur les épaules en effectuant un squat avant.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1439","wgerId":1439,"name":"Pin OHP","muscle":"epaules","equipment":"barre","desc":"* Réglez les goupilles de sécurité à la hauteur de votre menton inférieur * Reposez la barre sur les goupilles en maintenant la tension * Soulevez la barre au-dessus de la tête","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1440","wgerId":1440,"name":"Développé militaire avec impulsion (push press)","muscle":"epaules","equipment":"barre","desc":"* Posez la barre devant vous sur vos épaules * Fléchissez les genoux en gardant le haut du corps droit * Tendez les jambes pour propulser la barre au-dessus de la tête avec force","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1441","wgerId":1441,"name":"Développé épaules incliné aux haltères","muscle":"epaules","equipment":"elastiques","desc":"* Asseyez-vous sur un banc incliné à 45° * Coudes écartés à 45° * Abaissez les haltères jusqu'à ce que vos bras soient parallèles à vos épaules * Remontez les haltères en les faisant se rejoindre au-dessus de la tête","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1442","wgerId":1442,"name":"Kreis Press aux haltères","muscle":"epaules","equipment":"elastiques","desc":"* Asseyez-vous sur un banc incliné à 45° * Tenez les haltères au-dessus de la tête * Abaissez les haltères comme pour un développé au-dessus de la tête * Faites pivoter les haltères, paumes tournées vers le haut, et tendez les bras devant votre corps * Rapprochez les mains jusqu'à ce que les haltères se touchent, en gardant les bras tendus * Inversez le mouvement jusqu'à ramener les haltères au-dessus de la tête * Cela constitue une répétition","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1443","wgerId":1443,"name":"Élévation latérale et frontale aux haltères","muscle":"epaules","equipment":"elastiques","desc":"* Tenez-vous debout en tenant les haltères le long du corps * Gardez les bras presque entièrement tendus * Sans élan, levez les haltères sur les côtés du corps jusqu'à hauteur des épaules, paumes vers le bas * Abaissez les haltères le long du corps, paumes tournées vers l'intérieur * Levez immédiatement les haltères devant le corps jusqu'à hauteur des épaules, paumes vers le bas * Redescendez à nouveau * Cela correspond à une répétition","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1445","wgerId":1445,"name":"Jeté — haltérophilie","muscle":"epaules","equipment":"barre","desc":"Jeté d'haltérophilie olympique * Tenez la barre devant vous, posée sur les épaules, comme pour un développé avec impulsion * Fléchissez puis tendez les genoux pour propulser la barre vers le haut tout en vous plongeant sous la barre * Réceptionnez la barre au-dessus de la tête, bras tendus, en adoptant une position de fente * Ramenez les pieds parallèles tout en maintenant la barre verrouillée en position haute","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1446","wgerId":1446,"name":"Clean and Jerk OL","muscle":"epaules","equipment":"barre","desc":"Levage olympique propre et saccadé. Combinaison de clean et de jerk en un seul mouvement.","tips":["Levage olympique propre et saccadé. Combinaison de clean et de jerk en un seul mouvement."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1447","wgerId":1447,"name":"Arraché — haltérophilie","muscle":"epaules","equipment":"barre","desc":"Arraché d'haltérophilie olympique * Tirez la barre du sol jusqu'au verrouillage au-dessus de la tête en utilisant une prise large et un squat overhead. * Déplacez la barre lentement jusqu'à ce qu'elle passe les genoux, puis tendez explosivement les hanches, tirez la barre vers le haut et plongez-vous sous la barre * Réceptionnez la barre au-dessus de la tête, bras tendus * Poussez la tête vers l'avant pendant le verrouillage","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1448","wgerId":1448,"name":"Curl incliné avec haltères","muscle":"bras","equipment":"barre","desc":"**Asseyez-vous sur un banc incliné à 60∘.** **Tenez les haltères le long du corps près du sol, paumes vers l'extérieur, bras complètement étendus.** **Soulevez les haltères en utilisant uniquement les biceps et sans élan (sans donner d'à-coups).**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1448/2184e68c-32b5-413f-a7c1-4a2d1bb98c35.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1449","wgerId":1449,"name":"Simulateur d'escalier (ClimbMill)","muscle":"jambes","equipment":"none","desc":"Le ClimbMill, également appelé simulateur d'escalier, est une machine axée sur le cardio qui reproduit la montée d'escaliers. Il offre un moyen efficace d'améliorer l'endurance tout en renforçant le bas du corps. Pour utiliser la machine, montez sur les marches mobiles, gardez une posture droite et utilisez les rampes pour garder l'équilibre si nécessaire. Réglez la vitesse et l'intensité en fonction de votre niveau de forme physique. Cet exercice contribue à améliorer la santé cardiovasculaire, à brûler des calories et à renforcer l'endurance musculaire du bas du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1450","wgerId":1450,"name":"Étirement du cobra","muscle":"abdos","equipment":"none","desc":"L'étirement du cobra est un exercice d'extension du dos qui aide à améliorer la souplesse de la colonne vertébrale et à soulager les tensions dans le bas du dos. Pour le réaliser, allongez-vous à plat ventre sur le sol, mains placées sous les épaules. Appuyez les paumes contre le sol et soulevez la poitrine tout en gardant les hanches au sol. Gardez les coudes légèrement fléchis et les épaules détendues. Maintenez l'étirement pendant quelques secondes, puis redescendez lentement. Cet exercice est bénéfique pour améliorer la posture et réduire la raideur du bas du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1451","wgerId":1451,"name":"Étirement en rotation du tronc","muscle":"abdos","equipment":"none","desc":"L'étirement en rotation du tronc aide à améliorer la mobilité de la colonne vertébrale et à soulager les tensions dans le bas du dos et les obliques. Il peut se pratiquer debout ou assis. 1. **Variante debout** : Tenez-vous droit, pieds écartés à la largeur des épaules. Placez les mains sur les hanches ou tendez les bras devant vous. Tournez lentement le tronc d'un côté en gardant les hanches stables. Maintenez quelques secondes, puis tournez vers le côté opposé. 2. **Variante assise** : Asseyez-vous sur une chaise, pieds à plat sur le sol. Placez une main sur l'extérieur de la cuisse opposée et faites doucement pivoter le tronc de ce côté. M","tips":["**Variante debout** : Tenez-vous droit, pieds écartés à la largeur des épaules","**Variante assise** : Asseyez-vous sur une chaise, pieds à plat sur le sol"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1452","wgerId":1452,"name":"Étirement genou-poitrine","muscle":"fessiers","equipment":"none","desc":"L'étirement genou-poitrine est un exercice simple mais efficace pour soulager les tensions du bas du dos et améliorer la mobilité des hanches. Pour le réaliser, allongez-vous à plat sur le dos, jambes tendues. Ramenez un genou vers la poitrine en enroulant les mains autour du tibia ou derrière la cuisse. Tirez doucement le genou plus près de la poitrine tout en gardant l'autre jambe tendue au sol. Maintenez l'étirement pendant 15 à 30 secondes, puis changez de côté. Pour un étirement plus profond, vous pouvez ramener les deux genoux vers la poitrine en même temps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1452/85a6b9de-4eec-445b-8ebb-f1950b076aba.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1455","wgerId":1455,"name":"Superman avec serviette","muscle":"dos","equipment":"none","desc":"Dans cet exercice, vous vous allongez à plat ventre, tenez une serviette les bras tendus devant vous, et l'écartez pour créer une tension. Ensuite, vous la déplacez d'avant en arrière sous votre ventre. Cet exercice sollicite les muscles du dos et des épaules ainsi que la stabilité du tronc.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1461","wgerId":1461,"name":"Développé couché aux haltères sans impulsion des jambes","muscle":"pectoraux","equipment":"barre","desc":"Mettez-vous en place comme pour un développé couché aux haltères classique, mais levez les jambes tendues ou posez-les sur un autre banc afin d'éliminer l'impulsion des jambes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1462","wgerId":1462,"name":"punches","muscle":"epaules","equipment":"none","desc":"rester stable et lancer des coups de poing droits normaux","tips":["rester stable et lancer des coups de poing droits normaux"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1463","wgerId":1463,"name":"Rowing aux haltères en prise supination","muscle":"bras","equipment":"elastiques","desc":"Le rowing aux haltères en prise supination sollicite le dos, ce qui vous permet d'essayer une charge un peu plus lourde. La contrainte est que vous devez pouvoir contrôler la charge sur toutes les répétitions. 1. Commencez en tenant une paire d'haltères, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis. 2. Faites une charnière au niveau des hanches pour incliner le tronc vers l'avant jusqu'à ce qu'il soit presque parallèle au sol, en gardant le dos plat et en maintenant une légère flexion des genoux. 3. Expirez en tirant les haltères vers vos côtés jusqu'à hauteur de la poitrine, en menant avec les coudes jusqu'à ce","tips":["Commencez en tenant une paire d'haltères, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis","Redescendez lentement vers la position de départ et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1464","wgerId":1464,"name":"Hack squats avec pause","muscle":"jambes","equipment":"none","desc":"Des hack squats mais avec une pause de 1 à 2 secondes au bas du mouvement. Cela garantit qu'il ne reste plus d'énergie élastique stockée dans les muscles.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1465","wgerId":1465,"name":"Spider curl","muscle":"bras","equipment":"barre","desc":"Pour tirer le meilleur parti des spider curls aux haltères, il vous faut un banc réglable incliné à 45 degrés. Cette position inclinée permet à vos bras de pendre librement, les plaçant dans une position de départ étirée avec les coudes légèrement en avant du tronc, ce qui est la clé pour maintenir une tension isométrique de faible niveau tout au long du mouvement. 1. Allongez-vous à plat ventre sur un banc réglable, la poitrine entièrement soutenue, en tenant une paire d'haltères. 2. Gardez la tête en position neutre et ne tendez pas le cou. 3. Laissez vos bras pendre droit vers le bas, paumes vers l'avant (pour un spider curl classique) ou ","tips":["Allongez-vous à plat ventre sur un banc réglable, la poitrine entièrement soutenue, en tenant une paire d'haltères","Gardez la tête en position neutre et ne tendez pas le cou","Gardez les pieds stables au sol pour maintenir l'équilibre et le contrôle","Gardez la flexion du coude contrôlée","Contractez fortement au sommet pendant"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1466","wgerId":1466,"name":"Calf Raise using Hack Squat Machine","muscle":"jambes","equipment":"none","desc":"Idéalement à l'aide d'un addon trapèze, soulevez le poids à l'aide de vos mollets en vous mettant sur les orteils.","tips":["Idéalement à l'aide d'un addon trapèze, soulevez le poids à l'aide de vos mollets en vous mettant sur les orteils."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1467","wgerId":1467,"name":"Incline Close Grip Barbell Bench Press","muscle":"bras","equipment":"barre","desc":"Prise plus étroite que la presse à banc ordinaire, juste à l'extérieur de la largeur des épaules.","tips":["Prise plus étroite que la presse à banc ordinaire, juste à l'extérieur de la largeur des épaules."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1468","wgerId":1468,"name":"Barre au front au sol","muscle":"bras","equipment":"barre","desc":"Vous permettant de charger en toute sécurité plus de poids qu'une barre au front classique, allongez-vous au sol et reposez la charge sur le sol entre chaque répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1471","wgerId":1471,"name":"Kroc Row","muscle":"dos","equipment":"none","desc":"Rangées d'haltères avec une technique plus lâche mais un poids plus lourd.","tips":["Rangées d'haltères avec une technique plus lâche mais un poids plus lourd."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1474","wgerId":1474,"name":"W-Raise","muscle":"abdos","equipment":"none","desc":"Cet exercice exigeant est une variante des crunchs inversés, composée de trois parties au cours desquelles nous dessinons essentiellement un « W » à l'envers avec nos jambes. La position de départ consiste à être allongé sur le dos, à plat sur le sol, jambes tendues au point bas de la branche externe du « W ». En gardant un gainage solide et les jambes tendues, montez, soulevez les hanches puis abaissez lentement les jambes à mi-hauteur. Ensuite, en relevant les jambes vers le haut, soulevez à nouveau les hanches, en maintenant cette ligne droite, et utilisez la force de votre sangle abdominale pour finalement redescendre complètement vers l'","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1475","wgerId":1475,"name":"Black widow knee slides (glissements de genou)","muscle":"abdos","equipment":"none","desc":"Dans ce mouvement de rotation de bas en haut, vous croisez le genou et le ramenez vers le coude opposé. Commencez en position de planche haute (ou en position de table) avec les mains directement sous les épaules. Levez le genou gauche vers le bras droit et faites-le glisser le long de l'avant-bras pour accentuer la bascule postérieure du bassin et l'engagement des muscles abdominaux. Faites ensuite l'autre côté, en ramenant votre genou droit vers votre main gauche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1476","wgerId":1476,"name":"Relevé de buste papillon","muscle":"abdos","equipment":"none","desc":"Dans cet exercice à mi-amplitude, les muscles de vos bras vous fournissent un peu d'élan pour vous aider à décoller du sol. Vous les ouvrez également en position au-dessus de la tête, ce qui sollicite le haut du dos. Commencez allongé, les pieds à plat sur le sol, les genoux fléchis, les bras croisés contre la poitrine. En utilisant vos abdominaux, soulevez le haut du corps du sol tout en ouvrant les bras en position de cage (bras en « poteaux de but »), puis redescendez lentement pour revenir à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1477","wgerId":1477,"name":"Tire-bouchon assis","muscle":"abdos","equipment":"none","desc":"Pour réaliser cet exercice des abdominaux et des obliques, commencez avec les mains posées derrière le corps et ramenez les genoux vers l'intérieur et en travers, en cherchant vraiment à contracter les obliques. Tendez ensuite les jambes pour revenir à la position de départ et répétez vers le côté opposé des abdominaux. Les débutants pourront constater qu'ils n'arrivent même pas à tenir les 45 premières secondes de cette variante exigeante de crunchs inversés. Ce n'est pas grave, car cela vous donne un point de départ et un objectif à améliorer.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1478","wgerId":1478,"name":"Crunch en lévitation","muscle":"abdos","equipment":"none","desc":"Pour ce mouvement de haut en bas, nous cherchons à déplacer le haut du tronc sans bouger le bas du tronc. Commencez allongé au sol, les pieds à plat sur le sol et les bras croisés au-dessus de la tête, mains derrière la tête. Soulevez le haut du corps et décollez les omoplates du sol, puis maintenez et marquez une pause au sommet pendant un ou deux temps. Cherchez à faire travailler le haut des abdominaux et à tenir cette contraction pendant 10 répétitions de bonne qualité.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1479","wgerId":1479,"name":"Relevé de buste avec poussée du coude","muscle":"abdos","equipment":"none","desc":"Il s'agit d'un mouvement de rotation de haut en bas, et il est aussi un peu plus explosif. Allongé, les genoux fléchis et les pieds au sol, relevez le buste puis projetez votre coude gauche en travers de tout le corps vers la droite, revenez ensuite au centre et enfin redescendez. Faites ensuite l'autre côté.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1479/0305d98e-0887-4c0c-8992-7c220814efc2.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1480","wgerId":1480,"name":"Extensions des triceps allongé","muscle":"bras","equipment":"barre","desc":"1. La position de départ de cet exercice efficace pour les triceps consiste à être allongé sur un banc standard, en tenant une barre ou deux haltères des deux mains en prise pronation, mains écartées à la largeur des épaules. 2. Commencez avec les bras au-dessus du haut de la poitrine et les coudes fléchis vers l'arrière à environ 45 degrés. 3. Fléchissez d'abord les coudes, puis laissez le bras reculer, amenant la barre ou les haltères derrière la tête et vers le bas en direction du sol. Concernant la position du bras, la barre ou les haltères ne doivent jamais être entièrement au-dessus de votre tête, mais plutôt derrière, afin de garantir ","tips":["Commencez avec les bras au-dessus du haut de la poitrine et les coudes fléchis vers l'arrière à environ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1482","wgerId":1482,"name":"Curl triché aux haltères","muscle":"bras","equipment":"elastiques","desc":"1. La position de départ consiste à se tenir debout, pieds écartés à la largeur des épaules. 2. Les mains doivent adopter une prise en supination sur les haltères, en les tenant écartés à la largeur des épaules. 3. En gardant les coudes collés aux côtés pendant tout le mouvement, utilisez l'élan pour réaliser le curl avec les haltères, en contractant les biceps au sommet du mouvement. 4. Redescendez lentement pour revenir à la position de départ. Gardez la sangle abdominale gainée pendant tout l'exercice. Tricher sur la phase concentrique de cet exercice exigeant nous offre une excellente occasion d'augmenter le temps sous tension et de créer","tips":["La position de départ consiste à se tenir debout, pieds écartés à la largeur des épaules","Les mains doivent adopter une prise en supination sur les haltères, en les tenant écartés à la largeur des épaules","Redescendez lentement pour revenir à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1483","wgerId":1483,"name":"Curl biceps trifecta","muscle":"bras","equipment":"elastiques","desc":"Cet exercice est un mélange de trois curls différents : le curl en supination en travers du corps, le curl en pronation en travers du corps et le no money curl. Vous alternez entre trois variantes de curl qui visent chacune des objectifs différents, et vous prolongerez la série au-delà de la fourchette habituelle de 8 à 12 répétitions, ce qui nous apporte cette intensité. 1. Pour le curl en supination en travers du corps, mettez l'avant-bras en supination, paumes tournées vers le plafond, et amenez les avant-bras en travers du corps. Soulevez vers l'épaule le côté de l'haltère orienté vers l'intérieur. 2. Pour le curl en pronation en travers ","tips":["Pour le no money curl, vous réalisez le curl tout en effectuant une rotation externe de l'épaule"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1487","wgerId":1487,"name":"Combo hyperextension Y et W","muscle":"dos","equipment":"none","desc":"1. Utilisez un banc à lombaires (glute-ham raise) ou un ballon de stabilité pour cet exercice, ainsi qu'un disque léger dans chaque main. 2. Soulevez le tronc pour former une ligne droite avec les jambes et levez les bras vers l'extérieur, légèrement au-delà d'un angle de 90 degrés, en position de « W » pour solliciter les muscles de la coiffe des rotateurs, puis redescendez à la position de départ. 3. Remontez ensuite avec les bras en position de « Y » pour activer le bas des trapèzes.","tips":["Remontez ensuite avec les bras en position de « Y » pour activer le bas des trapèzes"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1490","wgerId":1490,"name":"Kickback triceps allongé","muscle":"bras","equipment":"elastiques","desc":"Réglez le banc à un angle de 60 degrés. Tenez-vous immobile et reposez le haut du corps sur le banc incliné, en veillant à maintenir tout votre corps presque en ligne droite. Serrez les omoplates l'une vers l'autre, de sorte que vos coudes se trouvent derrière le tronc et que vos bras soient presque parallèles au sol. Levez les haltères jusqu'à ce que vos bras forment une ligne droite. Redescendez lentement les haltères à la position initiale. La position initiale correspond à un angle droit entre le bras et l'avant-bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1700","wgerId":1700,"name":"Soulevé de terre roumain à la barre (RDL)","muscle":"jambes","equipment":"barre","desc":"### **Exécution** 1. **Charnière au niveau des hanches :** * Poussez vos **hanches vers l'arrière**, en gardant une légère flexion des genoux (genoux souples). * Abaissez la barre **le long de l'avant de vos cuisses et de vos tibias** tout en maintenant une **colonne neutre**. * Gardez la barre **près de votre corps**.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1496","wgerId":1496,"name":"Variante haut des pectoraux aux haltères","muscle":"pectoraux","equipment":"elastiques","desc":"L'haltère en main à la manière d'un curl, inclinez le corps vers le bras pour aider à monter l'haltère au-dessus de la poitrine, à côté de la tête, afin d'activer la combinaison pectoraux et deltoïdes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1497","wgerId":1497,"name":"DB Underhand bench press","muscle":"pectoraux","equipment":"barre","desc":"Poignée sous la main DB, effectuer un mouvement normal de la presse à banc, en gardant les coudes près de la poitrine","tips":["Poignée sous la main DB, effectuer un mouvement normal de la presse à banc, en gardant les coudes près de la poitrine"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1498","wgerId":1498,"name":"Elbows Tucked DB Bench Press","muscle":"bras","equipment":"barre","desc":"Coudes Tucked DB Bench Press, mouvement de la presse thoracique se concentrant sur les triceps. DB reste parallèle au corps","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1514","wgerId":1514,"name":"Marche latérale","muscle":"fessiers","equipment":"none","desc":"La marche latérale, également appelée pas de côté ou marche en squat, est un type d'exercice où vous vous déplacez sur le côté en position de squat. Elle peut se pratiquer avec ou sans élastique de résistance. Ces exercices renforcent les abducteurs de la hanche, les fessiers et d'autres muscles stabilisateurs.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1501","wgerId":1501,"name":"Variante de rowing gorille aux haltères","muscle":"dos","equipment":"elastiques","desc":"Penchez-vous légèrement vers l'avant, genoux fléchis, pour imiter une position de gorille, puis tirez les haltères en rowing vers la poitrine. Les haltères restent droits (pouces pointés vers le haut).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1502","wgerId":1502,"name":"DB Cross Body Hammer Curls","muscle":"bras","equipment":"elastiques","desc":"Boucles de biceps en croix avec haltère, travaille sur le braccialis","tips":["Boucles de biceps en croix avec haltère, travaille sur le braccialis"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1503","wgerId":1503,"name":"Dumbbell Frog Press","muscle":"fessiers","equipment":"elastiques","desc":"Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.","tips":["Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1504","wgerId":1504,"name":"Développé Bradford aux haltères","muscle":"epaules","equipment":"elastiques","desc":"À partir d'une prise des haltères tenus devant en position de développé militaire, poussez au-dessus de la tête, ramenez les haltères vers l'arrière des épaules, redescendez, puis poussez de nouveau vers l'avant.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1529","wgerId":1529,"name":"Pointes de pieds à la barre (toes to bar)","muscle":"abdos","equipment":"none","desc":"Le nom « toes to bar » (pointes de pieds à la barre) dit tout : cet exercice, dans lequel vous êtes suspendu à une barre de traction, consiste à amener vos pointes de pieds vers la barre, en direction de votre visage. Cela sollicite vraiment vos abdominaux. Le « toes to bar » est populaire dans les programmes de fitness fonctionnel comme Freeletics et CrossFit, et c'est un exercice efficace pour travailler la tablette de chocolat.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1508","wgerId":1508,"name":"High-Incline Smith Machine Press","muscle":"epaules","equipment":"none","desc":"Réglez le banc sur une inclinaison de 45-60 °. Touchez le haut de la poitrine avec la barre.","tips":["Réglez le banc sur une inclinaison de 45-60 °. Touchez le haut de la poitrine avec la barre."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1511","wgerId":1511,"name":"Kong curl","muscle":"bras","equipment":"elastiques","desc":"Cet exercice ressemble quelque peu à un curl à la poulie et à un écarté à la poulie. Mais au lieu de cibler les pectoraux ou les biceps, il sollicite le muscle brachial, responsable de cette largeur de bras visible de face. Pendant l'exercice, maintenez l'avant-bras en pronation, avec une position de départ d'environ 45 degrés de pronation. Commencez avec les coudes légèrement fléchis et effectuez le curl en alternance jusqu'à ce que vos mains (le pouce en premier) atteignent le haut du milieu de votre poitrine (à la manière dont Kong frappe son torse, d'où le nom de cet exercice).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1512","wgerId":1512,"name":"Drop curl","muscle":"bras","equipment":"elastiques","desc":"Réalisés dans une position modifiée et à un rythme lent, les drop curls sollicitent efficacement le muscle brachial pour gagner en largeur de bras. La position de départ se fait avec les deux bras légèrement inclinés l'un vers l'autre à hauteur de poitrine, un haltère dans chaque main. Abaissez un haltère lentement et de manière contrôlée jusqu'à la quasi-extension complète du bras pendant la première moitié du curl, puis remontez-le jusqu'à la position de départ, pendant que l'autre haltère reste en position initiale. Abaissez ensuite l'autre haltère. Cela maintient la tension sur le muscle brachial. Une fois passé le repère des 90 degrés lo","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1515","wgerId":1515,"name":"Leg Press Toe Press","muscle":"jambes","equipment":"none","desc":"Déplacez la presse à jambes en utilisant vos mollets en plaçant vos pieds au bas de la plate-forme.","tips":["Déplacez la presse à jambes en utilisant vos mollets en plaçant vos pieds au bas de la plate-forme."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1516","wgerId":1516,"name":"Handstand","muscle":"epaules","equipment":"none","desc":"Se tenir debout en appuyant les bras dans le sol et en contractant le noyau et les fessiers","tips":["Se tenir debout en appuyant les bras dans le sol et en contractant le noyau et les fessiers"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1519","wgerId":1519,"name":"Extension des triceps au-dessus de la tête","muscle":"dos","equipment":"barre","desc":"**Extension des triceps au-dessus de la tête avec barre EZ – Guide rapide** La **position au-dessus de la tête** *met l'accent sur le chef long* des triceps (parce qu'il est étiré sous la charge), mais l'exercice **sollicite bien les trois chefs du triceps** (long, latéral et médial) dans une certaine mesure pendant l'extension. 1. **Préparation** : Asseyez-vous sur un banc (ou tenez-vous debout) et saisissez une barre EZ avec une prise serrée en pronation. Levez la barre au-dessus de la tête, bras complètement tendus. Gardez la sangle abdominale contractée et les coudes près de la tête. 2. **Exécution** : Abaissez lentement la barre derrière","tips":["**Fin** : Tendez à nouveau vos bras pour revenir à la position de départ, en contractant vos triceps en haut"],"image":"https://wger.de/media/exercise-images/1519/fab7f641-27d4-40b5-8edd-1a0a137bfd94.gif","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1693","wgerId":1693,"name":"Maintien statique incliné","muscle":"pectoraux","equipment":"elastiques","desc":"### **Exécution** 1. **Position de maintien :** * Abaissez les haltères **à quelques centimètres au-dessus de votre poitrine**, environ au **point médian** d'un développé incliné classique. * C'est là que le haut de vos pectoraux est sous tension maximale. 2. **Maintien statique :** * Tenez la position pendant **20 à 45 secondes** en gardant les pectoraux contractés. * Respirez lentement tout en restant tendu, **ne relâchez pas vos pectoraux ni vos épaules**. 3. **Fin de la série :** * Après le maintien, abaissez les haltères avec précaution et reposez-vous.","tips":["**Maintien statique :** * Tenez la position pendant **","**Fin de la série :** * Après le maintien, abaissez les haltères avec précaution et reposez-vous"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1521","wgerId":1521,"name":"Pendular hack","muscle":"jambes","equipment":"none","desc":"Hack pendulaire, réalisé sur une machine pendulaire","tips":["Hack pendulaire, réalisé sur une machine pendulaire"],"image":"https://wger.de/media/exercise-images/1521/e4e4aa78-3c96-4b1d-95c0-f9f73a0779d0.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1694","wgerId":1694,"name":"Développé à la machine sur plat","muscle":"pectoraux","equipment":"barre","desc":"### **Exécution** 1. **Position de départ :** * Coudes fléchis à environ 90°, mains juste à l'extérieur de votre poitrine. * Gardez les poignets droits et alignés avec vos avant-bras. 2. **Phase de poussée (concentrique) :** * Poussez les poignées vers l'avant jusqu'à ce que vos bras soient **presque complètement tendus**, sans verrouiller. * Concentrez-vous sur la **contraction de vos pectoraux** en fin de mouvement. 3. **Phase de retour (excentrique) :** * Ramenez lentement les poignées vers votre poitrine, en ressentant l'**étirement dans vos pectoraux**. * Maintenez la tension, ne laissez pas la pile de poids reposer entre les répétitions","tips":["**Position de départ :** * Coudes fléchis à environ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1523","wgerId":1523,"name":"Poussée de traîneau","muscle":"jambes","equipment":"none","desc":"1. Chargez le traîneau avec 25 % de votre charge maximale. Si vous ne la connaissez pas, choisissez un poids que vous pouvez pousser pendant 10 minutes avec de courtes pauses. Les débutants peuvent choisir de pousser le traîneau sans poids. 2. Tenez-vous derrière le traîneau et saisissez les barres avec une prise haute. 3. Contractez vos abdominaux et commencez à pousser le traîneau vers l'avant aussi vite que possible, en exploitant toute la force de vos jambes. Étendez les hanches et les genoux à mesure que vous faites avancer le traîneau. Votre position de pied doit ressembler à votre foulée naturelle de course.","tips":["Chargez le traîneau avec","Tenez-vous derrière le traîneau et saisissez les barres avec une prise haute"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1524","wgerId":1524,"name":"Cordes ondulatoires","muscle":"jambes","equipment":"none","desc":"1. Tenez les extrémités de la corde à bout de bras devant vos hanches, les mains écartées de la largeur des épaules. 2. Gainez vos abdominaux et commencez à lever et abaisser chaque bras en alternance, de manière explosive. 3. Continuez à alterner les bras pendant trois à quatre séries de 1 à 2 minutes.","tips":["Tenez les extrémités de la corde à bout de bras devant vos hanches, les mains écartées de la largeur des épaules","Gainez vos abdominaux et commencez à lever et abaisser chaque bras en alternance, de manière explosive","Continuez à alterner les bras pendant trois à quatre séries de"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1525","wgerId":1525,"name":"Slams de ballon (ball slams)","muscle":"dos","equipment":"none","desc":"1. Tenez-vous debout, les pieds écartés d'environ la largeur des épaules, les genoux et les hanches légèrement fléchis, en tenant le ballon des deux mains à hauteur de poitrine. Gainez vos abdominaux et conservez une bonne posture. 2. Tendez les genoux et poussez les hanches vers l'avant tout en soulevant le ballon. Cherchez à être le plus grand possible : le ballon au-dessus de la tête, les bras levés, les hanches légèrement vers l'avant et sur la pointe des pieds, portés par l'élan de votre poussée. 3. Utilisez vos abdominaux et vos bras pour projeter le medicine ball droit vers le sol entre vos pieds, avec le plus de force possible. Recule","tips":["Tendez les genoux et poussez les hanches vers l'avant tout en soulevant le ballon"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1526","wgerId":1526,"name":"Machine de ski (ski erg)","muscle":"jambes","equipment":"none","desc":"1. Commencez debout sur la plateforme, les pieds écartés de la largeur des hanches. 2. Levez les bras au-dessus de la tête pour saisir les poignées, paumes tournées vers l'intérieur. 3. Relâchez légèrement les genoux, puis reculez les fesses comme si vous fermiez une porte derrière vous, tout en tirant les bras droit vers le bas le long de vos hanches jusqu'à ce que vos mains passent à côté de vos genoux. 4. Ensuite, ramenez vos bras au-dessus de la tête tout en poussant les hanches vers l'avant jusqu'à vous tenir debout, bras complètement tendus. 5. Répétez selon un nombre de répétitions, une durée ou une distance.","tips":["Commencez debout sur la plateforme, les pieds écartés de la largeur des hanches","Levez les bras au-dessus de la tête pour saisir les poignées, paumes tournées vers l'intérieur","Répétez selon un nombre de répétitions, une durée ou une distance"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1527","wgerId":1527,"name":"Pendulum Squat","muscle":"jambes","equipment":"none","desc":"Placez vos pieds au milieu de la plaque à environ la largeur des épaules. Tendez votre torse. Gardez votre cou détendu.","tips":["Placez vos pieds au milieu de la plaque à environ la largeur des épaules. Tendez votre torse. Gardez votre cou détendu."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1528","wgerId":1528,"name":"Glute drive (machine à fessiers)","muscle":"fessiers","equipment":"none","desc":"Allongez-vous sur le coussin dorsal et attachez-vous avec la ceinture. Placez vos pieds écartés de la largeur des épaules. Ils doivent être légèrement ouverts vers l'extérieur.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1530","wgerId":1530,"name":"Curls avec haltères allongé","muscle":"bras","equipment":"barre","desc":"Prenez un haltère dans chaque main et allongez-vous sur le dos sur un banc, comme pour un développé couché classique. Laissez vos bras pendre sur les côtés, les haltères touchant éventuellement le sol. Commencez maintenant à soulever les haltères vers le haut jusqu'à ce que vos avant-bras soient perpendiculaires au plafond. Abaissez lentement les haltères jusqu'à ce qu'ils touchent presque à nouveau le sol. Gardez les coudes en place pour minimiser la triche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1695","wgerId":1695,"name":"Tractions (prise large)","muscle":"dos","equipment":"none","desc":"**Exécution** 1. **Phase de tirage (concentrique) :** * Tirez vos **coudes vers le bas et légèrement en arrière**, en amenant votre poitrine **vers la barre**. * Concentrez-vous sur le fait de mener le mouvement avec la **poitrine**, pas avec le menton. * Gardez vos **épaules abaissées** (évitez de hausser les épaules). 2. **Position haute :** * Le menton doit dépasser la barre (ou au moins atteindre son niveau). * Marquez une brève pause avec une **contraction du grand dorsal**.","tips":["**Position haute :** * Le menton doit dépasser la barre (ou au moins atteindre son niveau)"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1698","wgerId":1698,"name":"Rowing à la barre (prise en pronation)","muscle":"dos","equipment":"barre","desc":"### **Exécution** 1. **Position de départ :** * Tenez la barre avec les bras complètement tendus vers le sol. * Maintenez la tension dans votre grand dorsal et les muscles du dos.","tips":["**Position de départ :** * Tenez la barre avec les bras complètement tendus vers le sol"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1699","wgerId":1699,"name":"Rowing à la barre (prise en supination)","muscle":"dos","equipment":"barre","desc":"### **Exécution** 1. **Position de départ :** * Tenez la barre avec les bras complètement tendus vers le sol. * Maintenez la tension dans votre grand dorsal et les muscles du dos.","tips":["**Position de départ :** * Tenez la barre avec les bras complètement tendus vers le sol"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1536","wgerId":1536,"name":"Delt Stretch","muscle":"epaules","equipment":"none","desc":"Étirez vos deltoïdes pendant un certain temps.","tips":["Étirez vos deltoïdes pendant un certain temps."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1537","wgerId":1537,"name":"Pull-up Isometric Hold","muscle":"bras","equipment":"none","desc":"Hold the pull-up movement in any position","tips":["Hold the pull-up movement in any position"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1701","wgerId":1701,"name":"Rowing lourd à un bras","muscle":"dos","equipment":"elastiques","desc":"### **Exécution** 1. **Phase de tirage (concentrique) :** * Tirez l'haltère **vers le bas de votre poitrine ou votre taille**, en menant le mouvement avec le **coude**. * Gardez votre torse **stable**, évitez de tourner ou de pivoter les épaules. * Marquez une pause en haut et **contractez votre grand dorsal**.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1703","wgerId":1703,"name":"Extensions des triceps en kickback","muscle":"bras","equipment":"barre","desc":"Le kickback avec haltère est un exercice de musculation populaire qui cible les triceps, à l'arrière du haut des bras. Il aide à renforcer et à tonifier les triceps, contribuant à la force et à l'esthétique générales des bras. Parmi les exercices qui sollicitent les muscles des bras, le kickback et ses variantes sont très efficaces. Vous pouvez facilement réaliser ces exercices avec des haltères, des câbles ou des élastiques de résistance.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1704","wgerId":1704,"name":"L-sit groupé (tuck L-sit)","muscle":"abdos","equipment":"barre","desc":"Le tuck L-sit est un maintien au poids du corps où vous vous soutenez sur des barres parallèles, des parallettes ou le sol avec les bras tendus, tout en ramenant vos genoux vers votre poitrine. Vos hanches restent levées, votre colonne reste droite et vos pieds flottent au-dessus du sol. L'objectif est de garder la sangle abdominale gainée, les épaules abaissées et les bras verrouillés tout en maintenant la position groupée. C'est un maintien statique très exigeant pour les abdominaux et stabilisateur pour les épaules, souvent utilisé comme progression vers le L-sit complet.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1577","wgerId":1577,"name":"Étirement Bretzel","muscle":"fessiers","equipment":"none","desc":"Comment réaliser l'étirement Bretzel Position de départ : Allongez-vous sur le dos sur une surface plane, comme un tapis. Fléchissez les genoux et posez les pieds à plat sur le sol. Placement des jambes : Levez la jambe droite et croisez-la par-dessus la jambe gauche, en posant le pied droit à l'extérieur du genou gauche. La jambe gauche doit rester à plat sur le sol. Placement des bras : Tendez le bras gauche sur le côté à hauteur d'épaule, en le gardant droit. Avec la main droite, tirez doucement le genou droit vers le sol, du côté gauche de votre corps. Étirement : En tirant le genou vers le bas, essayez de garder l'épaule gauche à plat su","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1545","wgerId":1545,"name":"Traction de l'archer","muscle":"dos","equipment":"none","desc":"La traction de l'archer est un exercice avancé au poids du corps qui renforce votre dos et vos biceps, servant de progression vers la traction à un bras. Elle tient son nom de la position de « tir à l'arc » que prend votre corps en haut du mouvement. Voici comment la réaliser : 1. Prise : Saisissez une barre de traction avec une prise en pronation plus large que la largeur des épaules. 2. Position de départ : Suspendez-vous, bras complètement tendus, en gainant la sangle abdominale et en gardant vos omoplates abaissées. 3. Le tirage : Tirez votre corps vers une main, comme pour une traction classique. En même temps, tendez l'autre bras sur le","tips":["Prise : Saisissez une barre de traction avec une prise en pronation plus large que la largeur des épaules","Le tirage : Tirez votre corps vers une main, comme pour une traction classique","Maintien et descente : Maintenez brièvement la position haute où un bras est fléchi et tire, et l'autre est tendu","Alternez : Répétez le mouvement en tirant vers la main opposée"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1546","wgerId":1546,"name":"Larsen Press","muscle":"pectoraux","equipment":"barre","desc":"Placez vos jambes sur un banc séparé et appuyez sans entraînement des jambes","tips":["Placez vos jambes sur un banc séparé et appuyez sans entraînement des jambes"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1706","wgerId":1706,"name":"Squats bulgares haltères","muscle":"fessiers","equipment":"elastiques","desc":"Le squat bulgare consiste à faire un squat sur une jambe avec le pied arrière en appui sur une plateforme surélevée. Le fait de surélever votre jambe sur un banc crée une instabilité et augmente l'amplitude de mouvement de l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1548","wgerId":1548,"name":"Stair Master (simulateur d'escaliers)","muscle":"jambes","equipment":"none","desc":"Machine de cardio et de renforcement du bas du corps conçue pour simuler la montée d'escaliers. Elle offre un entraînement à faible impact et haute intensité qui cible les jambes, les fessiers et la sangle abdominale tout en améliorant l'endurance cardiovasculaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1492","wgerId":1492,"name":"High Row","muscle":"dos","equipment":"none","desc":"S'agenouiller sur une jambe et tirer le câble vers le bas tout en enfonçant le coude dans les lattes.","tips":["S'agenouiller sur une jambe et tirer le câble vers le bas tout en enfonçant le coude dans les lattes."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1707","wgerId":1707,"name":"Elevación lateral polea","muscle":"epaules","equipment":"barre","desc":"Élévation latérale unilatérale à l'aide d'une perche","tips":["Élévation latérale unilatérale à l'aide d'une perche"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1493","wgerId":1493,"name":"Bayesian Curl","muscle":"bras","equipment":"none","desc":"Boucle de câble avec épaule tendue (vers l'arrière)","tips":["Boucle de câble avec épaule tendue (vers l'arrière)"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1509","wgerId":1509,"name":"Extension des triceps à la poulie (kickback)","muscle":"bras","equipment":"none","desc":"Saisissez la poignée et tirez votre coude vers le haut et légèrement en arrière, un peu au-dessus de votre torse. Gardez le bras parallèle au sol pendant toute la durée de la série.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1710","wgerId":1710,"name":"Étirement du billot de boucher (butcher's block)","muscle":"dos","equipment":"barre","desc":"1. Agenouillez-vous, les mains jointes 2. Posez les coudes sur un banc devant vous et abaissez la poitrine vers le bas 3. Gardez les coudes fléchis avec une bonne posture et maintenez la position","tips":["Agenouillez-vous, les mains jointes","Posez les coudes sur un banc devant vous et abaissez la poitrine vers le bas","Gardez les coudes fléchis avec une bonne posture et maintenez la position"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1554","wgerId":1554,"name":"Pompe avec applaudissement","muscle":"pectoraux","equipment":"none","desc":"La pompe avec applaudissement est un mouvement explosif du haut du corps qui développe la puissance et la force des fibres rapides. Elle ajoute un défi pliométrique à la pompe classique en exigeant que les mains quittent le sol au milieu de la répétition. 1. Commencez dans une solide position de pompe, les mains légèrement plus écartées que la largeur des épaules et la sangle abdominale gainée 2. Abaissez votre corps puis poussez de manière explosive contre le sol avec assez de force pour décoller vos mains. 3. Tapez rapidement vos mains l'une contre l'autre à hauteur de poitrine avant de les replacer au sol. 4. Réceptionnez-vous avec les cou","tips":["Abaissez votre corps puis poussez de manière explosive contre le sol avec assez de force pour décoller vos mains","Tapez rapidement vos mains l'une contre l'autre à hauteur de poitrine avant de les replacer au sol","Réceptionnez-vous avec les coudes souples pour absorber l'impact et enchaînez immédiatement avec la répétition suivante"],"image":"https://wger.de/media/exercise-images/1554/49207a62-8799-4b47-8c0b-7bde02926f3d.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1711","wgerId":1711,"name":"Étirement du dormeur (sleeper stretch)","muscle":"epaules","equipment":"none","desc":"1. Allongez-vous sur le côté de façon à reposer un peu de poids sur votre omoplate pour la maintenir immobile 2. Tendez votre bras à 90 degrés devant vous, reposant sur le sol ou le tapis 3. Levez votre main avec votre coude de sorte que vos doigts pointent vers le plafond et votre paume vers vos pieds 4. En gardant votre coude immobile, abaissez doucement votre paume vers le sol","tips":["Allongez-vous sur le côté de façon à reposer un peu de poids sur votre omoplate pour la maintenir immobile","Tendez votre bras à","Levez votre main avec votre coude de sorte que vos doigts pointent vers le plafond et votre paume vers vos pieds","En gardant votre coude immobile, abaissez doucement votre paume vers le sol"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1510","wgerId":1510,"name":"Neutral Grip Lat Pulldown","muscle":"dos","equipment":"none","desc":"Lat tire vers le bas avec une prise neutre sur la barre.","tips":["Lat tire vers le bas avec une prise neutre sur la barre."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1556","wgerId":1556,"name":"Devil's press","muscle":"epaules","equipment":"elastiques","desc":"Le Devil's Press est un mouvement hybride combinant un burpee avec haltères et un arraché à deux haltères. C'est un exercice complet et de haute intensité qui développe la force, la puissance et le conditionnement métabolique. 1. Commencez avec un haltère dans chaque main et réalisez un burpee, en laissant votre poitrine toucher le sol tout en tenant les haltères. 2. Ramenez vos pieds vers l'avant d'un saut explosif et balancez les haltères entre vos jambes. 3. Propulsez les haltères au-dessus de la tête en un seul mouvement continu, en verrouillant vos bras. 4. Abaissez les haltères avec contrôle pour revenir à la position de départ et répét","tips":["Ramenez vos pieds vers l'avant d'un saut explosif et balancez les haltères entre vos jambes","Propulsez les haltères au-dessus de la tête en un seul mouvement continu, en verrouillant vos bras","Abaissez les haltères avec contrôle pour revenir à la position de départ et répétez"],"image":"https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1513","wgerId":1513,"name":"Extension des triceps à la poulie au-dessus de la tête","muscle":"bras","equipment":"none","desc":"Utilisez une corde, dos à la machine à poulie. Tendez vos bras jusqu'à l'extension complète, puis inversez le mouvement en résistant pendant la phase négative.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1531","wgerId":1531,"name":"Cable Curls","muscle":"bras","equipment":"none","desc":"Biceps s'enroule à l'aide de câbles. Peut être assis ou debout","tips":["Biceps s'enroule à l'aide de câbles. Peut être assis ou debout"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1689","wgerId":1689,"name":"Écarté à la poulie pour le milieu des pectoraux","muscle":"pectoraux","equipment":"none","desc":"### **Exécution** 1. **Position de départ :** Bras tendus sur les côtés (en grand « T »), en ressentant un étirement dans les pectoraux. 2. **Mouvement :** Rapprochez vos mains devant votre poitrine dans un **large geste d'accolade**. * Concentrez-vous sur la contraction des pectoraux au centre. * Ne **verrouillez pas les coudes** et n'en faites pas un développé. 3. **Retour :** Ouvrez lentement les bras pour revenir à la position de départ, en maintenant la tension sur les pectoraux.","tips":["**Position de départ :** Bras tendus sur les côtés (en grand « T »), en ressentant un étirement dans les pectoraux","**Mouvement :** Rapprochez vos mains devant votre poitrine dans un **large geste d'accolade**","**Retour :** Ouvrez lentement les bras pour revenir à la position de départ, en maintenant la tension sur les pectoraux"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1690","wgerId":1690,"name":"Écarté à la poulie pour le haut des pectoraux","muscle":"pectoraux","equipment":"none","desc":"### **Exécution** 1. **Position de départ :** * Bras le long du corps et légèrement en arrière, coudes légèrement fléchis. * Ressentez un léger étirement dans les pectoraux. 2. **Mouvement :** * Amenez vos mains **vers le haut et l'une vers l'autre** devant le haut de votre poitrine, à peu près **au niveau du menton et de la clavicule**. * Utilisez un mouvement fluide et contrôlé (évitez les à-coups). * **Contractez** vos pectoraux en haut pendant 1 à 2 secondes. 3. **Retour :** * Laissez lentement vos bras redescendre et s'écarter sur les côtés, en gardant le contrôle et la tension.","tips":["**Position de départ :** * Bras le long du corps et légèrement en arrière, coudes légèrement fléchis","**Retour :** * Laissez lentement vos bras redescendre et s'écarter sur les côtés, en gardant le contrôle et la tension"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1691","wgerId":1691,"name":"Écarté à la poulie pour le bas des pectoraux","muscle":"pectoraux","equipment":"none","desc":"### **Exécution** 1. **Position de départ :** * Bras tendus sur les côtés en forme de « Y ». * Ressentez un étirement dans les pectoraux (légère flexion des coudes, ne les verrouillez pas). 2. **Mouvement :** * Amenez vos mains **vers le bas et l'une vers l'autre** devant le **bas de votre poitrine ou le haut des abdominaux**, dans un mouvement d'arc fluide. * **Contractez fortement vos pectoraux** en bas pendant 1 à 2 secondes. 3. **Retour :** * Relevez lentement vos bras en suivant la même trajectoire jusqu'à ressentir un bon étirement dans les pectoraux. * Gardez le contrôle, ne laissez pas les poids vous tirer en arrière trop rapidement.","tips":["**Position de départ :** * Bras tendus sur les côtés en forme de « Y »"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1702","wgerId":1702,"name":"Tirage vertical à la poulie en prise large","muscle":"dos","equipment":"none","desc":"Le tirage vertical à la poulie est un exercice de tirage qui cible principalement le grand dorsal (souvent appelé « dorsaux ») dans le dos. Il consiste à tirer une barre ou une poignée fixée à un câble vers la poitrine, assis sur une machine spécialement conçue à cet effet. Le tirage vertical se réalise généralement en prise large, mais peut aussi se faire en prise serrée ou en supination pour cibler différents groupes musculaires du dos et des bras. C'est un exercice populaire pour développer la force du haut du corps et améliorer la posture.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1572","wgerId":1572,"name":"Bird Dog","muscle":"abdos","equipment":"none","desc":"Le Bird Dog est un exercice de stabilité du tronc qui améliore l'équilibre, la coordination et l'alignement de la colonne vertébrale. C'est un mouvement à faible impact, idéal pour renforcer la chaîne postérieure et améliorer le contrôle fonctionnel global. 1. Commencez à quatre pattes, les mains sous les épaules et les genoux sous les hanches, en gardant la colonne en position neutre. 2. Tendez simultanément le bras droit vers l'avant et la jambe gauche vers l'arrière, en gardant les hanches bien parallèles. 3. Marquez une courte pause en pleine extension tout en engageant les abdominaux et les fessiers. 4. Revenez à la position de départ et","tips":["Marquez une courte pause en pleine extension tout en engageant les abdominaux et les fessiers","Revenez à la position de départ et répétez du côté opposé"],"image":"https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1573","wgerId":1573,"name":"Roue abdominale","muscle":"abdos","equipment":"none","desc":"1. **Position de départ** : Agenouillez-vous au sol avec la roue abdominale placée devant vous. 2. **Saisissez la roue** : Tenez fermement les poignées. 3. **Déroulez** : Faites rouler lentement la roue vers l'avant en tendant le corps tout en gardant les abdominaux contractés. 4. **Revenez** : Ramenez la roue vers vos genoux en maintenant la tension dans les abdominaux.","tips":["**Position de départ** : Agenouillez-vous au sol avec la roue abdominale placée devant vous","**Saisissez la roue** : Tenez fermement les poignées","**Revenez** : Ramenez la roue vers vos genoux en maintenant la tension dans les abdominaux"],"image":"https://wger.de/media/exercise-images/1573/a9ab402b-61ef-4d60-b91a-df52bf7f41a9.jpg.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1574","wgerId":1574,"name":"Schwimmen","muscle":"jambes","equipment":"none","desc":"* 800m Schwimmen en 20 Minuten","tips":["* 800m Schwimmen en 20 Minuten"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1575","wgerId":1575,"name":"Standing Dowel Shoulder press","muscle":"jambes","equipment":"barre","desc":"Mobilité - pression de la cheville couchée ou pression de l'épaule de la cheville debout alternant entre l'avant et l'arrière","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1576","wgerId":1576,"name":"Snap Down","muscle":"jambes","equipment":"none","desc":"Commencez en position debout, les bras levés au-dessus de la tête et les orteils poussant dans le sol pour soulever les talons et vous grandir au maximum. À partir de cette position, effectuez un petit saut, les deux pieds décollant légèrement du sol. À l'atterrissage, fléchissez les genoux et commencez à basculer vers l'avant au niveau des hanches pour absorber la réception. Revenez à la position de départ et répétez. Vous devez sentir travailler les muscles du bas du corps. Commencez avec les bras et les genoux complètement tendus. Gardez un équilibre stable lors de la réception et maintenez brièvement cette position finale, n'allez pas tro","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1578","wgerId":1578,"name":"Charnière de hanche","muscle":"jambes","equipment":"barre","desc":"Description de l'exercice de charnière de hancheLa charnière de hanche est un schéma de mouvement fondamental qui consiste à se pencher au niveau des hanches tout en gardant la colonne en position neutre. Elle est couramment utilisée dans des exercices comme le soulevé de terre, le swing avec kettlebell et le good morning. Pour effectuer une charnière de hanche : Position de départ : Tenez-vous debout, les pieds écartés de la largeur des hanches et les genoux légèrement fléchis. Basculez au niveau des hanches : Poussez les hanches vers l'arrière tout en gardant le dos droit. Votre buste doit s'incliner vers l'avant et votre poitrine doit rest","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1579","wgerId":1579,"name":"Bronco","muscle":"jambes","equipment":"none","desc":"Test de condition physique pour le rugby. 5 séries de courses navettes de 20 m, 40 m et 60 m (20 yd, 45 yd, 65 yd / repère lointain à 45 yd) À réaliser le plus vite possible","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1580","wgerId":1580,"name":"Rowing landmine unilatéral perpendiculaire","muscle":"epaules","equipment":"barre","desc":"À l'aide d'un accessoire landmine, la barre orientée à 90 degrés sur le côté, basculez légèrement au niveau des hanches et saisissez la barre par le manchon à disques. Soulevez la barre jusqu'à hauteur de poitrine, le haut du bras parallèle au sol en haut du mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1581","wgerId":1581,"name":"Développé trapèzes","muscle":"dos","equipment":"barre","desc":"Allongé à plat, le bras pointé droit vers le haut et le coude complètement tendu, utilisez uniquement l'épaule pour soulever le poids aussi haut que possible sans inconfort, puis revenez à la position de repos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1581/b71a6710-5798-4639-ac5a-22a2cdae2036.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1582","wgerId":1582,"name":"Rotation interne en décubitus latéral","muscle":"dos","equipment":"barre","desc":"Allongé sur le côté et en utilisant le bras le plus proche du banc, maintenez le coude fléchi à 90 degrés et laissez le poids descendre vers le sol au-delà du banc, aussi bas que possible sans inconfort. Remontez le poids en utilisant uniquement la rotation de l'épaule vers l'épaule opposée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1582/5094fe30-eea2-4269-b0de-4b8a20558fd7.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1583","wgerId":1583,"name":"Supine press","muscle":"dos","equipment":"barre","desc":"Prenez une prise serrée et poussez perpendiculairement au banc. Restez à plat.","tips":["Prenez une prise serrée et poussez perpendiculairement au banc. Restez à plat."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1584","wgerId":1584,"name":"Marche ou course sur place","muscle":"jambes","equipment":"none","desc":"Exercice cardiovasculaire à faible impact qui simule la course sans se déplacer, idéal pour s'échauffer, améliorer l'endurance ou s'entraîner dans des espaces réduits.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1589","wgerId":1589,"name":"Leg and hip stretch","muscle":"jambes","equipment":"none","desc":"Des mouvements doux pour améliorer la souplesse du bas du corps et relâcher les tensions au niveau des hanches.","tips":["Des mouvements doux pour améliorer la souplesse du bas du corps et relâcher les tensions au niveau des hanches."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1590","wgerId":1590,"name":"Arm and neck stretch","muscle":"epaules","equipment":"none","desc":"Soulage la tension dans le haut du corps, particulièrement utile pour les personnes ayant des emplois de bureau ou des postures prolongées.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1591","wgerId":1591,"name":"Deep breathing (standing or seated)","muscle":"abdos","equipment":"none","desc":"Une technique de respiration consciente pour améliorer l'oxygénation, réduire le stress et se connecter au moment présent.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1592","wgerId":1592,"name":"Guided or free meditation","muscle":"jambes","equipment":"none","desc":"Un exercice de pleine conscience mentale qui aide à réduire l'anxiété, à améliorer la concentration et à améliorer le bien-être général.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1593","wgerId":1593,"name":"Split squat à la Smith machine","muscle":"jambes","equipment":"barre","desc":"Le **« Split squat à la Smith machine »** est un exercice de renforcement réalisé sur la Smith machine, idéal pour cibler les jambes et les fessiers. Il consiste à placer un pied vers l'avant et l'autre vers l'arrière, puis à abaisser le corps jusqu'à ce que la cuisse avant soit parallèle au sol tandis que la barre coulisse verticalement le long de la machine. Cet exercice aide à améliorer la stabilité, à corriger les déséquilibres musculaires et à réduire les contraintes sur le dos, offrant un environnement sûr pour l'entraînement en force.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1593/9815fcd6-cf40-4ddd-9b38-2eac25973de1.gif","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1696","wgerId":1696,"name":"Tractions (prise neutre)","muscle":"dos","equipment":"none","desc":"### **Exécution** 1. **Phase de traction (concentrique) :** * Tirez vos **coudes vers le bas et l'arrière**, en amenant votre **poitrine vers vos mains**. * Gardez les épaules **basses et rétractées** (évitez de hausser les épaules). * Concentrez-vous sur la contraction du **grand dorsal et du haut du dos** en position haute. 2. **Position haute :** * Le menton doit dépasser ou atteindre le niveau de vos mains. * Marquez une courte pause et **contractez fortement le grand dorsal**.","tips":["**Position haute :** * Le menton doit dépasser ou atteindre le niveau de vos mains"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1712","wgerId":1712,"name":"Étirement en flexion horizontale de l'épaule","muscle":"pectoraux","equipment":"none","desc":"1. Levez le bras sur le côté en posant la main sur un mur ou un encadrement de porte à côté de vous, à hauteur d'épaule 2. Tournez le corps à l'opposé du bras pour étirer les pectoraux, aussi loin que possible sans inconfort","tips":["Levez le bras sur le côté en posant la main sur un mur ou un encadrement de porte à côté de vous, à hauteur d'épaule","Tournez le corps à l'opposé du bras pour étirer les pectoraux, aussi loin que possible sans inconfort"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1719","wgerId":1719,"name":"Jalon caballero unialteral","muscle":"bras","equipment":"elastiques","desc":"``` Pull effectué en position de chevalier```","tips":["``` Pull effectué en position de chevalier```"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1709","wgerId":1709,"name":"Oiseau debout","muscle":"epaules","equipment":"none","desc":"1. Tenez-vous debout avec une bonne posture, une poignée de poulie dans chaque main, face à la machine 2. En partant les mains devant la poitrine, écartez les bras sur les côtés pour former un T, les coudes presque tendus 3. Ramenez lentement les bras vers l'avant jusqu'à la position de départ 4. Répétez en amenant les bras en forme de Y 5. Répétez en amenant les bras en forme de W 6. Répétez en amenant les bras en forme de L le long du corps","tips":["Tenez-vous debout avec une bonne posture, une poignée de poulie dans chaque main, face à la machine","En partant les mains devant la poitrine, écartez les bras sur les côtés pour former un T, les coudes presque tendus","Ramenez lentement les bras vers l'avant jusqu'à la position de départ","Répétez en amenant les bras en forme de Y","Répétez en amenant les bras en forme de W"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1724","wgerId":1724,"name":"Adduction debout (poulie)","muscle":"jambes","equipment":"none","desc":"Gardez les hanches bien parallèles et immobiles, en tirant le câble en travers de votre jambe opposée en utilisant uniquement l'intérieur de la cuisse. Ne laissez pas votre buste s'incliner ou pivoter : pas d'inclinaison latérale pour vous aider dans la répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1602","wgerId":1602,"name":"Élévation en scaption aux haltères","muscle":"dos","equipment":"elastiques","desc":"Position de départ : Tenez-vous debout, bien droit, les pieds écartés de la largeur des épaules. Tenez un haltère dans chaque main en prise neutre (paumes se faisant face). Gardez les coudes légèrement fléchis, les épaules relâchées et les omoplates ramenées vers l'arrière. Exécution : Levez lentement les haltères vers l'avant et légèrement sur les côtés, à un angle d'environ 30 à 45° par rapport au corps (entre une élévation frontale et une élévation latérale). Levez jusqu'à ce que les bras soient à peu près à hauteur d'épaule (ne montez pas au-dessus de la tête). Marquez une pause d'une seconde en position haute et ressentez l'activation de","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1603","wgerId":1603,"name":"Leg curl with elastic","muscle":"jambes","equipment":"elastiques","desc":"Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.","tips":["Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1604","wgerId":1604,"name":"Fente latérale glissée","muscle":"jambes","equipment":"barre","desc":"Tenez-vous debout, bien droit, les pieds écartés de la largeur des hanches, en tenant une kettlebell près de la poitrine en position goblet. Placez un pied sur un slider, un disque glissant ou une serviette. Gardez la poitrine relevée et les abdominaux engagés. Faites glisser lentement le pied vers l'extérieur en fléchissant le genou opposé, en abaissant les hanches dans une fente latérale. Gardez le genou de la jambe active aligné avec les orteils et évitez qu'il ne s'affaisse vers l'intérieur. La jambe inactive reste tendue et glisse en douceur sur le sol. Poussez dans le talon de la jambe fléchie pour revenir à la position de départ tout e","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1604/7695428e-bfed-4021-b987-498d93153995.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1605","wgerId":1605,"name":"Exercice d'adduction de Copenhague","muscle":"fessiers","equipment":"barre","desc":"Allongez-vous sur le côté, le coude placé directement sous l'épaule, comme dans une position de planche latérale. Posez la jambe supérieure sur un banc, l'intérieur du pied ou de la cheville reposant dessus. Soulevez les hanches et maintenez le corps en ligne droite tout en gardant la jambe inférieure décollée du sol. Cet exercice active fortement les adducteurs de la jambe supérieure tout en sollicitant également le tronc et les stabilisateurs de la hanche.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1606","wgerId":1606,"name":"Élévations de bras (T/Y/I)","muscle":"epaules","equipment":"none","desc":"Tenez-vous debout, bien droit, les pieds écartés de la largeur des hanches, les abdominaux engagés et les bras relâchés le long du corps. À partir de cette position, effectuez trois élévations de bras différentes pour cibler les épaules et le haut du dos : * **Élévation en T :** Levez les bras tendus sur les côtés jusqu'à ce qu'ils soient parallèles au sol, en formant un « T ». * **Élévation en Y :** Levez les bras vers le haut à un angle d'environ 45° par rapport au corps pour former un « Y ». * **Élévation en I :** Levez les bras tendus au-dessus de la tête, rapprochés l'un de l'autre, en formant un « I ». Gardez la colonne en position neut","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1607","wgerId":1607,"name":"Tractions typewriter","muscle":"bras","equipment":"none","desc":"Suspendez-vous à une barre de traction en prise pronation, légèrement plus large que la largeur des épaules. Tirez-vous vers le haut jusqu'à ce que votre menton dépasse la barre. En position haute, au lieu de redescendre tout droit, déplacez votre corps d'un côté en tendant un bras tout en gardant l'autre bras fléchi. Passez en douceur d'un côté à l'autre, comme le mouvement d'une machine à écrire, avant de redescendre. Cet exercice augmente le temps sous tension et renforce le grand dorsal, les biceps et les épaules tout en développant la force de tirage unilatérale.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1608","wgerId":1608,"name":"Curl biceps au poids du corps","muscle":"bras","equipment":"none","desc":"Placez-vous sous une barre droite (à hauteur de taille ou de poitrine environ). Saisissez la barre paumes tournées vers vous (prise supination), les mains écartées d'environ la largeur des épaules. Penchez-vous en arrière, bras tendus, de sorte que votre corps forme un angle avec le sol. En gardant les coudes hauts et près de la barre, tirez le haut du corps vers la barre en fléchissant les coudes, comme pour un curl biceps. Redescendez de manière contrôlée. Gardez les abdominaux contractés et le mouvement lent pour maximiser la tension sur les biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1723","wgerId":1723,"name":"Glute Kickback (Machine)","muscle":"fessiers","equipment":"none","desc":"Passez par le talon, pas par les orteils, pour atteindre le fessier. N'étirez pas trop le bas du dos vers le haut.","tips":["Passez par le talon, pas par les orteils, pour atteindre le fessier. N'étirez pas trop le bas du dos vers le haut."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1725","wgerId":1725,"name":"Rowing assis (machine)","muscle":"dos","equipment":"none","desc":"Gardez la poitrine relevée et resserrez les omoplates en fin de mouvement. N'arrondissez pas le dos et ne vous penchez pas vers l'avant pendant le tirage.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1725/f0ebd44e-b8e1-400c-b598-ca371f3a07af.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1612","wgerId":1612,"name":"Soulevé de terre sumo à la kettlebell","muscle":"jambes","equipment":"elastiques","desc":"Placez les pieds plus écartés que la largeur des épaules, les orteils tournés vers l'extérieur. Gardez le dos droit, les épaules en arrière et la poitrine relevée. Les genoux doivent suivre la même direction que les orteils et ne pas avancer. Lors de la remontée, il est conseillé de contracter les fessiers pour maximiser l'efficacité de l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1613","wgerId":1613,"name":"Kickback fessier à l'élastique","muscle":"fessiers","equipment":"elastiques","desc":"Le kickback fessier à l'élastique est un exercice réalisé à quatre pattes, où vous fixez une bande de résistance à votre pied et propulsez le talon vers l'arrière et le haut, en contractant le fessier en haut du mouvement, tout en gardant un tronc stable et le dos plat afin de cibler et de renforcer les muscles fessiers.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1613/a851fe9d-771f-44da-82f0-799e02ae3fd1.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1938","wgerId":1938,"name":"Cat-Cow","muscle":"jambes","equipment":"none","desc":"À quatre pattes. La colonne vertébrale de la voûte plantaire vers le haut (chat) puis vers le bas (vache). Respirez avec mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1615","wgerId":1615,"name":"Cardio sur tapis de course","muscle":"jambes","equipment":"none","desc":"Il s'agit d'un entraînement cardiovasculaire réalisé sur un tapis de course pour améliorer l'endurance, brûler des calories et favoriser la santé cardiaque. Il offre de nombreux avantages, comme la possibilité d'ajuster facilement la vitesse et l'inclinaison, ce qui permet une grande variété d'entraînements, de la marche en côte à l'entraînement par intervalles de haute intensité (HIIT) et aux séances de tempo. Pour optimiser les résultats, il est important de varier vos entraînements. Avantages du cardio sur tapis de course : - Amélioration de la santé cardiovasculaire : Un exercice aérobie régulier sur tapis de course renforce le cœur et le","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1615/7792295c-83b6-4ea8-9353-ce02f0ad2559.jpg.400x400_q85.jpg","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1616","wgerId":1616,"name":"Donkey kick à l'haltère","muscle":"jambes","equipment":"elastiques","desc":"Le donkey kick à l'haltère est un exercice efficace pour travailler les muscles fessiers et les ischio-jambiers. Cet exercice se réalise généralement à quatre pattes, en utilisant un haltère pour ajouter de la résistance. Les étapes pour le réaliser correctement sont décrites ci-dessous. Position de départ : Mettez-vous à quatre pattes sur un tapis, les mains alignées sous les épaules et les genoux alignés sous les hanches. Placement de l'haltère : Prenez un haltère et placez-le derrière le genou de la jambe que vous allez soulever. Assurez-vous qu'il soit bien maintenu pour éviter qu'il ne tombe pendant l'exercice. Exercice : Inspirez et, en","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1616/97e6fd98-2ca6-486f-b9b2-f0499fe38044.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1952","wgerId":1952,"name":"SMR Glutes (lax ball)","muscle":"jambes","equipment":"none","desc":"SMR Glutes (balle LAX) Partie de : Limber 11 Source : Joe DeFranco Prescription : 30 sec-2 min Type : soft_tissue","tips":["SMR Glutes (balle LAX) Partie de : Limber 11 Source : Joe DeFranco Prescription : 30 sec-2 min Type : soft_tissue"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1618","wgerId":1618,"name":"Cardio sur vélo d'appartement","muscle":"jambes","equipment":"none","desc":"Avantages du cardio sur vélo d'appartement Le cardio sur vélo d'appartement est une excellente forme d'exercice qui offre de multiples avantages pour la santé et le bien-être. Voici quelques-uns des plus notables : Amélioration de la santé cardiovasculaire Renforce le cœur : Un exercice régulier aide à améliorer l'efficacité du cœur et à réduire le risque de maladie cardiovasculaire. Améliore la circulation : Il favorise le flux sanguin, ce qui peut aider à abaisser la tension artérielle. Dépense calorique et perte de poids Efficace pour brûler des calories : Selon l'intensité, vous pouvez brûler entre 400 et 600 calories par heure. Aide à la","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1618/c18baedc-ff98-4fb2-b4f5-38a05c12f637.png.400x400_q85.png","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"fr"},{"id":"wger-1620","wgerId":1620,"name":"Élévation des mollets haltères assis","muscle":"jambes","equipment":"elastiques","desc":"L'élévation des mollets avec haltères en position assise est un exercice ciblé pour renforcer les muscles du bas de la jambe. Il suit le même schéma de mouvement que la version avec machine : vous placez le poids sur vos genoux, et en étendant et en fléchissant vos chevilles, vous déplacez le poids.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1620/edd40e39-e337-4460-a8dd-6127d40ddd16.jpeg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1742","wgerId":1742,"name":"Back Lever","muscle":"jambes","equipment":"none","desc":"Suspendu à une barre de traction orientée vers le bas avec les bras tendus","tips":["Suspendu à une barre de traction orientée vers le bas avec les bras tendus"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1732","wgerId":1732,"name":"Face pulls avec élastique jaune/vert","muscle":"dos","equipment":"elastiques","desc":"Face pulls à l'élastique – tirage horizontal debout. Saisissez l'élastique à hauteur du visage, tirez les coudes haut et large vers votre visage tout en resserrant les omoplates. Sollicite le haut du dos et l'arrière des épaules, et améliore la posture.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1732/d13b9adb-968e-4f73-95e6-b16690bcf616.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1733","wgerId":1733,"name":"Squat isométrique jusqu'à l'échec","muscle":"fessiers","equipment":"none","desc":"Squat isométrique jusqu'à l'échec : une technique d'entraînement en force Définition Le squat isométrique jusqu'à l'échec est une variante de l'exercice du squat dans laquelle vous maintenez une position de squat statique à un angle précis, en conservant la position jusqu'à ce que vos muscles ne puissent plus soutenir la contraction.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1733/4ef77069-beb2-4504-a4f3-b181d5f35212.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1734","wgerId":1734,"name":"Fente sur une jambe avec kettlebell","muscle":"jambes","equipment":"elastiques","desc":"Comment réaliser une fente sur une jambe avec kettlebell Préparation : Tenez-vous debout, pieds joints. Saisissez le kettlebell des deux mains par la poignée en le gardant près de votre poitrine, ou tenez-le d'une seule main (du même côté que la jambe qui travaille). Pas et descente : Faites un grand pas vers l'avant (ou vers l'arrière, ce qui est plus sûr pour vos genoux) avec une jambe, en abaissant les hanches jusqu'à ce que les deux genoux forment un angle de 90 degrés. Focalisation : Reportez votre poids sur la jambe avant (ou fléchie), en gardant le dos droit et le buste bien vertical. Retour : Poussez sur votre jambe avant pour revenir","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1734/782e2fbb-1267-476d-a817-14f3b83e0564.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1735","wgerId":1735,"name":"Presse à fessiers latérale sur une jambe","muscle":"jambes","equipment":"barre","desc":"La presse à fessiers latérale sur une jambe est une variante de la presse à cuisses où vous placez votre corps de côté sur l'appui, un pied posé haut et légèrement incliné pour pousser la charge, ce qui sollicite puissamment le fessier externe (moyen et petit fessier) et les ischio-jambiers pour un développement équilibré des jambes et de la stabilité. L'exercice demande de bien pousser à travers le talon et de garder le contrôle sans verrouiller complètement la jambe. Comment l'exécuter : Mise en place : Asseyez-vous dans la presse à cuisses, pivotez le corps sur une hanche et placez un pied en haut de la plateforme, à environ 45 degrés, les","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1735/43bca7d9-2333-43f3-8554-2d0b39fa2a07.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1726","wgerId":1726,"name":"Tirage bras tendus (poulie)","muscle":"dos","equipment":"none","desc":"Gardez les bras tendus mais sans les verrouiller, en tirant avec le grand dorsal et non avec les épaules. Ne laissez pas vos épaules se hausser pendant le mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1726/2e7e541b-5f55-405a-ae78-3e71b3f42db4.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1738","wgerId":1738,"name":"Tractions en prise neutre ou rowings TRX","muscle":"dos","equipment":"none","desc":"- **Traction : tirage vertical — sollicite davantage le grand dorsal (largeur du dos).** **Rowing TRX : tirage horizontal — sollicite davantage les rhomboïdes et les trapèzes (épaisseur du milieu du dos et posture).**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1738/0529acdf-ede8-42a2-a3e5-8d0c57b7a0e1.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1744","wgerId":1744,"name":"Élévations latérales à la machine","muscle":"epaules","equipment":"none","desc":"Les élévations latérales à la machine sont un exercice d'isolation pour les deltoïdes latéraux, réalisé sur une machine pour plus de stabilité. Elles sollicitent l'épaule externe en soulevant les appuis ou les poignées sur les côtés jusqu'à la hauteur des épaules, puis en les abaissant lentement, en gardant les coudes légèrement fléchis et les trapèzes relâchés pour bien cibler les deltoïdes. Cet exercice aide à développer la largeur des épaules en évitant les balancements et en offrant une tension constante, ce qui en fait un excellent choix pour les débutants ou comme exercice de finition. Comment réaliser les élévations latérales à la mach","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1744/cb9263c4-39fc-4261-8d30-a5d6d57841c1.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1727","wgerId":1727,"name":"Tirage latéral bras tendu (poulie)","muscle":"dos","equipment":"none","desc":"Gardez le buste immobile, en tirant la poignée vers le bas le long de votre côté en utilisant la partie externe du grand dorsal. Ne tournez pas le corps et ne faites pas pivoter le buste pour tricher dans la répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1747","wgerId":1747,"name":"Squat à la machine Smith","muscle":"fessiers","equipment":"none","desc":"Technique et exécution Le squat à la machine Smith est une variante du squat traditionnel à la barre qui utilise une barre guidée à trajectoire fixe. Voici un détail de la technique correcte : Position de départ Placement des pieds : Positionnez les pieds légèrement en avant de la barre, écartés d'environ la largeur des épaules Position de la barre : Posez la barre sur le haut de vos trapèzes et de vos épaules, comme pour un squat arrière traditionnel Posture : Les pieds peuvent être légèrement orientés vers l'extérieur pour une rotation naturelle des hanches Mouvement du squat Déverrouillez la barre en la faisant pivoter pour la libérer des ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1747/af9647dd-04ec-4adf-9c07-4e33edb77277.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1743","wgerId":1743,"name":"Essuie-glaces","muscle":"abdos","equipment":"none","desc":"Suspendez-vous à une barre de traction et levez les jambes vers le plafond. Déplacez le bas du corps de gauche à droite, jambes tendues, comme un essuie-glace.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1737","wgerId":1737,"name":"Assisted chin-ups","muscle":"bras","equipment":"none","desc":"Chin-ups avec assistance machine (contrepoids)","tips":["Chin-ups avec assistance machine (contrepoids)"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1739","wgerId":1739,"name":"Shrimp Squad","muscle":"fessiers","equipment":"none","desc":"Équipe à une jambe où une jambe est derrière vous.","tips":["Équipe à une jambe où une jambe est derrière vous."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1754","wgerId":1754,"name":"45° lateral raises","muscle":"jambes","equipment":"elastiques","desc":"soulèvement d'haltères dans l'espace entre les soulèvements avant et latéraux","tips":["soulèvement d'haltères dans l'espace entre les soulèvements avant et latéraux"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1741","wgerId":1741,"name":"L-Sit Pull-ups","muscle":"dos","equipment":"none","desc":"Les L-Sit Pull-ups entraînent les muscles du haut du corps et du tronc.","tips":["Les L-Sit Pull-ups entraînent les muscles du haut du corps et du tronc."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1766","wgerId":1766,"name":"Planche avec extension du bras","muscle":"abdos","equipment":"none","desc":"Placez votre corps en position de planche, le regard tourné vers le sol. Levez un bras devant vous puis ramenez-le. Répétez avec l'autre bras. Levez et ramenez lentement en gardant le corps aussi immobile que possible.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1774","wgerId":1774,"name":"Dips sur chaise","muscle":"bras","equipment":"none","desc":"**Position de départ :** Asseyez-vous sur le bord avant d'une chaise, le dos droit, les mains tenant le bord avant. En tenant toujours le bord de la chaise, les bras tendus, soulevez vos fessiers et avancez légèrement de manière à vous trouver à quelques centimètres de la chaise. **Étapes :** 1. Abaissez lentement votre corps, en gardant le dos droit, jusqu'à ce que vos bras forment un angle droit. 2. Relevez votre corps jusqu'à la position initiale, les bras tendus. 3. Répétez.","tips":["Abaissez lentement votre corps, en gardant le dos droit, jusqu'à ce que vos bras forment un angle droit","Relevez votre corps jusqu'à la position initiale, les bras tendus"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1621","wgerId":1621,"name":"Rowing unilatéral à la poulie","muscle":"dos","equipment":"barre","desc":"Placez un banc à dossier vertical devant la machine de rowing à la poulie. Positionnez-le de manière à pouvoir vous concentrer sur un seul côté, puis effectuez des tirages lents en vous concentrant sur les muscles latéraux et en veillant à maintenir la tension dans ces muscles en position étirée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1621/ca1bc68d-9c36-4dd3-8ec4-496c57b5c564.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1728","wgerId":1728,"name":"Rotation interne de l'épaule (poulie)","muscle":"epaules","equipment":"none","desc":"Gardez le coude collé à votre côté comme s'il y était fixé à la colle forte. Ne faites pas pivoter le buste : seul l'avant-bras doit bouger.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1729","wgerId":1729,"name":"Rotation externe de l'épaule (poulie)","muscle":"epaules","equipment":"none","desc":"Gardez le coude fixe le long de votre côté et faites pivoter l'avant-bras vers l'extérieur en douceur. Ne laissez pas votre poignet ou votre coude dériver vers le haut : restez dans un seul plan.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1730","wgerId":1730,"name":"Side Lateral Raise (Cable)","muscle":"dos","equipment":"none","desc":"Soulevez avec vos coudes en tête, pas vos mains. Ne haussez pas les épaules ; gardez les pièges silencieux.","tips":["Soulevez avec vos coudes en tête, pas vos mains. Ne haussez pas les épaules ; gardez les pièges silencieux."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1731","wgerId":1731,"name":"Front Raise (Cable)","muscle":"epaules","equipment":"none","desc":"Soulevez la poignée en un léger arc avec un mouvement contrôlé. Ne balancez pas votre torse pour démarrer le rep.","tips":["Soulevez la poignée en un léger arc avec un mouvement contrôlé. Ne balancez pas votre torse pour démarrer le rep."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1745","wgerId":1745,"name":"Élévation frontale à la poulie avec barre courte","muscle":"epaules","equipment":"none","desc":"L'élévation frontale à la poulie avec barre courte isole vos deltoïdes antérieurs (épaules avant) grâce à une tension constante. Tenez-vous debout, dos tourné à une poulie basse, saisissez la barre en prise pronation et levez-la devant vous jusqu'à la hauteur des épaules, les bras légèrement fléchis, en évitant tout balancement et en gardant la sangle abdominale gainée pour un mouvement contrôlé vers le haut et vers le bas. Utilisez une charge légère à modérée, en privilégiant des répétitions lentes et contrôlées pour bien sentir le muscle travailler, sans recourir à l'élan. Comment réaliser l'élévation frontale à la poulie (barre) Mise en pl","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1745/9c92843a-6b90-428b-a868-9af4b11bad38.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1751","wgerId":1751,"name":"Tirage à la poulie entre les jambes","muscle":"fessiers","equipment":"none","desc":"Le **tirage à la poulie entre les jambes** est un exercice pour le bas du corps qui sollicite les fessiers et les ischio-jambiers grâce à un mouvement de charnière de hanche. Pour l'exécuter, fixez une corde à la poulie réglée au plus bas, placez-vous dos à la machine avec la corde entre vos jambes, et avancez d'un pas pour créer de la tension. En gardant le dos plat et les genoux légèrement déverrouillés, poussez vos hanches vers l'arrière comme si vous cherchiez à fermer une porte derrière vous, jusqu'à sentir un étirement profond dans vos ischio-jambiers. Pour terminer la répétition, propulsez vos hanches vers l'avant de façon explosive po","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1752","wgerId":1752,"name":"Side lateral raise - Front (Cable)","muscle":"epaules","equipment":"none","desc":"dans un cablerack, faites une élévation latérale latérale avec le câble devant vous, avec la mise au point en tension à l'arrière de votre épaule.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1753","wgerId":1753,"name":"Side lateral raise - Back (Cable)","muscle":"epaules","equipment":"none","desc":"sur un porte-câble, faites une élévation latérale latérale avec le câble derrière vous. Concentrez-vous sur la tension à l'avant de l'épaule.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1772","wgerId":1772,"name":"Crunch inversé","muscle":"abdos","equipment":"none","desc":"1. Allongez-vous 2. Placez vos mains près de vos fessiers (souvent légèrement devant, ou en dessous, ou les deux) 3. Levez les jambes, mais à environ 70 % du mouvement vous devriez pouvoir lever aussi le bassin 4. (optionnel/variable) Maintenez 1 à 2 secondes en haut 5. Revenez à la position de départ","tips":["Allongez-vous","Placez vos mains près de vos fessiers (souvent légèrement devant, ou en dessous, ou les deux)","Levez les jambes, mais à environ","(optionnel/variable) Maintenez","Revenez à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1773","wgerId":1773,"name":"Legend Incline Bench Press","muscle":"pectoraux","equipment":"none","desc":"presse à banc incliné sur machine LeverEdge.","tips":["presse à banc incliné sur machine LeverEdge."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1755","wgerId":1755,"name":"Shoulder Y-pull cable","muscle":"jambes","equipment":"none","desc":"sur un rack à câbles croisent les câbles et tirent les coudes au plafond près du corps.","tips":["sur un rack à câbles croisent les câbles et tirent les coudes au plafond près du corps."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1771","wgerId":1771,"name":"Flexion des poignets à la poulie","muscle":"jambes","equipment":"none","desc":"1. Tendez le bras vers le bas, puis levez légèrement l'avant-bras 2. Mettez le poignet en supination (paume vers le haut) 3. Réglez la hauteur de la poulie pour que la poignée se trouve dans votre main en supination 4. Réalisez le mouvement en enroulant les paumes et les poignets vers le haut 5. (optionnel/variable) Marquez une pause en haut 6. Revenez lentement à la position de départ","tips":["Tendez le bras vers le bas, puis levez légèrement l'avant-bras","Mettez le poignet en supination (paume vers le haut)","Réglez la hauteur de la poulie pour que la poignée se trouve dans votre main en supination","Réalisez le mouvement en enroulant les paumes et les poignets vers le haut","(optionnel/variable) Marquez une pause en haut"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1736","wgerId":1736,"name":"Soulevé de terre sur une jambe avec haltère","muscle":"jambes","equipment":"elastiques","desc":"Position de départ : Tenez-vous debout, les genoux légèrement fléchis, en tenant un haltère dans une main ou dans les deux. Reportez votre poids sur votre jambe d'appui (par exemple la jambe droite) et décollez légèrement du sol le pied de l'autre jambe. La charnière : En gardant le dos plat et la sangle abdominale gainée, basculez au niveau des hanches en poussant vos fessiers vers l'arrière. À mesure que votre buste descend, tendez la jambe libre droit derrière vous pour l'équilibre, en gardant les hanches bien parallèles au sol. Le ou les haltères doivent descendre vers le sol le long de votre jambe d'appui. Amplitude de mouvement : Contin","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1740","wgerId":1740,"name":"Single Leg Glute Bridge","muscle":"fessiers","equipment":"none","desc":"Un pont fessier, où vous n'utilisez qu'une jambe à la fois.","tips":["Un pont fessier, où vous n'utilisez qu'une jambe à la fois."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1748","wgerId":1748,"name":"Abduction des hanches à la machine","muscle":"fessiers","equipment":"none","desc":"Technique et exécution Position de départ Positionnement assis : Asseyez-vous dans la machine, le dos contre l'appui Placement des jambes : Faces internes des cuisses contre les points de résistance rembourrés de la machine Réglage de la machine : Réglez la position du siège pour aligner votre articulation de hanche avec le point de pivot de la machine Technique du mouvement Commencez jambes serrées ou légèrement appuyées contre les coussins internes Poussez lentement les jambes vers l'extérieur en les écartant Écartez-les jusqu'à atteindre l'amplitude latérale maximale confortable Marquez une brève pause au point le plus écarté du mouvement ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1748/923a3ff7-c269-49bd-9f03-697151a40f06.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1775","wgerId":1775,"name":"Oiseau arrière à la machine pec deck","muscle":"jambes","equipment":"none","desc":"Oiseau pour les deltoïdes postérieurs assis à la machine pec deck (face à la machine, en tendant les bras vers l'arrière ; les mains doivent être à la hauteur des épaules).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1777","wgerId":1777,"name":"Deficit Push ups","muscle":"pectoraux","equipment":"none","desc":"Poussez sur des blocs ou des poignées, de sorte que vous puissiez plonger plus bas que les mains dans le décent.","tips":["Poussez sur des blocs ou des poignées, de sorte que vous puissiez plonger plus bas que les mains dans le décent."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1843","wgerId":1843,"name":"Étirement du papillon","muscle":"jambes","equipment":"none","desc":"1. Asseyez-vous en position de prière, les plantes des pieds doucement collées l'une contre l'autre. 2. À l'aide de vos mains, tirez lentement vos pieds vers l'intérieur, en direction de l'aine. Maintenez aussi longtemps que nécessaire.","tips":["Asseyez-vous en position de prière, les plantes des pieds doucement collées l'une contre l'autre","À l'aide de vos mains, tirez lentement vos pieds vers l'intérieur, en direction de l'aine"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1844","wgerId":1844,"name":"Étirement de la grenouille","muscle":"fessiers","equipment":"none","desc":"1. Mettez-vous à quatre pattes. 2. Écartez les genoux vers l'extérieur et descendez sur les coudes. 3. Sans bouger les coudes ni les genoux, commencez à vous balancer d'avant en arrière, en cherchant à rapprocher vos fessiers de vos pieds.","tips":["Mettez-vous à quatre pattes","Écartez les genoux vers l'extérieur et descendez sur les coudes"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1779","wgerId":1779,"name":"Rotation au landmine","muscle":"abdos","equipment":"barre","desc":"Commencez avec la barre du landmine pointée droit vers le haut en la poussant au-dessus de vous à l'aide de vos épaules. Puis, depuis cette position, amenez-la sur le côté pour solliciter vos abdominaux, et revenez à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1833","wgerId":1833,"name":"Curl des ischio-jambiers avec sliders au sol","muscle":"jambes","equipment":"none","desc":"Allongez-vous sur le dos, les talons posés sur des sliders ou des serviettes. Soulevez les hanches en position de pont, puis faites glisser les talons vers les fessiers tout en gardant les hanches relevées. Revenez lentement à la position de départ en maintenant le pont de hanches.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1827","wgerId":1827,"name":"Pression abdominale à deux jambes","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur le dos, les genoux et les hanches fléchis à 90 degrés (position de la table). Placez vos mains sur vos cuisses, juste au-dessus des genoux. Poussez vos mains contre vos genoux aussi fort que possible tout en utilisant vos abdominaux pour tirer vos genoux vers vos mains. Maintenez pendant 10 secondes à effort maximal. Vos abdominaux devraient trembler.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1776","wgerId":1776,"name":"Suitcase Carry","muscle":"abdos","equipment":"elastiques","desc":"Marchez en avant et en arrière en tenant l'haltère d'un côté sans vous pencher pour contrer le poids.","tips":["Marchez en avant et en arrière en tenant l'haltère d'un côté sans vous pencher pour contrer le poids."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1778","wgerId":1778,"name":"Supino inclinado","muscle":"pectoraux","equipment":"none","desc":"Inclinado 90 graus e movimentos leves e precisos","tips":["Inclinado 90 graus e movimentos leves e precisos"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1861","wgerId":1861,"name":"Side stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1861/0ffe4e99-71ad-47fb-b98c-1f243faa0499.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1867","wgerId":1867,"name":"Hip Flexor Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1867/767631e5-10d2-46b8-b03f-cc298f96963b.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1868","wgerId":1868,"name":"Lunge with Twist Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1868/446e7065-215d-4a91-9da7-9416101442bb.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1869","wgerId":1869,"name":"Lying Figure Four Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1869/c49187bd-9f90-4a7a-b25e-1d50e857a104.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1872","wgerId":1872,"name":"Pigeon Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1872/df982df1-512a-4eb9-acd9-68cc1c265df6.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1873","wgerId":1873,"name":"Quad Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1873/c0ed299b-6d87-4d90-885d-bb3b5d85f1eb.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1874","wgerId":1874,"name":"Runners Lunge Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1874/66fca8a5-41e8-42d1-8776-5e46a4902650.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1875","wgerId":1875,"name":"Standing IT Band Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1875/e1128391-4b73-43a9-ab27-657d8bb43083.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1876","wgerId":1876,"name":"Supported Calf Stretch","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1876/ca7b3fe7-5908-4ec2-9d85-7fa1b80bb105.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1870","wgerId":1870,"name":"Lying Hamstring Stretch with Band","muscle":"jambes","equipment":"elastiques","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1870/7465bbcf-3b86-42a6-8d2f-12a3d1f60a15.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1795","wgerId":1795,"name":"Tirage croisé unilatéral à la poulie","muscle":"dos","equipment":"none","desc":"Sur une station à poulies, placez la poulie en position haute et, le bras tendu, tirez le câble en travers de votre corps, du haut vers le bas. Concentrez-vous sur la tension dans l'arrière de l'épaule.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1832","wgerId":1832,"name":"Maintien en appui aux anneaux","muscle":"jambes","equipment":"none","desc":"Maintenez-vous en position d'appui sur des anneaux de gymnastique, les bras tendus le long du corps. Veillez à garder les anneaux légèrement tournés vers l'extérieur et à conserver une position de corps creux. Il s'agit d'un maintien isométrique pour les pectoraux, les épaules et les triceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1807","wgerId":1807,"name":"Élévation latérale à la poulie derrière le dos","muscle":"epaules","equipment":"none","desc":"Les élévations latérales sont depuis longtemps un incontournable pour développer des deltoïdes bien arrondis, et les pratiquants utilisent tout ce qui est possible, des haltères et des élastiques aux machines et aux variantes à un bras, pour les faire grossir.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1882","wgerId":1882,"name":"Élévation latérale à la poulie haute","muscle":"epaules","equipment":"none","desc":"Tenez-vous à côté d'une machine à poulie réglée à hauteur de taille. Saisissez la poignée du côté opposé avec la main la plus éloignée de la poulie, en gardant la paume tournée vers l'intérieur. Gardez la sangle abdominale engagée, la poitrine ouverte et les épaules détendues. Maintenez une légère flexion du coude pendant toute la montée. Levez le bras sur le côté jusqu'à ce que votre coude atteigne la hauteur de l'épaule, en gardant le poignet aligné avec le coude. Marquez une brève pause en haut, puis abaissez lentement la poignée le long de votre corps de façon contrôlée. Répétez pour le nombre de répétitions souhaité.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1803","wgerId":1803,"name":"Squat à la barre trap","muscle":"jambes","equipment":"none","desc":"Une combinaison des principes du squat et du soulevé de terre à l'aide d'une barre hexagonale (trap bar), qui réduit la contrainte sur le bas du dos en centrant mieux la charge.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1804","wgerId":1804,"name":"Bascules en dorsiflexion de la cheville","muscle":"jambes","equipment":"none","desc":"Avancez le genou vers l'avant en gardant le talon au sol. Maintenez la position quelques secondes et revenez à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1808","wgerId":1808,"name":"Maintien aux barres parallèles","muscle":"epaules","equipment":"none","desc":"1. Placez-vous entre une paire de barres parallèles. 2. Posez vos mains sur les barres, les phalanges vers l'extérieur. 3. Poussez sur vos mains pour vous soulever du sol. 4. Maintenez-vous dans cette position, les bras tendus, pendant la durée requise.","tips":["Placez-vous entre une paire de barres parallèles","Posez vos mains sur les barres, les phalanges vers l'extérieur","Poussez sur vos mains pour vous soulever du sol","Maintenez-vous dans cette position, les bras tendus, pendant la durée requise"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1809","wgerId":1809,"name":"Hyperextension inversée","muscle":"jambes","equipment":"barre","desc":"Allongez-vous à plat ventre sur un banc, les jambes pendant dans le vide au-delà du bord. 1. Fléchissez les hanches pour que vos cuisses soient à la verticale, en fléchissant les genoux en même temps de manière à garder les tibias à l'horizontale. 2. Tendez les jambes jusqu'à ce qu'elles soient droites, les orteils pointant vers l'arrière à l'horizontale. 3. Revenez à la position initiale, et répétez.","tips":["Tendez les jambes jusqu'à ce qu'elles soient droites, les orteils pointant vers l'arrière à l'horizontale","Revenez à la position initiale, et répétez"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1810","wgerId":1810,"name":"Sphinx","muscle":"abdos","equipment":"none","desc":"Allongez-vous à plat ventre, les jambes tendues et le dessus des pieds posé au sol. Amenez vos avant-bras sous vos épaules, les coudes juste en dessous. Puis poussez vos mains dans le sol pour soulever la poitrine. Rapprochez vos omoplates, ouvrez les clavicules et dirigez votre regard vers l'avant, tout en gardant le bas du dos détendu.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1822","wgerId":1822,"name":"Le livre ouvert","muscle":"jambes","equipment":"none","desc":"**Exercice de base** * **Objectif :** améliore la mobilité thoracique et la segmentation de la colonne tout en ouvrant les épaules et la poitrine. * **Position :** à genoux sur le sol, le côté droit face à un mur. Les hanches sont parallèles et stables, le genou droit au sol et le pied gauche en avant. Allongez votre colonne et alignez confortablement votre tête. Commencez avec les bras détendus et ouverts devant votre poitrine, les paumes se faisant face et les mains écartées. * **Inspirez** pour amorcer le mouvement, en laissant votre bras gauche — celui qui est le plus éloigné du mur — s'ouvrir vers l'extérieur et l'arrière. Initiez la rot","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1824","wgerId":1824,"name":"Tate press avec haltères","muscle":"bras","equipment":"barre","desc":"1. **Mise en place** : Allongez-vous à plat avec un haltère dans chaque main. Tendez les bras droit au-dessus de votre poitrine, comme en position haute d'un développé couché avec haltères 2. **Position de départ** : Positionnez les haltères de manière qu'ils se touchent ou soient très proches l'un de l'autre, en prise pronation (paumes vers vos pieds et pouces se faisant face) 3. **Descente** : Sans bouger la partie supérieure des bras ni les épaules, fléchissez les coudes en les écartant vers l'extérieur. Abaissez les extrémités internes des haltères vers le centre de votre poitrine 4. **Contact et pause** : Touchez doucement votre poitrine","tips":["**Mise en place** : Allongez-vous à plat avec un haltère dans chaque main","**Contact et pause** : Touchez doucement votre poitrine avec les haltères","**Poussée** : Tendez les coudes avec force pour ramener les haltères à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1825","wgerId":1825,"name":"Élévation des deltoïdes postérieurs avec appui sur la poitrine","muscle":"epaules","equipment":"barre","desc":"« Le Y »Position : Réglez un banc incliné à 30-45 degrés. Allongez-vous à plat ventre, la poitrine en appui, en gardant la tête neutre ou le regard légèrement vers le bas pour éviter de forcer sur la nuque.Prise : Tenez des haltères légers en prise neutre ou pouces vers le haut (le pouce pointant vers le plafond).Mouvement : Les coudes tendus ou légèrement fléchis, levez les haltères vers le haut et vers l'extérieur en formant un « Y ». Concentrez-vous sur le mouvement des épaules et des omoplates plutôt que sur le simple fait de lever les bras.Position haute : Rapprochez les omoplates et étirez-vous bien haut, en veillant à ce que les bras s","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1826","wgerId":1826,"name":"Écarté à l'élastique avec rotation externe","muscle":"epaules","equipment":"elastiques","desc":"Tenez-vous bien droit, les pieds écartés de la largeur des épaules, la poitrine sortie et les épaules en arrière. Tenez l'élastique des deux mains, les paumes vers le haut ou se faisant face selon le type d'élastique. Fléchissez les coudes à un angle de 90 degrés et collez la partie supérieure des bras contre vos côtés. L'élastique doit présenter une certaine tension en position de départ, vos mains plus rapprochées devant votre ventre. Rotation vers l'extérieur : Tout en gardant les coudes serrés contre vos côtés, éloignez lentement vos mains l'une de l'autre en étirant l'élastique. Contraction : Rapprochez vos omoplates et abaissez-les pend","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1828","wgerId":1828,"name":"Rentrée du ventre","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur le dos, les genoux fléchis. Rentrez doucement votre nombril vers votre colonne, sans bouger vos hanches ni retenir votre respiration.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1829","wgerId":1829,"name":"Squat-développé au landmine","muscle":"epaules","equipment":"barre","desc":"Position de la barre : Ancrez une extrémité d'une barre dans un support landmine ou un coin sûr. Posture : Tenez-vous face à la barre, les pieds un peu plus écartés que la largeur des épaules. Orientez les orteils vers l'extérieur de 10 à 35 degrés pour permettre un meilleur mouvement du bassin et plus de profondeur. Prise : Enveloppez l'extrémité libre de la barre des deux mains (doigts entrelacés ou superposés) et tenez-la au milieu de la poitrine, juste sous la clavicule. Descente : Gainez la sangle abdominale et asseyez-vous vers l'arrière en squat, en gardant la poitrine haute et le poids sur les talons. Profondeur : Descendez jusqu'à ce","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1830","wgerId":1830,"name":"Fente arrière à la barre","muscle":"jambes","equipment":"barre","desc":"Étape 1 : Tenez-vous debout, les pieds écartés de la largeur des hanches, en maintenant une barre sur le haut du dos. Étape 2 : Gardez le dos droit, la poitrine ouverte et la sangle abdominale engagée. Étape 3 : Faites un pas en arrière avec une jambe et abaissez votre corps en pliant les deux genoux. Assurez-vous que le genou arrière touche presque le sol. Étape 4 : Poussez sur le pied arrière pour revenir à la position de départ. Étape 5 : Répétez le mouvement avec l'autre jambe. Continuez à alterner les jambes pour le nombre de répétitions souhaité.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1831","wgerId":1831,"name":"Développé décliné sur machine Hammer Strength","muscle":"pectoraux","equipment":"none","desc":"1. Asseyez-vous bien droit sur une machine Hammer Strength de développé décliné en rapprochant vos omoplates et en posant fermement les talons au sol, sous les genoux. 2. Le dossier doit rester en contact avec votre tête, vos épaules et vos fessiers à tout moment. 3. Saisissez les poignées en prise pronation, juste un peu plus large que la largeur des épaules, légèrement sous la poitrine. 4. En gardant la sangle abdominale gainée par une respiration ventrale et une contraction des abdominaux, poussez à travers les paumes pour tendre les coudes tout en les maintenant à un angle de 45 degrés par rapport au torse. 5. Une fois les bras complèteme","tips":["Le dossier doit rester en contact avec votre tête, vos épaules et vos fessiers à tout moment","Une fois les bras complètement tendus, revenez à la position de départ"],"image":"https://wger.de/media/exercise-images/1831/2d9d509f-707b-4132-961e-91a2459ca198.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1834","wgerId":1834,"name":"Élévation trapèze inférieur (Trap-3)","muscle":"dos","equipment":"none","desc":"1. Penchez-vous vers l'avant et fléchissez légèrement les genoux. Abaissez et rétractez l'épaule que vous allez utiliser. Posez l'autre main sur votre genou. 2. Levez la main d'environ 15 degrés au-dessus de la tête, en maintenant la position de votre épaule.","tips":["Penchez-vous vers l'avant et fléchissez légèrement les genoux","Levez la main d'environ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1835","wgerId":1835,"name":"Étirement en rotation externe","muscle":"epaules","equipment":"barre","desc":"1. Asseyez-vous avec les pieds pressés l'un contre l'autre et un genou relevé complètement sur le côté du corps. 2. Placez votre coude sur le genou relevé, pliez-le à 90 degrés et pointez la main droit devant vous, en tenant votre barre ou votre haltère. 3. Gardez l'épaule abaissée et rétractée, puis levez la main jusqu'à ce que l'avant-bras soit vertical, comme si vous alliez saluer quelqu'un à la manière d'un robot. 4. Abaissez la main jusqu'à la position initiale et répétez.","tips":["Asseyez-vous avec les pieds pressés l'un contre l'autre et un genou relevé complètement sur le côté du corps","Placez votre coude sur le genou relevé, pliez-le à","Abaissez la main jusqu'à la position initiale et répétez"],"image":"https://wger.de/media/exercise-images/1835/ca4a0b7e-9fdd-4173-843a-f0392824abe1.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1838","wgerId":1838,"name":"Exercices d'épaules à l'élastique","muscle":"epaules","equipment":"elastiques","desc":"1. Fixez un élastique à un support solide derrière vous. Tenez-vous à distance en le maintenant dans la main de façon à ce qu'il soit tendu. 2. Consultez la vidéo YouTube jointe : https://www.youtube.com/watch?v=zdwEWchSjrI .","tips":["Fixez un élastique à un support solide derrière vous","Consultez la vidéo YouTube jointe : https://www"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1839","wgerId":1839,"name":"Solo Hip Flexor Stretch","muscle":"jambes","equipment":"none","desc":"Voir cette vidéo instructive : https://www.youtube.com/watch?v=qHwyBHS6MQs .","tips":["Voir cette vidéo instructive : https://www.youtube.com/watch?v=qHwyBHS6MQs ."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1840","wgerId":1840,"name":"Bent-Leg Hamstring Stretch","muscle":"jambes","equipment":"none","desc":"Voir cette vidéo d'instructions de Stretch Therapy : https://www.youtube.com/watch?v=CrF2iMnn09w .","tips":["Voir cette vidéo d'instructions de Stretch Therapy : https://www.youtube.com/watch?v=CrF2iMnn09w ."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1841","wgerId":1841,"name":"Étirement des épaules en extension assis","muscle":"dos","equipment":"none","desc":"1. Asseyez-vous avec les mains derrière vous, écartées de la largeur des épaules. 2. Verrouillez les coudes. 3. Avancez vos pieds et vos hanches vers l'avant, en abaissant vos épaules vers le sol. 4. Allez aussi loin que possible pour obtenir un bon étirement. Consultez la vidéo : https://www.youtube.com/watch?v=ihUAbG0e8zw","tips":["Asseyez-vous avec les mains derrière vous, écartées de la largeur des épaules","Verrouillez les coudes","Avancez vos pieds et vos hanches vers l'avant, en abaissant vos épaules vers le sol","Allez aussi loin que possible pour obtenir un bon étirement"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1846","wgerId":1846,"name":"Posture du cavalier (grand écart latéral)","muscle":"fessiers","equipment":"none","desc":"1. Placez-vous comme pour un squat, les pieds largement écartés et les orteils légèrement tournés vers l'extérieur. 2. Descendez doucement dans un squat profond et large : vos hanches doivent passer sous le niveau de vos genoux. 3. Maintenez la position pendant 3 à 5 secondes. 4. Remontez de façon contrôlée et répétez autant de fois que nécessaire.","tips":["Placez-vous comme pour un squat, les pieds largement écartés et les orteils légèrement tournés vers l'extérieur","Descendez doucement dans un squat profond et large : vos hanches doivent passer sous le niveau de vos genoux","Maintenez la position pendant","Remontez de façon contrôlée et répétez autant de fois que nécessaire"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1854","wgerId":1854,"name":"Calves foam roller","muscle":"jambes","equipment":"none","desc":"Déplacez lentement vos mollets sur le rouleau en mousse","tips":["Déplacez lentement vos mollets sur le rouleau en mousse"],"image":"https://wger.de/media/exercise-images/1854/ccd3c18e-c864-426f-8176-15dce14305e3.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1855","wgerId":1855,"name":"Hamstring Foam roller","muscle":"jambes","equipment":"none","desc":"Déplacez lentement vos ischio-jambiers sur le rouleau en mousse","tips":["Déplacez lentement vos ischio-jambiers sur le rouleau en mousse"],"image":"https://wger.de/media/exercise-images/1855/a6597ed8-1613-4458-ba56-4b63bc946a35.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1856","wgerId":1856,"name":"Foam Roller Anterior tibialis","muscle":"jambes","equipment":"none","desc":"Utilisez le rouleau en mousse lentement dans l'antériorité tibiale. C'est l'anglais, s'il vous plaît","tips":["Utilisez le rouleau en mousse lentement dans l'antériorité tibiale. C'est l'anglais, s'il vous plaît"],"image":"https://wger.de/media/exercise-images/1856/19c31c63-4968-4887-b8e6-4127be27fdde.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1857","wgerId":1857,"name":"Foam Roller Iliotibial band","muscle":"jambes","equipment":"none","desc":"Glissez sur le rouleau en mousse sur votre bande iliotibiale. Est anglais terrible Checker","tips":["Glissez sur le rouleau en mousse sur votre bande iliotibiale. Est anglais terrible Checker"],"image":"https://wger.de/media/exercise-images/1857/92291128-cc7e-4f70-9663-80840c516fc9.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1858","wgerId":1858,"name":"Foam Roller quadriceps","muscle":"jambes","equipment":"none","desc":"Faites glisser le rouleau de mousse sur vos quadriceps. Est anglais, s'il vous plaît","tips":["Faites glisser le rouleau de mousse sur vos quadriceps. Est anglais, s'il vous plaît"],"image":"https://wger.de/media/exercise-images/1858/058b6fdb-8093-4b6d-a504-cbf869f3e3d3.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1859","wgerId":1859,"name":"Foam Roller Gluteus","muscle":"fessiers","equipment":"none","desc":"Glissez sur le rouleau de mousse sur votre fessier. Est anglais s'il vous plaît","tips":["Glissez sur le rouleau de mousse sur votre fessier. Est anglais s'il vous plaît"],"image":"https://wger.de/media/exercise-images/1859/2465d5eb-c249-454d-93eb-58aa13bdc080.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1860","wgerId":1860,"name":"Foam Roller Adductors","muscle":"jambes","equipment":"none","desc":"Faites glisser le rouleau de mousse sur vos adducteurs. Est-ce que l'anglais s'il vous plaît","tips":["Faites glisser le rouleau de mousse sur vos adducteurs. Est-ce que l'anglais s'il vous plaît"],"image":"https://wger.de/media/exercise-images/1860/f0410e66-28d5-455f-90f3-d078e0988460.avif.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1862","wgerId":1862,"name":"Hip Circles","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1862/93d993f8-1d8c-4e21-99c6-08b2fe424a17.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1863","wgerId":1863,"name":"Hip Crossover","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1863/5f29959d-0fd1-46d2-98b7-0c2cb5d9ee13.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1864","wgerId":1864,"name":"Ankle Roll","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1864/5970cdd8-0123-4eba-a921-2157fb6adacf.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1865","wgerId":1865,"name":"Banded Ankle Mobility","muscle":"jambes","equipment":"none","desc":"Visionnez la vidéo pour annuler l'exercice","tips":["Visionnez la vidéo pour annuler l'exercice"],"image":"https://wger.de/media/exercise-images/1865/c2c9848e-5094-4ed9-bd81-0831b6551483.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1877","wgerId":1877,"name":"Rétraction scapulaire à l'élastique","muscle":"epaules","equipment":"elastiques","desc":"Fixez une extrémité de l'élastique à un mur, un montant ou un autre support, à hauteur d'épaule. Passez le bras dans la boucle, au niveau du triceps. Reculez jusqu'à ce que l'élastique soit tendu. Tirez le coude et l'épaule vers l'arrière contre la résistance de l'élastique.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1879","wgerId":1879,"name":"Élévation en Y aux haltères sur banc incliné","muscle":"epaules","equipment":"elastiques","desc":"1. Réglez un banc incliné à un angle de 45 degrés et asseyez-vous face au banc, la poitrine contre le dossier, un haltère dans chaque main, les paumes se faisant face. 2. Posez fermement les pieds au sol pour plus de stabilité et laissez vos bras pendre naturellement avec une légère flexion des coudes. 3. Engagez la sangle abdominale et gardez le dos droit tout au long du mouvement. 4. Levez les bras vers l'avant et vers l'extérieur pour former un Y, en gardant le mouvement contrôlé et les coudes légèrement fléchis. 5. Montez jusqu'à ce que vos bras soient à peu près parallèles au sol et alignés avec vos oreilles. 6. Marquez une brève pause e","tips":["Réglez un banc incliné à un angle de","Engagez la sangle abdominale et gardez le dos droit tout au long du mouvement","Montez jusqu'à ce que vos bras soient à peu près parallèles au sol et alignés avec vos oreilles","Répétez pour le nombre de répétitions souhaité, en conservant une bonne technique tout du long"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1881","wgerId":1881,"name":"Extension des poignets aux haltères","muscle":"jambes","equipment":"elastiques","desc":"Saisissez deux haltères en prise pronation et posez vos avant-bras sur vos genoux. Laissez vos poignets fléchir complètement, puis réalisez l'extension des poignets.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1823","wgerId":1823,"name":"Coquille (clamshell)","muscle":"fessiers","equipment":"none","desc":"**Position** Planche latérale avec le coude et l'avant-bras au sol et les jambes légèrement fléchies. **Exécution** Levez le genou supérieur tout en gardant les pieds rapprochés, comme une « coquille qui s'ouvre », puis revenez lentement à la position de départ. Gardez la sangle abdominale stable et les hanches alignées.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1842","wgerId":1842,"name":"Coquille à l'élastique","muscle":"fessiers","equipment":"elastiques","desc":"**Position** Planche latérale avec le coude et l'avant-bras au sol et les jambes légèrement fléchies. Tendez un élastique replié en deux entre vos cuisses, juste au-dessus du genou. **Exécution** Levez le genou supérieur tout en gardant les pieds rapprochés, comme une « coquille qui s'ouvre », puis revenez lentement à la position de départ. Gardez la sangle abdominale stable et les hanches alignées.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1397","wgerId":1397,"name":"Good morning jambes écartées debout","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds écartés au-delà de la largeur des épaules et les orteils légèrement tournés vers l'extérieur. Placez vos mains derrière la tête. Effectuez une bascule à partir des hanches et abaissez le haut du corps vers le sol, en gardant le dos droit et la poitrine ouverte.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1845","wgerId":1845,"name":"Good morning jambes écartées assis","muscle":"fessiers","equipment":"none","desc":"1. Asseyez-vous avec les jambes complètement tendues (genoux verrouillés), largement écartées en position d'écart facial. 2. Placez vos mains derrière la nuque. 3. Basculez le torse et la tête vers le sol.","tips":["Asseyez-vous avec les jambes complètement tendues (genoux verrouillés), largement écartées en position d'écart facial","Placez vos mains derrière la nuque","Basculez le torse et la tête vers le sol"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1884","wgerId":1884,"name":"Étirement en rotation interne en position shinbox","muscle":"fessiers","equipment":"none","desc":"* **Position de départ :** Asseyez-vous au sol, les hanches et les genoux fléchis à un angle de 90 degrés. * **Placement des jambes :** Placez une jambe devant vous (rotation externe) et l'autre jambe sur le côté ou derrière vous (rotation interne). Les tibias et les genoux doivent rester à plat sur le sol. * **Le mouvement :** En gardant les hanches bien parallèles, basculez le torse vers l'avant ou inclinez-le latéralement (d'un côté à l'autre) vers la jambe avant pour approfondir l'étirement. * **Zones ciblées :** Étire les fessiers et le piriforme (jambe avant) ainsi que les fléchisseurs de la hanche et les quadriceps (jambe arrière). Sol","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1885","wgerId":1885,"name":"Exercice YTWL","muscle":"epaules","equipment":"elastiques","desc":"* **But :** Améliore la stabilité des épaules, la posture et le contrôle scapulaire (des omoplates). Souvent utilisé en kinésithérapie et lors des échauffements. * **Position de départ :** Tenez-vous debout, les pieds écartés de la largeur des épaules. Basculez vers l'avant à partir des hanches (comme pour un soulevé de terre) en gardant le dos plat, ou allongez-vous à plat ventre sur un banc incliné. Gardez les pouces pointés vers le haut tout au long de l'exercice. * **Y (bras levés) :** Tendez les deux bras droit vers l'avant et vers le haut, à un angle de 135 degrés par rapport au corps, pour former un « Y ». Resserrez vos omoplates en ha","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1886","wgerId":1886,"name":"Abduction de hanche en décubitus dorsal","muscle":"fessiers","equipment":"elastiques","desc":"* **Position de départ :** Allongez-vous sur le dos (décubitus dorsal) sur un tapis, les jambes tendues et détendues. Les bras peuvent être placés le long du corps ou écartés sur les côtés pour plus de stabilité. * **Le mouvement :** Soulevez légèrement une jambe du sol (en la gardant tendue ou avec une légère flexion). Déplacez-la latéralement vers l'extérieur, en l'éloignant de l'autre jambe, comme si vous enjambiez un petit obstacle. * **Amplitude de mouvement :** Déplacez la jambe aussi loin que possible sans soulever le bassin ni faire tourner le torse, en ressentant un étirement à l'intérieur de la cuisse et de la hanche. * **Retour :**","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1939","wgerId":1939,"name":"Neck CARs","muscle":"jambes","equipment":"none","desc":"Rotations articulaires contrôlées. 3 cercles complets lents dans chaque sens. Mobilité cervicale.","tips":["Rotations articulaires contrôlées. 3 cercles complets lents dans chaque sens. Mobilité cervicale."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1947","wgerId":1947,"name":"dumbbell snatch","muscle":"jambes","equipment":"elastiques","desc":"Pour l'exécuter correctement, il faut suivre ces étapes clés : Mise en place : Placez l'haltère entre vos pieds, les épaules au-dessus des hanches, la poitrine haute et le dos plat. Le tirage : Étendez violemment les hanches, les genoux et les chevilles (extension tri-joint) pour projeter l'haltère vers le haut, en gardant le coude haut et l'haltère près du corps. La réception : Fléchissez rapidement les hanches et les genoux pour passer sous l'haltère et le recevoir au-dessus de la tête avec le bras verrouillé, en atterrissant en position de demi-squat. Les erreurs courantes incluent l'utilisation excessive des bras pour soulever le poids au","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1947/4201a9c0-f9e4-48ca-80f1-b46c7ffe5640.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1948","wgerId":1948,"name":"Squat sur boîte à une jambe","muscle":"jambes","equipment":"none","desc":"Cet exercice nécessite une boîte solide ou une chaise. Tenez-vous simplement à environ 15 cm devant elle et tenez-vous en équilibre sur une jambe. À partir de là, commencez à descendre en squat par un mouvement fluide et contrôlé, tout en gardant l'autre jambe tendue devant vous pour l'équilibre. Asseyez-vous lentement sur la boîte, marquez une pause d'une seconde, puis remontez en poussant avec la jambe active, sans jamais laisser l'autre jambe toucher le sol.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1893","wgerId":1893,"name":"Développé militaire à la barre","muscle":"epaules","equipment":"barre","desc":"- **Mise en place :** Tenez-vous debout, les pieds joints, et saisissez la barre un peu plus large que la largeur des épaules. - **Position :** Posez la barre sur le haut de la poitrine. - **Poussée :** Gainez la sangle abdominale et poussez la barre droit vers le haut jusqu'à ce que vos bras soient tendus. - **Fin :** Contrôlez la descente de la barre jusqu'à votre poitrine. - https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1893/7dbad19e-0616-41fd-9d7d-3e21649c0eea.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1949","wgerId":1949,"name":"Limber 11","muscle":"jambes","equipment":"none","desc":"Limber 11 Source : Joe DeFranco 1. Rouleau de massage sur le tractus iliotibial [tissus mous] - 10 à 15 passages 2. Rouleau de massage sur les adducteurs [tissus mous] - 10 à 15 passages 3. Automassage des fessiers (balle de massage) [tissus mous] - 30 s à 2 min 4. Iron cross genou fléchi [dynamique] - 5 à 10 répétitions de chaque côté 5. Roulades vers des V-sits [dynamique] - 10 répétitions 6. Étirement de la grenouille en balancement [dynamique] - 10 répétitions 7. Cercles de la bouche d'incendie [dynamique] - 10 vers l'avant / 10 vers l'arrière 8. Mountain climbers [dynamique] - 10 répétitions par jambe 9. Squats cosaques [dynamique] - 5 à","tips":["Rouleau de massage sur le tractus iliotibial [tissus mous] -","Rouleau de massage sur les adducteurs [tissus mous] -","Automassage des fessiers (balle de massage) [tissus mous] -","Iron cross genou fléchi [dynamique] -","Roulades vers des V-sits [dynamique] -"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1950","wgerId":1950,"name":"Foam Roll IT Band","muscle":"jambes","equipment":"none","desc":"Rouleau de mousse IT Band Partie de : Limber 11 Source : Joe DeFranco Prescription : 10-15 passes Type : soft_tissue","tips":["Rouleau de mousse IT Band Partie de : Limber 11 Source : Joe DeFranco Prescription : 10-15 passes Type : soft_tissue"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1953","wgerId":1953,"name":"Bent-knee Iron Cross","muscle":"jambes","equipment":"none","desc":"Croix de fer au genou plié Partie de : Limber 11 Source : Joe DeFranco Prescription : 5 à 10 répétitions de chaque côté Type : dynamique","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1956","wgerId":1956,"name":"Fire Hydrant Circles","muscle":"jambes","equipment":"none","desc":"Cercles de bouche d'incendie Partie de : Limber 11 Source : Joe DeFranco Prescription : 10 vers l'avant / 10 vers l'arrière Type : dynamique","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1901","wgerId":1901,"name":"Épaulé-développé (clean and press)","muscle":"epaules","equipment":"barre","desc":"* **Le premier tirage :** Soulevez la barre du sol jusqu'à hauteur des genoux en poussant avec les jambes, en gardant l'angle de votre dos constant. * **La position de « puissance » :** Lorsque la barre atteint le milieu des cuisses, haussez explosivement les épaules et étendez les hanches pour créer une impulsion verticale. * **Le passage rapide des coudes :** Pendant la phase de réception, faites pivoter rapidement vos coudes sous la barre pour créer une « tablette » sur vos deltoïdes antérieurs. * **La poussée verticale :** Poussez la barre en ligne droite ; votre tête doit se décaler légèrement vers l'avant une fois que la barre dépasse v","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1901/046f0f42-0ed5-48c5-a9ee-41de25e3b6a0.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1902","wgerId":1902,"name":"Pompes lestées","muscle":"pectoraux","equipment":"none","desc":"- **Mise en place :** Commencez en position de planche classique avec un disque de poids posé de façon stable sur le haut du dos. - **Alignement :** Maintenez une ligne droite de la tête aux talons, en engageant la sangle abdominale pour éviter que le dos ne s'affaisse. - **Exécution :** Abaissez votre corps jusqu'à ce que la poitrine touche presque le sol, en gardant les coudes à **quarante-cinq degrés**. - **Montée :** Poussez à travers les paumes pour revenir à la position de départ, en tendant complètement les bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1902/d0c3f170-543c-4be4-bc70-5c6dc606406c.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1904","wgerId":1904,"name":"Pec Deck","muscle":"pectoraux","equipment":"none","desc":"Exercice d'émolation pectorale - une amplitude de mouvement complète est préférable avec une contraction complète et un négatif lent","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1906","wgerId":1906,"name":"Pont fessier","muscle":"fessiers","equipment":"none","desc":"Mettez-vous en position de pont, tenez-vous en équilibre sur les talons et commencez à étendre les jambes de manière unilatérale. Gardez la hanche en extension autant que possible.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1907","wgerId":1907,"name":"Unilateral Lunges","muscle":"fessiers","equipment":"none","desc":"Pas d'arrêts pendant le mouvement, mains sur les hanches.","tips":["Pas d'arrêts pendant le mouvement, mains sur les hanches."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1908","wgerId":1908,"name":"Butterfly Superman","muscle":"dos","equipment":"none","desc":"Allongez-vous sur le ventre, entrelacez les doigts derrière la tête et commencez à lever la tête et levez les coudes aussi loin qu'ils vont.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1909","wgerId":1909,"name":"Roue avec les jambes","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur le dos et levez les jambes à la verticale, en gardant les genoux serrés l'un contre l'autre. Commencez à dessiner de petits cercles dans une direction avec vos deux genoux, sur une très faible amplitude de mouvement, en vous concentrant sur les abdominaux et en gardant le dos en contact avec le sol.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1910","wgerId":1910,"name":"Superman à genoux","muscle":"jambes","equipment":"none","desc":"- Poussez un pied vers l'arrière jusqu'à ce que la jambe soit complètement tendue, en veillant à garder le pied haut et poussé vers l'arrière comme s'il était tiré. - Tendez le bras vers l'avant en veillant à garder l'épaule bien haute. Exercice unilatéral et maintien statique.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1911","wgerId":1911,"name":"Planche du chat","muscle":"jambes","equipment":"none","desc":"Placez-vous à quatre pattes et décollez très légèrement les genoux du sol. Arrondissez le dos et poussez vers l'arrière à partir des épaules, de manière à ressembler à un chat qui se fait paraître plus grand.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1912","wgerId":1912,"name":"Rotation du tronc","muscle":"jambes","equipment":"none","desc":"Asseyez-vous en arrière, soulevez les pieds du sol en gardant les genoux fléchis, puis commencez à pivoter de gauche à droite en touchant le sol avec les mains à chaque mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1913","wgerId":1913,"name":"Unilateral Hip Thrust","muscle":"fessiers","equipment":"none","desc":"Étendez une jambe tout en vous couchant et commencez à soulever votre corps avec une jambe touchant le sol par le talon.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1914","wgerId":1914,"name":"Maintien isométrique aux barres parallèles","muscle":"pectoraux","equipment":"none","desc":"Le maintien isométrique aux barres parallèles est un exercice statique pour le haut du corps réalisé sur des barres de dips (barres parallèles). Au lieu de monter et descendre comme dans un dip traditionnel, vous maintenez une position fixe sous tension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1916","wgerId":1916,"name":"Tuck planche","muscle":"epaules","equipment":"none","desc":"Basic calisthenics progression for the full planche","tips":["Basic calisthenics progression for the full planche"],"image":"https://wger.de/media/exercise-images/1916/e7d97b4b-9fe4-4378-aea3-5a9d93b6eb8d.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-1959","wgerId":1959,"name":"Étirement du piriforme assis","muscle":"jambes","equipment":"none","desc":"Étirement du piriforme assis Fait partie de : Limber 11 Source : Joe DeFranco Prescription : 20 à 30 s de chaque côté Type : statique Comprend un maintien isométrique.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1925","wgerId":1925,"name":"Haussement d'épaules Silverback à la barre","muscle":"dos","equipment":"barre","desc":"1. Tenez-vous debout, les pieds écartés à la largeur des épaules, en tenant la barre à deux mains devant vous, un peu au-delà de la largeur des épaules. 2. Penchez-vous vers l'avant au niveau des hanches en fléchissant légèrement les genoux, tout en gardant le dos droit. 3. Engagez vos omoplates, comme si vous cherchiez à les rapprocher l'une de l'autre. 4. Relâchez le haussement d'épaules. Description tirée de MuscleWiki","tips":["Penchez-vous vers l'avant au niveau des hanches en fléchissant légèrement les genoux, tout en gardant le dos droit","Engagez vos omoplates, comme si vous cherchiez à les rapprocher l'une de l'autre","Relâchez le haussement d'épaules"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-723","wgerId":723,"name":"Tirage vertical en prise large","muscle":"dos","equipment":"none","desc":"1. **Position de départ :** * Les bras tendus au-dessus de la tête, en ressentant un étirement dans le grand dorsal. * Gardez les épaules basses (ne haussez pas les épaules vers le haut). 2. **Phase de tirage (concentrique) :** * Tirez la barre vers le haut de la poitrine ou la zone des clavicules en poussant les coudes vers le bas et l'arrière. * Gardez la poitrine relevée et rapprochez vos omoplates en bas du mouvement.","tips":["**Position de départ :** * Les bras tendus au-dessus de la tête, en ressentant un étirement dans le grand dorsal"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1927","wgerId":1927,"name":"Tirage vertical en prise inversée","muscle":"dos","equipment":"none","desc":"Le **tirage vertical en prise inversée** (plus connu sous le nom de **tirage vertical en supination**) est une variante de l'exercice classique qui utilise une prise en supination, mains écartées à la largeur des épaules. Cette position met davantage l'accent sur le **bas du grand dorsal** et sollicite davantage les **biceps**, permettant souvent une plus grande amplitude de mouvement et une contraction plus profonde en bas du mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1929","wgerId":1929,"name":"Traction assistée","muscle":"dos","equipment":"elastiques","desc":"La **traction assistée** est un exercice de tirage vertical polyarticulaire réalisé sur une machine avec un contrepoids ou à l'aide d'élastiques. Elle reproduit la mécanique d'une traction classique mais réduit le poids total à soulever, ce qui en fait un excellent outil pour développer une force fonctionnelle et perfectionner votre technique.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1900","wgerId":1900,"name":"Extensions triceps à la corde","muscle":"bras","equipment":"none","desc":"- **Mise en place :** Tenez-vous face à la poulie, les pieds écartés de la largeur des épaules, avec une légère inclinaison vers l'avant. - **Prise :** Tenez la corde, les paumes se faisant face et les coudes bien serrés contre les côtes. - **Exécution :** Poussez la corde vers le bas jusqu'à ce que les bras soient complètement tendus, en écartant les extrémités l'une de l'autre en bas du mouvement. - **Contrôle :** Gardez le haut des bras immobile et revenez à la position de départ par un mouvement lent et contrôlé.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1900/a8243245-8f8f-4e2b-93ca-694d416cb11d.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1931","wgerId":1931,"name":"Curl avec haltères","muscle":"bras","equipment":"elastiques","desc":"Le **curl avec haltères** est un exercice d'isolation classique pour les bras. Contrairement au curl marteau, il implique une rotation des poignets (supination) au moment de soulever les charges, ce qui permet une contraction complète des biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1905","wgerId":1905,"name":"Tirage en arrière (pullback)","muscle":"bras","equipment":"none","desc":"Réglez la charge et la prise des câbles dans la cage. Reculez de quelques pas, penchez-vous vers l'avant, puis tirez et étendez le dos en même temps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1933","wgerId":1933,"name":"Crunch abdominal","muscle":"abdos","equipment":"none","desc":"Le **crunch abdominal** est un exercice d'isolation classique pour la sangle abdominale, réalisé au sol ou sur un tapis. Contrairement au redressement assis complet, il implique une amplitude de mouvement plus réduite où vous ne soulevez que les épaules et le haut du dos du sol, en gardant le bas du dos fermement plaqué contre le sol.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1915","wgerId":1915,"name":"Abduction de hanche à quatre pattes","muscle":"jambes","equipment":"elastiques","desc":"Répartissez le poids de votre corps de façon égale sur les genoux et les bras. Gardez le tronc stable, les abdominaux contractés et la colonne lombaire droite, sans tordre le dos (imaginez qu'un verre posé sur le bas de votre dos ne doit pas tomber). Soulevez une jambe vers l'extérieur sans la tordre. Veillez à conserver un angle droit au niveau des hanches et des genoux. Entraînez toujours les deux côtés du corps. Pour augmenter la résistance, vous pouvez utiliser un élastique.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-1935","wgerId":1935,"name":"Squat à la ceinture","muscle":"fessiers","equipment":"none","desc":"Squat à la ceinture : une variante du squat réalisée avec une ceinture fixée à une machine à charge ou à une plateforme, de sorte que le poids soit supporté au niveau des hanches plutôt que sur la colonne vertébrale. Il sollicite principalement les quadriceps et les fessiers, avec beaucoup moins de fatigue pour le bas du dos qu'un squat à la barre. Utilisez une amplitude de mouvement complète, gardez le tronc droit et poussez à travers le milieu du pied.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-20","wgerId":20,"name":"Arnold Shoulder Press","muscle":"epaules","equipment":"elastiques","desc":"Very common shoulder exercise. As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM","tips":["Very common shoulder exercise. As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-46","wgerId":46,"name":"Fentes debout à la barre","muscle":"jambes","equipment":"barre","desc":"Placez la barre sur l'arrière de vos épaules. Tenez-vous droit, puis faites un premier pas en avant. Le pas doit vous amener suffisamment loin pour que le genou de votre jambe d'appui puisse toucher le sol. Redressez-vous ensuite et répétez avec l'autre jambe. Pensez à conserver une bonne posture.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-43","wgerId":43,"name":"Barbell Hack Squats","muscle":"jambes","equipment":"barre","desc":"Perform leg squats with barbell behind your legs","tips":["Perform leg squats with barbell behind your legs"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-50","wgerId":50,"name":"Extension des triceps à la barre","muscle":"bras","equipment":"barre","desc":"Placez la barre au-dessus de la tête, en prise pronation serrée. Abaissez les avant-bras derrière les bras en gardant les coudes pointés vers le haut. Tendez les avant-bras au-dessus de la tête. Abaissez et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/50/695ced5c-9961-4076-add2-cb250d01089e.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-48","wgerId":48,"name":"Curl inversé des poignets à la barre","muscle":"jambes","equipment":"barre","desc":"Assis sur un banc, saisissez une barre, paumes tournées vers le bas et mains écartées à la largeur des épaules. Posez vos avant-bras sur vos cuisses et laissez vos poignets dépasser au-delà de vos genoux. Enroulez vos phalanges vers votre visage en soulevant la barre. Marquez une pause en position haute, puis ramenez lentement la barre à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-801","wgerId":801,"name":"Dumbbell Push-Up","muscle":"pectoraux","equipment":"elastiques","desc":"Normal Push-ups on Dumbbells, this brings a further range of movement","tips":["Normal Push-ups on Dumbbells, this brings a further range of movement"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-1918","wgerId":1918,"name":"Legend Chest Press","muscle":"pectoraux","equipment":"none","desc":"Plate-loaded chest press machine from Legend Fitness LeverEdge line.","tips":["Plate-loaded chest press machine from Legend Fitness LeverEdge line."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-1919","wgerId":1919,"name":"Extreme Pec Stretch","muscle":"jambes","equipment":"none","desc":"Deep loaded stretch for pectorals, typically performed at end of chest work.","tips":["Deep loaded stretch for pectorals, typically performed at end of chest work."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-1920","wgerId":1920,"name":"Extreme Shoulder Stretch","muscle":"jambes","equipment":"none","desc":"Deep loaded stretch for deltoids, performed after pressing movements.","tips":["Deep loaded stretch for deltoids, performed after pressing movements."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-1921","wgerId":1921,"name":"Extreme Lat Stretch","muscle":"jambes","equipment":"none","desc":"Deep loaded stretch for latissimus dorsi, performed after pulling movements.","tips":["Deep loaded stretch for latissimus dorsi, performed after pulling movements."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-1924","wgerId":1924,"name":"3008 Abdominal Crunch","muscle":"abdos","equipment":"none","desc":"This is especially for the gym80 device 3008 Abdominal Crunch.","tips":["This is especially for the gym80 device 3008 Abdominal Crunch."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"other"},{"id":"wger-1922","wgerId":1922,"name":"Écarté à la poulie assis (pectoraux)","muscle":"pectoraux","equipment":"none","desc":"1. Placez un banc entre deux poulies et réglez les poulies de sorte qu'elles se trouvent à hauteur de poitrine ou d'épaules une fois que vous êtes assis. 2. Saisissez les poignées en prise neutre et appuyez-vous contre le dossier vertical. 3. Rapprochez vos bras devant la poitrine dans un mouvement contrôlé, en vous concentrant sur la contraction des pectoraux. Gardez les coudes légèrement fléchis tout au long du mouvement. 4. Marquez une brève pause en position haute. 5. Ramenez lentement vos bras à la position de départ en gardant le contrôle du mouvement. 6. Répétez pour le nombre de répétitions souhaité.","tips":["Saisissez les poignées en prise neutre et appuyez-vous contre le dossier vertical","Rapprochez vos bras devant la poitrine dans un mouvement contrôlé, en vous concentrant sur la contraction des pectoraux","Marquez une brève pause en position haute","Ramenez lentement vos bras à la position de départ en gardant le contrôle du mouvement","Répétez pour le nombre de répétitions souhaité"],"image":"https://wger.de/media/exercise-images/1922/eb750ee5-3220-4128-aef1-5e2f1ccff40a.webp.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1928","wgerId":1928,"name":"Tirage assis à poignée en V","muscle":"dos","equipment":"none","desc":"Le **tirage assis à poignée en V** est un exercice de tirage polyarticulaire réalisé sur une machine à poulie avec une poignée en V à prise serrée. Assis, les pieds calés, vous tirez la poignée vers le milieu de votre ventre, en vous concentrant sur l'**épaisseur du dos** et le développement du milieu du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-1936","wgerId":1936,"name":"Oiseau à la poulie (un bras)","muscle":"jambes","equipment":"none","desc":"**Oiseau à la poulie (un bras) :** Tenez-vous de profil par rapport à une machine à poulie, la poignée réglée à environ hauteur d'épaule. Le coude légèrement fléchi, tirez la poignée vers l'extérieur et l'arrière en un large arc de cercle, de sorte que le bras s'éloigne du corps. Gardez le buste immobile et concentrez-vous sur le travail du deltoïde postérieur. Utilisez une charge **légère à modérée** et des répétitions contrôlées.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-92","wgerId":92,"name":"Curl biceps avec haltères","muscle":"bras","equipment":"elastiques","desc":"Tenez deux haltères, les bras tendus, les mains le long du corps, les paumes tournées vers l'intérieur. Fléchissez les bras et montez la charge d'un mouvement rapide. En même temps, effectuez une rotation des bras de 90 degrés dès le tout début du mouvement. Au point le plus haut, tournez légèrement les charges davantage vers l'extérieur. Sans pause, redescendez-les lentement. Ne laissez pas votre corps se balancer pendant l'exercice : tout le travail est effectué par les biceps, qui sont les seuls muscles qui doivent bouger (faites attention aux coudes).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/81/Biceps-curl-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-83","wgerId":83,"name":"Rowing buste penché","muscle":"dos","equipment":"barre","desc":"1. En tenant une barre en prise pronation (paumes tournées vers le bas), fléchissez légèrement les genoux et penchez le buste vers l'avant en vous inclinant au niveau de la taille, tout en gardant le dos droit, jusqu'à ce qu'il soit presque parallèle au sol. Conseil : veillez à garder la tête relevée. La barre doit pendre directement devant vous, vos bras étant perpendiculaires au sol et à votre buste. C'est votre position de départ. 2. Maintenant, en gardant le buste immobile, expirez et tirez la barre vers vous. Gardez les coudes près du corps et n'utilisez que les avant-bras pour tenir la charge. En position de contraction maximale, en hau","tips":["Maintenant, en gardant le buste immobile, expirez et tirez la barre vers vous","Inspirez ensuite et abaissez lentement la barre vers la position de départ","Répétez pour le nombre de répétitions recommandé"],"image":"https://wger.de/media/exercise-images/109/Barbell-rear-delt-row-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-81","wgerId":81,"name":"Rowing avec haltères buste penché","muscle":"dos","equipment":"barre","desc":"Des haltères en main, penchez-vous au niveau des hanches jusqu'à ce que les mains pendent juste en dessous des genoux (position semblable à celle de départ du soulevé de terre jambes tendues). Gardez l'angle du haut du corps constant tout en contractant le grand dorsal pour tirer les coudes vers l'arrière, en rapprochant les omoplates en haut du mouvement. Essayez de ne pas vous redresser à chaque répétition, et vérifiez que les mains descendent bien sous les genoux à chaque répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/81/a751a438-ae2d-4751-8d61-cef0e9292174.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-94","wgerId":94,"name":"Curl biceps avec barre SZ","muscle":"bras","equipment":"barre","desc":"Tenez la barre SZ à la largeur des épaules, le dos droit, les épaules légèrement en arrière, les bras tendus. Fléchissez les bras en montant la charge d'un mouvement rapide. Sans marquer de pause, redescendez la barre d'un mouvement lent et contrôlé. Ne laissez pas votre corps se balancer pendant l'exercice : tout le travail est effectué par les biceps, qui sont les seuls muscles qui doivent bouger (faites attention aux coudes).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/94/6dee2f60-aea2-4f2d-9bf6-aef50c4f9483.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-82","wgerId":82,"name":"Élévations latérales buste penché","muscle":"jambes","equipment":"barre","desc":"Asseyez-vous sur un banc en tenant des charges. Penchez-vous vers l'avant aussi loin que possible, les bras légèrement fléchis au niveau des coudes. Effectuez une élévation latérale tout en conservant la flexion de vos coudes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-75","wgerId":75,"name":"Développé couché avec haltères","muscle":"pectoraux","equipment":"barre","desc":"Le mouvement est très similaire au développé couché avec une barre, mais le poids est ramené plus bas sur la poitrine. Tenez deux haltères et allongez-vous sur un banc. Tenez les haltères près de la poitrine et poussez-les vers le haut jusqu'à ce que les bras soient tendus. Laissez retomber les haltères lentement et de manière contrôlée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/97/Dumbbell-bench-press-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-91","wgerId":91,"name":"Curl biceps à la barre","muscle":"bras","equipment":"barre","desc":"Tenez la barre à la largeur des épaules, le dos droit, les épaules légèrement en arrière, les bras tendus. Fléchissez les bras en montant la charge d'un mouvement rapide. Sans marquer de pause, redescendez la barre d'un mouvement lent et contrôlé. Ne laissez pas votre corps se balancer pendant l'exercice : tout le travail est effectué par les biceps, qui sont les seuls muscles qui doivent bouger (faites attention aux coudes).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/74/Bicep-curls-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1889","wgerId":1889,"name":"Relevé de jambes sur banc décliné","muscle":"abdos","equipment":"barre","desc":"- **Installation** : Allongez-vous sur un banc décliné, la tête en haut, et saisissez les poignées. - **Le départ** : Tendez complètement les jambes en les gardant légèrement surélevées pour engager la sangle abdominale. - **La montée** : Soulevez vos jambes vers le plafond à l'aide des abdominaux, sans utiliser l'élan. - **La contraction** : Marquez une pause et contractez le bas des abdominaux en position haute. - **Le retour** : Abaissez lentement vos jambes vers la position de départ en gardant le contrôle.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1889/bc51ef67-0c12-4340-a36c-42ef722778dd.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-73","wgerId":73,"name":"Développé couché","muscle":"pectoraux","equipment":"barre","desc":"Allongez-vous sur un banc, la barre doit se trouver directement au-dessus de vos yeux, les genoux légèrement fléchis et les pieds fermement posés au sol. Concentrez-vous, respirez profondément et saisissez la barre un peu plus large que la largeur des épaules. Descendez-la lentement jusqu'à ce qu'elle effleure brièvement votre poitrine à la hauteur des tétons. Poussez la barre vers le haut. Si vous vous entraînez avec une charge élevée, il est conseillé d'avoir un *pareur* qui peut vous aider à relever la barre si vous ne parvenez pas à la soulever seul. Avec la largeur de la prise, vous pouvez aussi contrôler quelle partie des pectoraux est ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/192/Bench-press-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-76","wgerId":76,"name":"Développé couché prise serrée","muscle":"bras","equipment":"barre","desc":"- **Mise en place :** Allongez-vous à plat sur le banc et saisissez la barre à la largeur des épaules (plus serré qu'un développé couché classique). - **Descente :** Abaissez la barre de façon contrôlée vers le bas de la poitrine. - **Technique :** Gardez les coudes bien serrés contre le torse, ne les laissez pas s'écarter. - **Montée :** Poussez la barre droit vers le haut en contractant vos triceps en fin de mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/88/Narrow-grip-bench-press-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-349","wgerId":349,"name":"Tirage latéral à la poulie, à un bras","muscle":"epaules","equipment":"none","desc":"Réglez la poulie à hauteur de la taille, commencez le bras en travers du ventre puis déplacez la main vers l'autre côté en l'éloignant, un bras à la fois.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/349/9d969203-9cb6-4d47-9c31-fef53bfe1de5.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-185","wgerId":185,"name":"Développé couché décliné à la barre","muscle":"pectoraux","equipment":"barre","desc":"Allongez-vous sur un banc décliné, la barre doit se trouver directement au-dessus de vos yeux, les genoux légèrement fléchis et les pieds fermement posés au sol. Concentrez-vous, respirez profondément et saisissez la barre un peu plus large que la largeur des épaules. Abaissez-la lentement jusqu'à ce qu'elle effleure brièvement votre poitrine à la hauteur des mamelons. Poussez la barre vers le haut.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/100/Decline-bench-press-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-186","wgerId":186,"name":"Développé couché décliné aux haltères","muscle":"pectoraux","equipment":"barre","desc":"Prenez deux haltères et asseyez-vous sur un banc décliné, les pieds fermement posés au sol, la tête reposant sur le banc. Tenez les poids près de la poitrine, à la hauteur des mamelons, et poussez-les vers le haut jusqu'à ce que les bras soient tendus. Redescendez la charge lentement et de façon contrôlée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-51","wgerId":51,"name":"Curl des poignets à la barre","muscle":"jambes","equipment":"barre","desc":"Assis sur un banc, saisissez une barre, paumes tournées vers le haut et mains écartées à la largeur des épaules. Posez vos avant-bras sur vos cuisses et laissez vos poignets dépasser au-delà de vos genoux. Effectuez le mouvement en enroulant vos paumes et vos poignets vers votre visage. Marquez une pause en position haute, puis ramenez lentement la barre à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/51/f1730f56-7aca-4566-8338-3e42b1bee6e1.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-12","wgerId":12,"name":"Adduction de hanche assise","muscle":"fessiers","equipment":"none","desc":"Position de départ : asseyez-vous sur la machine, les genoux vers l'intérieur et contre les coussinets. Tirez la goupille pour libérer les coussinets. Saisissez les poignées sur les côtés.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/12/4a42cc6f-648d-40cc-a72a-c49dd47e1667.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-56","wgerId":56,"name":"Abdominal Stabilization","muscle":"abdos","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"other"},{"id":"wger-282","wgerId":282,"name":"Pompe en équilibre sur les mains","muscle":"epaules","equipment":"none","desc":"La pompe en équilibre sur les mains, également appelée pompe verticale ou pompe inversée, est un type d'exercice de pompe où le corps est positionné en équilibre sur les mains. Pour un véritable équilibre, l'exercice est réalisé en autonomie, en suspension dans l'air. Afin de développer la force jusqu'à acquérir un équilibre suffisant, les pieds sont souvent placés contre un mur, tenus par un partenaire ou maintenus d'une autre façon pour éviter la chute. Les pompes en équilibre sur les mains exigent une force considérable, ainsi que de l'équilibre et du contrôle si elles sont exécutées en autonomie.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/282/f6121ac9-330e-4ed7-8219-91ce246bf871.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-194","wgerId":194,"name":"Dips","muscle":"pectoraux","equipment":"none","desc":"Le dip est un exercice de musculation pour le haut du corps. Les dips à prise serrée, à largeur d'épaules, sollicitent principalement les triceps, les principaux muscles synergistes étant le deltoïde antérieur, les muscles pectoraux (sternal, claviculaire et petit pectoral) et les rhomboïdes du dos (dans cet ordre).[1] Un entraînement bras écartés met davantage l'accent sur les pectoraux, de la même manière qu'un développé couché à prise large sollicite davantage les pectoraux et moins les triceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/194/34600351-8b0b-4cb0-8daa-583537be15b0.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-239","wgerId":239,"name":"Écarté aux haltères sur banc décliné","muscle":"pectoraux","equipment":"barre","desc":"L'exercice est le même que sur un banc classique : Prenez deux haltères et allongez-vous sur un banc, veillez à ce que les pieds soient fermement posés au sol et à ce que votre dos ne soit pas cambré, mais bien en contact avec le banc. Les bras sont tendus devant vous, à environ la largeur des épaules. Fléchissez maintenant légèrement les bras et écartez-les sur le côté par un mouvement en demi-cercle. Sans modifier l'angle du coude, ramenez-les vers le haut d'un mouvement fluide.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-165","wgerId":165,"name":"Ball crunches","muscle":"abdos","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"other"},{"id":"wger-95","wgerId":95,"name":"Curl biceps à la poulie","muscle":"bras","equipment":"none","desc":"Tenez-vous à environ 30 à 40 cm de la poulie, les pieds fermement posés au sol. Saisissez la barre et soulevez la charge d'un mouvement rapide. Abaissez la charge lentement et de façon contrôlée, comme pour les curls avec haltères.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/129/Standing-biceps-curl-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-237","wgerId":237,"name":"Fly With Cable","muscle":"pectoraux","equipment":"none","desc":"cable machine, two steps forward, straight back","tips":["cable machine, two steps forward, straight back"],"image":"https://wger.de/media/exercise-images/122/Incline-cable-flyes-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-275","wgerId":275,"name":"Curl marteau à la poulie","muscle":"bras","equipment":"none","desc":"Saisissez une poignée de poulie dans les mains (paumes parallèles, l'une face à l'autre), le corps droit. Fléchissez les bras et montez la charge d'un mouvement rapide. Sans aucune pause, redescendez-la d'un mouvement lent et contrôlé, mais sans tendre complètement les bras. Ne balancez pas votre corps pendant l'exercice, les biceps doivent effectuer tout le travail ici. Les coudes restent le long du corps et ne bougent pas.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/138/Hammer-curls-with-rope-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-265","wgerId":265,"name":"Pont fessier","muscle":"fessiers","equipment":"none","desc":"Allongez-vous sur le dos, les hanches et les genoux fléchis, les pieds au sol. À partir de cette position, soulevez les fessiers du sol jusqu'à ce que votre corps forme une ligne droite des genoux aux épaules. Pour rendre l'exercice plus intense, vous pouvez ajouter du poids en laissant reposer une barre sur vos hanches pendant que vous effectuez le mouvement, ou vous pouvez poser vos pieds sur une surface légèrement plus haute, comme une marche ou un banc.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-158","wgerId":158,"name":"Tirage vertical prise serrée","muscle":"dos","equipment":"none","desc":"Saisissez la barre de tirage, les mains plus rapprochées que la largeur des épaules, les paumes tournées vers l'extérieur. Penchez-vous légèrement en arrière. Tirez la barre vers votre poitrine en gardant les coudes près des flancs pendant la descente. Rapprochez vos épaules en arrière à la fin du mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/158/0d51a0f2-622f-434b-beb8-1a003c54712a.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-124","wgerId":124,"name":"Squat gainé","muscle":"jambes","equipment":"none","desc":"Tenez-vous debout, les pieds légèrement plus écartés que la largeur des épaules, en vous grandissant autant que possible. Saisissez un disque de fonte et tenez-le devant votre corps, les bras tendus devant vous. Gardez la sangle abdominale contractée et conservez une cambrure naturelle dans le dos. Maintenant, poussez les hanches vers l'arrière et fléchissez les genoux en descendant en squat aussi bas que possible. Maintenez la position quelques instants, puis remontez à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-146","wgerId":146,"name":"Extension des mollets à la presse à cuisses","muscle":"jambes","equipment":"none","desc":"Placez la pointe de vos pieds sur le plateau d'une presse à cuisses en extension. Utilisez vos mollets pour pousser la charge en tendant les pieds et les orteils en pointe, puis revenez à une position détendue. Cet exercice développe la masse et la force des muscles gastrocnémien et soléaire aussi bien, sinon mieux, que n'importe quel exercice pour les mollets.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/146/8b284904-d072-4381-a256-4c81d8fd9c1f.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-148","wgerId":148,"name":"Extension des mollets à la machine Hackenschmidt","muscle":"jambes","equipment":"none","desc":"Installez-vous sur la machine, le dos fermement appuyé contre le dossier, les pieds posés sur la plateforme pour les extensions de mollets. Vérifiez que les pieds dépassent à moitié et que vous pouvez étirer complètement les muscles des mollets vers le bas. Les genoux tendus, soulevez votre charge aussi haut que possible. Redescendez d'un mouvement fluide jusqu'à ce que les mollets soient complètement étirés. Répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-137","wgerId":137,"name":"Butterfly à prise serrée","muscle":"pectoraux","equipment":"none","desc":"Le mouvement est identique à celui du butterfly classique, à ceci près que la prise est serrée : Asseyez-vous sur la machine à butterfly, les pieds bien en contact avec le sol, les bras en position parallèle au sol. Rapprochez vos bras jusqu'à ce que les poignées soient pratiquement jointes (mais sans qu'elles se touchent !). Revenez lentement. Les poids doivent rester en permanence en suspension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-135","wgerId":135,"name":"Butterfly","muscle":"pectoraux","equipment":"none","desc":"Asseyez-vous sur la machine à butterfly, les pieds bien en contact avec le sol, les bras en position parallèle au sol. Rapprochez vos bras jusqu'à ce que les poignées soient pratiquement jointes (mais sans qu'elles se touchent !). Revenez lentement. Les poids doivent rester en permanence en suspension.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/98/Butterfly-machine-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-172","wgerId":172,"name":"Crunchs à la machine","muscle":"abdos","equipment":"none","desc":"La procédure est très semblable à celle des crunchs classiques, avec en plus la charge de la machine. Asseyez-vous sur la machine et posez fermement les deux pieds au sol. Saisissez les poids, les câbles, etc., et effectuez un mouvement d'enroulement vers l'avant (la colonne vertébrale doit idéalement se dérouler vertèbre par vertèbre). Revenez lentement à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-171","wgerId":171,"name":"Crunchs sur banc incliné","muscle":"abdos","equipment":"barre","desc":"Allongez-vous sur le dos sur un banc incliné, les pieds à une extrémité du banc. Demandez à un partenaire ou utilisez un autre moyen (une barre, etc.) pour les maintenir en place, vos mains derrière la tête. À partir de cette position, relevez le haut du corps jusqu'à ce que votre tête ou vos coudes touchent vos genoux. Effectuez ce mouvement en enroulant le dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/56/Decline-crunch-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-139","wgerId":139,"name":"Butterfly Reverse","muscle":"epaules","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-167","wgerId":167,"name":"Abdominaux","muscle":"abdos","equipment":"none","desc":"1. Allongez-vous sur le sol, face contre terre, genoux pliés. 2. Courbez les épaules vers le bassin. Les mains peuvent être derrière ou à côté du cou ou croisées sur la poitrine. 3. Répétez","tips":["Allongez-vous sur le sol, face contre terre, genoux pliés","Courbez les épaules vers le bassin"],"image":"https://wger.de/media/exercise-images/91/Crunches-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-174","wgerId":174,"name":"Crunchs jambes en l'air","muscle":"abdos","equipment":"none","desc":"Allongé sur le dos, les jambes tendues à la verticale, tendez les mains vers vos orteils et décollez les omoplates du sol avant de les reposer.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-189","wgerId":189,"name":"Soulevé de terre en déficit","muscle":"jambes","equipment":"barre","desc":"Préparation Tenez-vous debout sur un disque, un disque amortisseur ou une plateforme légèrement surélevée, la barre chargée au-dessus des pieds. Accroupissez-vous et saisissez la barre avec une prise en pronation ou mixte, à largeur d'épaules ou légèrement plus large. Exécution Soulevez la barre en étendant complètement les hanches et les genoux. Tirez les épaules vers l'arrière en haut du mouvement si elles sont arrondies. Reposez les poids au sol en repoussant les hanches vers l'arrière tout en laissant les genoux se fléchir vers l'avant, en gardant le dos droit et les genoux orientés dans la même direction que les pieds. Répétez. Remarques","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-235","wgerId":235,"name":"Battements de jambes","muscle":"abdos","equipment":"none","desc":"-Allongé sur le dos, décollez vos jambes tendues du sol selon un angle de 45 degrés. -Lorsque votre pied gauche descend et frôle presque le sol, votre pied droit doit chercher à atteindre un angle de 90 degrés, ou s'en approcher le plus possible. -Abaissez votre pied droit jusqu'à ce qu'il frôle presque le sol, puis relevez votre pied gauche. Maintenez les jambes rigides pendant tout l'exercice. Votre tête doit rester décollée du sol, soutenue par le haut des abdominaux contracté. -(gauche en haut droit en bas, gauche en bas droit en haut, x2) ^v, v^, ^v, v^ = 1 répétition -Sollicite principalement le grand droit de l'abdomen, les fléchisseur","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-184","wgerId":184,"name":"Soulevés de terre","muscle":"dos","equipment":"barre","desc":"Tenez-vous fermement debout, les pieds un peu plus écartés que la largeur des épaules. Placez-vous directement derrière la barre, qui doit à peine toucher votre tibia, les pieds légèrement orientés vers l'extérieur. Penchez-vous en gardant le dos droit, les genoux eux aussi légèrement vers l'extérieur. Saisissez la barre avec une prise à largeur d'épaules, une main en pronation, l'autre en supination. Tirez la charge vers le haut. Au point le plus haut, creusez légèrement le dos et tirez la barre vers l'arrière. Tenez cette position 1 ou 2 secondes. Redescendez en veillant à ne pas arrondir le dos. Une fois en bas, vous pouvez soit repartir d","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/184/1709c405-620a-4d07-9658-fade2b66a2df.jpeg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-193","wgerId":193,"name":"Développé épaules en diagonale","muscle":"jambes","equipment":"barre","desc":"Vous êtes assis sur l'appareil à développé couché, le dos légèrement incliné vers l'arrière. La barre doit se trouver à environ 20 cm devant vous. Vous poussez ensuite la barre puis la ramenez, comme vous le feriez au développé couché. Dans cette position, vous sollicitez beaucoup moins les pectoraux, ce qui est appréciable si vous voulez vous entraîner alors que votre poitrine n'est pas encore récupérée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-203","wgerId":203,"name":"Squat goblet avec haltère","muscle":"jambes","equipment":"elastiques","desc":"Saisissez l'haltère des deux mains, au niveau des bords des disques supérieurs. Tenez l'haltère devant la poitrine, près du torse. Placez les pieds à environ la largeur des épaules, en gardant les genoux légèrement fléchis. Descendez en squat jusqu'à ce que les cuisses soient parallèles au sol. Gardez le dos droit, fléchissez et reculez les hanches pour que les genoux restent au-dessus des pieds. Remontez en gardant les genoux légèrement fléchis. Répétez. Gardez le poids du corps sur les talons et regardez devant vous ou légèrement vers le haut afin de garder le dos droit.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/203/1c052351-2af0-4227-aeb0-244008e4b0a8.jpeg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-205","wgerId":205,"name":"Dumbbell Lunges Standing","muscle":"jambes","equipment":"elastiques","desc":".","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-206","wgerId":206,"name":"Fentes marchées avec haltères","muscle":"jambes","equipment":"elastiques","desc":"- **Position de départ :** Tenez-vous debout, les pieds écartés de la largeur des hanches, les mains sur les hanches ou tenant des haltères le long du corps. - **Le pas :** Faites un grand pas en avant avec la jambe droite. - **La descente :** Abaissez vos hanches jusqu'à ce que les deux genoux soient pliés à environ **90 degrés**. - **La transition :** Poussez à travers le talon avant pour vous redresser, en ramenant le pied arrière vers l'avant pour enchaîner directement sur la fente suivante.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/113/Walking-lunges-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-238","wgerId":238,"name":"Écarté aux haltères","muscle":"pectoraux","equipment":"elastiques","desc":"Prenez deux haltères et allongez-vous sur un banc, veillez à ce que les pieds soient fermement posés au sol et à ce que votre dos ne soit pas cambré, mais bien en contact avec le banc. Les bras sont tendus devant vous, à environ la largeur des épaules. Fléchissez maintenant légèrement les bras et écartez-les sur le côté par un mouvement en demi-cercle. Sans modifier l'angle du coude, ramenez-les vers le haut d'un mouvement fluide.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/238/2fc242d3-5bdd-4f97-99bd-678adb8c96fc.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-204","wgerId":204,"name":"Curl incliné aux haltères","muscle":"bras","equipment":"elastiques","desc":"- **Installation :** Réglez un banc ajustable sur une inclinaison d'environ **45 à 60 degrés**. - **Position de départ :** Asseyez-vous en appui contre le banc, un haltère dans chaque main. Laissez vos bras pendre à la verticale vers le sol, les paumes tournées vers l'avant (prise en supination). - **Le curl :** En gardant les bras immobiles et les épaules plaquées contre le banc, expirez et enroulez les poids vers vos épaules. - **Contraction maximale :** Contractez fortement vos biceps en haut du mouvement, en veillant à ce que vos coudes ne basculent pas vers l'avant. - **La descente :** Inspirez et abaissez lentement les haltères jusqu'à ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-211","wgerId":211,"name":"Extension des triceps à l'haltère","muscle":"bras","equipment":"elastiques","desc":"Placez un haltère au-dessus de la tête, les deux mains sous le disque intérieur (prise en cœur). Les coudes au-dessus de la tête, abaissez l'avant-bras derrière le bras en fléchissant les coudes. Fléchissez les poignets en bas du mouvement pour éviter de heurter votre nuque avec l'haltère. Relevez l'haltère au-dessus de la tête en étendant les coudes tout en plaçant les poignets en hyperextension. Revenez et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-197","wgerId":197,"name":"Dips entre deux bancs","muscle":"bras","equipment":"barre","desc":"Disposez deux bancs suffisamment éloignés l'un de l'autre pour que vous puissiez vous appuyer sur l'un avec les mains tout en parvenant tout juste à atteindre l'autre avec les pieds. Les jambes restent complètement tendues pendant l'exercice. Les coudes orientés vers l'arrière, fléchissez-les autant que possible. Repoussez-vous vers le haut, mais sans tendre complètement les bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/83/Bench-dips-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-254","wgerId":254,"name":"Élévation frontale au disque","muscle":"epaules","equipment":"none","desc":"L'élévation frontale au disque est une variante de l'élévation frontale aux haltères dans laquelle le pratiquant tient un disque de fonte entre ses deux mains, plutôt qu'un haltère, une barre ou un autre poids. Elle peut apporter de la variété à une séance de renforcement axée sur les épaules, ou s'intégrer à un circuit pour le haut du corps ou pour tout le corps. 1. En position debout bien droite, tenez un disque de barre à deux mains aux positions 3 heures et 9 heures. Vos paumes doivent se faire face et vos bras doivent être tendus et verrouillés, avec une légère flexion des coudes ; le disque doit se trouver en bas, près de votre taille, ","tips":["En position debout bien droite, tenez un disque de barre à deux mains aux positions","Levez lentement le disque en expirant, jusqu'à ce qu'il soit un peu au-dessus du niveau des épaules","Répétez le nombre de répétitions recommandé"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-283","wgerId":283,"name":"Hanging Leg Raises","muscle":"abdos","equipment":"none","desc":"Hanging from bar or straps, bring legs up with knees extended or flexed","tips":["Hanging from bar or straps, bring legs up with knees extended or flexed"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"other"},{"id":"wger-256","wgerId":256,"name":"Élévations frontales","muscle":"epaules","equipment":"barre","desc":"Pour exécuter l'exercice, le pratiquant se tient debout, les pieds à la largeur des épaules, des poids ou des poignées élastiques tenus le long du corps avec une prise en pronation. Le mouvement consiste à monter les bras devant le corps jusqu'à la hauteur des yeux, en ne conservant qu'une légère flexion du coude. Cela isole le deltoïde antérieur (avant de l'épaule) et utilise le deltoïde antérieur pour soulever la charge. Lors du mouvement, il est important de garder le corps immobile afin que le deltoïde antérieur soit pleinement sollicité ; si la charge ne peut être soulevée en restant immobile, c'est qu'elle est trop lourde et qu'un poids","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/256/b7def5bc-2352-499b-b9e5-fff741003831.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-291","wgerId":291,"name":"Squats hindous","muscle":"jambes","equipment":"none","desc":"Commencez les pieds à la largeur des épaules et les bras légèrement derrière le dos. À mesure que vous descendez vers le sol, décollez vos talons du sol tout en gardant le dos aussi vertical que possible. Une fois la position basse atteinte, touchez vos talons avec vos mains. Relevez-vous ensuite en terminant les talons au sol, les bras tendus devant la poitrine, puis ramenez-les en tirant vers la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-257","wgerId":257,"name":"Front Squats","muscle":"fessiers","equipment":"barre","desc":"This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.","tips":["This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors."],"image":"https://wger.de/media/exercise-images/191/Front-squat-1-857x1024.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-272","wgerId":272,"name":"Curls marteau","muscle":"bras","equipment":"elastiques","desc":"- **Départ :** Tenez les haltères le long du corps, les paumes tournées vers le torse. - **Curl :** Montez les poids vers vos épaules en conservant la prise neutre (comme si vous teniez un marteau). - **Contraction :** Contractez les biceps en haut sans avancer les coudes. - **Descente :** Revenez lentement à la position de départ en gardant un contrôle total.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/86/Bicep-hammer-curl-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-245","wgerId":245,"name":"Barre au front aux haltères","muscle":"bras","equipment":"barre","desc":"Tenez les haltères et allongez-vous sur un banc plat de manière à ce qu'environ un quart de votre tête dépasse du bord. Tendez les bras à la verticale, puis inclinez les haltères en direction opposée à vos orteils, selon un angle de 10 à 20 degrés. Conservez le bras à cet angle pendant tout l'exercice. L'haltère ne doit pas être dirigé vers votre tête, mais au-delà, derrière votre tête. Cela maximise le bénéfice de l'exercice en gardant la charge sur les triceps en permanence. Prêtez attention à vos coudes et à vos bras : seuls les triceps travaillent, le reste des bras ne doit pas bouger.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-246","wgerId":246,"name":"Barre au front à la barre EZ","muscle":"bras","equipment":"barre","desc":"Tenez la barre EZ et allongez-vous sur un banc plat de manière à ce qu'environ un quart de votre tête dépasse du bord. Tendez les bras avec la barre, puis fléchissez-les pour abaisser la barre. Juste avant qu'elle ne touche votre front, repoussez-la vers le haut. Prêtez attention à vos coudes et à vos bras : seuls les triceps travaillent, le reste des bras ne doit pas bouger.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/84/Lying-close-grip-triceps-press-to-chin-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-259","wgerId":259,"name":"Front Pull narrow","muscle":"dos","equipment":"barre","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-258","wgerId":258,"name":"Front pull wide","muscle":"dos","equipment":"barre","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-365","wgerId":365,"name":"Leg curl (allongé)","muscle":"jambes","equipment":"none","desc":"Allongez-vous sur un banc et placez vos mollets derrière le rouleau (de préférence en appui autour du bas des mollets). Maintenez une prise sur les poignées pour bien stabiliser le corps. Fléchissez vos jambes en montant la charge, puis revenez lentement. Pendant l'exercice, le corps ne doit pas bouger, tout le travail est effectué par les jambes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/154/lying-leg-curl-machine-large-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-354","wgerId":354,"name":"Lat Pull Down (Leaning Back)","muscle":"dos","equipment":"none","desc":"Lean Back, Pull into chest","tips":["Lean Back, Pull into chest"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-355","wgerId":355,"name":"Tirage vertical à la poulie haute","muscle":"dos","equipment":"none","desc":"Le tirage vertical à la poulie haute est un exercice utilisé pour développer les muscles du dos. Bien qu'il cible principalement le grand dorsal, vous remarquerez aussi une sollicitation notable des biceps et du milieu du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-366","wgerId":366,"name":"Leg Curls (sitting)","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/117/seated-leg-curl-large-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-348","wgerId":348,"name":"Élévations latérales","muscle":"epaules","equipment":"elastiques","desc":"Cet exercice sollicite le deltoïde de l'épaule. Le mouvement débute bras tendus, les mains tenant des poids le long du corps ou devant le corps. Le corps est légèrement penché vers l'avant, les hanches et les genoux un peu fléchis. Les bras sont gardés tendus ou légèrement fléchis, et montés selon un arc de mouvement dans le plan frontal qui se termine lorsque les mains arrivent approximativement à hauteur des épaules. Les poids sont redescendus à la position de départ, ce qui complète une répétition. Avec une poulie, le pratiquant se place de manière à ce que son plan frontal soit aligné avec la poulie, qui se trouve au niveau du sol ou à pr","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/148/lateral-dumbbell-raises-large-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-364","wgerId":364,"name":"Leg curl","muscle":"jambes","equipment":"none","desc":"Le leg curl, également appelé curl des ischio-jambiers, est un exercice d'isolation qui cible les ischio-jambiers. L'exercice consiste à fléchir la partie basse de la jambe contre une résistance, en direction des fessiers. D'autres exercices peuvent être utilisés pour renforcer les ischio-jambiers, comme le glute-ham raise et le soulevé de terre.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/364/b318dde9-f5f2-489f-940a-cd864affb9e3.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-351","wgerId":351,"name":"Élévations latérales puis frontales","muscle":"epaules","equipment":"elastiques","desc":"-(1) Effectuez une élévation latérale, en marquant une pause en haut du mouvement (2). -Au lieu de redescendre la charge, ramenez-la devant votre corps de manière à vous retrouver en position haute d'une élévation frontale. Vous le ferez par un mouvement de pec fly, en gardant les bras tendus. (3) -Abaissez maintenant la charge vers vos quadriceps, autrement dit, descendez les haltères comme si vous terminiez une répétition d'élévation frontale. (4) -Inversez le mouvement : effectuez une élévation frontale (5), au sommet du mouvement utilisez un mouvement de reverse fly pour amener les poids en position haute d'une élévation latérale (6), et ","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-341","wgerId":341,"name":"Squats on Multipress","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-308","wgerId":308,"name":"Écarté incliné aux haltères","muscle":"pectoraux","equipment":"elastiques","desc":"Utilisez un banc incliné. Tenez les haltères tendus sur les côtés, les coudes légèrement fléchis. Rapprochez les bras au-dessus de vous, en conservant l'angle des coudes fixe.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-803","wgerId":803,"name":"One Arm Triceps Extensions on Cable","muscle":"bras","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"other"},{"id":"wger-822","wgerId":822,"name":"Oiseau à la poulie","muscle":"epaules","equipment":"none","desc":"L'oiseau à la poulie, également appelé écarté inversé à la poulie, est un exercice de renforcement et de définition des deltoïdes. C'est l'un des meilleurs exercices d'isolation pour votre dos et votre deltoïde postérieur. Cet exercice cible vos deltoïdes postérieurs (arrière) tout en sollicitant un ensemble de muscles du haut du corps. 1. Réglez la charge et les poulies à la bonne hauteur. Vous devez pouvoir voir les poulies, car elles doivent se trouver au-dessus de votre tête. 2. De la main droite, saisissez la poulie de gauche, et de la main gauche, saisissez la poulie de droite, en les croisant devant vous. C'est ici que commence votre m","tips":["Réglez la charge et les poulies à la bonne hauteur","Amorcez le mouvement en écartant et rapprochant les bras, tout en gardant les bras tendus","Marquez une brève pause à la fin du mouvement avant de ramener les poignées à leur position de départ"],"image":"https://wger.de/media/exercise-images/822/74affc0d-03b6-4f33-b5f4-a822a2615f68.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-331","wgerId":331,"name":"Swings au kettlebell","muscle":"fessiers","equipment":"elastiques","desc":"Tenez fermement le kettlebell à deux mains. Gardez le dos plat pendant tout le mouvement, en évitant tout arrondissement de la colonne vertébrale. En gardant les genoux \"souples\", basculez les hanches vers l'arrière, en laissant le kettlebell osciller entre vos genoux. Vous devez vous fléchir au niveau des hanches autant que possible *sans laisser votre dos s'arrondir vers l'avant*. Projetez ensuite rapidement les hanches vers l'avant et redressez-vous, en verrouillant votre corps dans une posture droite. La vitesse de ce mouvement fera monter vos bras et le kettlebell devant vous. N'essayez pas de *soulever* le kettlebell avec vos bras. La p","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-380","wgerId":380,"name":"Leverage Machine Iso Row","muscle":"dos","equipment":"none","desc":"Adjust seat height so that the handles are at the bottom of your pectorals or just below.","tips":["Adjust seat height so that the handles are at the bottom of your pectorals or just below."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-427","wgerId":427,"name":"Crunchs négatifs","muscle":"abdos","equipment":"none","desc":"Asseyez-vous sur le banc décliné et bloquez vos jambes. Croisez les bras sur la poitrine et relevez le haut du corps par un mouvement d'enroulement, puis redescendez sans pause et par un mouvement lent. Ne laissez pas votre tête bouger pendant l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/93/Decline-crunch-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-386","wgerId":386,"name":"Pompes diamant","muscle":"pectoraux","equipment":"none","desc":"Départ : mettez-vous en position de planche. Placez les mains rapprochées sous votre poitrine de sorte que les pouces et les index forment un losange. Descente : pliez les coudes pour abaisser votre poitrine vers vos mains. Gardez le corps droit. Poussée : repoussez vers le haut jusqu'à ce que les bras soient complètement tendus. Remarque : gardez les coudes près du corps et la sangle abdominale gainée.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-378","wgerId":378,"name":"Relevés de jambes, debout","muscle":"abdos","equipment":"none","desc":"Placez vos avant-bras sur les coussinets de la machine à relevés de jambes, le corps est suspendu librement. Levez maintenant vos jambes par un mouvement rapide aussi haut que possible, marquez une courte pause d'une seconde en haut, puis redescendez-les. Assurez-vous que votre corps ne se balance pas pendant l'exercice, seules les jambes doivent bouger.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-379","wgerId":379,"name":"Leverage Machine Chest Press","muscle":"pectoraux","equipment":"none","desc":"Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.","tips":["Be sure to adjust seat height so that the handles are towards the bottom of your pectorals."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-377","wgerId":377,"name":"Relevés de jambes, allongé","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur un banc et tenez-vous au dossier avec les mains pour rester stable. Gardez vos jambes tendues et levez-les jusqu'à ce qu'elles forment un angle d'environ 45°. Marquez une courte pause d'une seconde et redescendez lentement à la position initiale. Pour augmenter l'intensité, vous pouvez marquer une pause plus longue de 7 secondes toutes les 5 répétitions.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/125/Leg-raises-2.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-376","wgerId":376,"name":"Levées de jambe","muscle":"abdos","equipment":"none","desc":"The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-397","wgerId":397,"name":"Box squat bas - position large","muscle":"fessiers","equipment":"barre","desc":"Sortez la barre du support et adoptez une position large, au-delà de la largeur des hanches. Poussez les hanches vers l'arrière et asseyez-vous sur une box qui vous amène sous la parallèle. Asseyez-vous complètement, ne touchez pas pour rebondir aussitôt. Relevez-vous ensuite de manière explosive. Gardez le haut du dos et le tronc bien gainés pendant tout le mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-367","wgerId":367,"name":"Leg Curls (standing)","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/118/standing-leg-curls-large-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-375","wgerId":375,"name":"Leg Press on Hackenschmidt Machine","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/130/Narrow-stance-hack-squats-1-1024x721.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-373","wgerId":373,"name":"Presse à cuisses (serrée)","muscle":"jambes","equipment":"none","desc":"L'exercice est très similaire à la presse à cuisses large : Asseyez-vous sur la machine et placez vos pieds sur la plateforme suffisamment écartés pour pouvoir tout juste glisser un autre pied entre eux. Les pieds sont parallèles et pointent vers le haut. Abaissez le poids jusqu'à ce que les genoux forment un angle droit. Repoussez immédiatement la plateforme vers le haut, sans aucune pause. En position basse, les genoux pointent légèrement vers l'extérieur et le mouvement doit toujours rester fluide.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/373/60e2aa21-1910-40d3-9fed-babfee06dd48.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-374","wgerId":374,"name":"Presse à cuisses (large)","muscle":"jambes","equipment":"none","desc":"Asseyez-vous sur la machine et placez vos pieds sur la plateforme, un peu plus large que la largeur des épaules. Les pieds sont tournés vers l'extérieur de quelques degrés. Abaissez le poids jusqu'à ce que les genoux forment un angle droit. Repoussez immédiatement la plateforme vers le haut, sans aucune pause. En position basse, les genoux pointent légèrement vers l'extérieur et le mouvement doit toujours rester fluide.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-448","wgerId":448,"name":"Rowing Pendlay","muscle":"dos","equipment":"barre","desc":"Exercice de dos avec une barre, dont la position de départ est penchée en avant, le dos parallèle au sol. La barre repose au sol à hauteur de la poitrine. Pour le mouvement, saisissez la barre avec une prise à largeur d'épaules et tirez-la vers votre poitrine sans perdre la position penchée et sans bouger autre chose que vos bras.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-484","wgerId":484,"name":"Soulevé de terre au rack","muscle":"fessiers","equipment":"none","desc":"Soulevé de terre à réaliser sur une machine Smith ou un rack libre. La barre doit se trouver juste sous le niveau de la rotule. Soulevez en utilisant les fessiers et en poussant à travers les talons, puis revenez à la position de départ par un mouvement contrôlé de 2 secondes. Cet exercice sollicite principalement le bas du dos et les fessiers.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/161/Dead-lifts-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-478","wgerId":478,"name":"Push press","muscle":"dos","equipment":"none","desc":"Amenez vos haltères sur vos épaules par un mouvement d'épaulé, paumes tournées vers l'intérieur. Inspirez et gainez votre sangle abdominale (image 1). Fléchissez les genoux et utilisez vos jambes pour aider (image 2) à pousser vos haltères au-dessus de la tête. Redescendez-les sous contrôle, à un rythme lent, jusqu'à vos épaules, puis répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/478/70a2d72c-a822-45f3-8de2-54ea85951b84.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-445","wgerId":445,"name":"Développé couché avec pause","muscle":"pectoraux","equipment":"barre","desc":"Abaissez la barre vers votre poitrine et marquez une pause (sans relâcher) de 2 secondes. Repoussez vers le haut. Utilisez le même poids que pour le développé couché classique, mais n'effectuez que des répétitions isolées. Faites au total le nombre de répétitions que vous feriez en une série de développé couché (si vous faisiez 3 séries de 8, faites 8 répétitions isolées de développé couché avec pause).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-487","wgerId":487,"name":"Élévations pour deltoïdes postérieurs","muscle":"jambes","equipment":"elastiques","desc":"Assis sur un banc, les haltères au sol, penchez-vous en avant à 45 degrés, puis levez lentement chaque haltère jusqu'à la hauteur des épaules et maintenez quelques secondes avant de redescendre à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/487/ad724e5c-b1ed-49e8-9279-a17545b0dd0b.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-456","wgerId":456,"name":"Pistol squats gauches","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous debout sur une jambe, l'autre jambe droite et légèrement en avant 2. Pliez lentement un genou, descendez en position accroupie et gardez votre dos et votre autre jambe droits 3. Soulevez-vous lentement du squat, en redressant le genou plié et en gardant l'autre jambe droite 4. Répéter","tips":["Tenez-vous debout sur une jambe, l'autre jambe droite et légèrement en avant","Pliez lentement un genou, descendez en position accroupie et gardez votre dos et votre autre jambe droits","Soulevez-vous lentement du squat, en redressant le genou plié et en gardant l'autre jambe droite"],"image":"https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-477","wgerId":477,"name":"Pull Ups on Machine","muscle":"dos","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-475","wgerId":475,"name":"Tractions","muscle":"dos","equipment":"none","desc":"Prenez la barre de traction avec les deux mains écartées. En gardant la poitrine en avant, tirez avec vos bras jusqu’à ce que votre mentons atteigne la barre. Controlez le mouvement lors de la montée et de la descente.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/475/b0554016-16fd-4dbe-be47-a2a17d16ae0e.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-458","wgerId":458,"name":"Planche pour les avant-bras","muscle":"abdos","equipment":"none","desc":"Position de départ : 1. Commencez à quatre pattes.Les bras doivent être pliés à angle droit, les épaules au-dessus des coudes.Le dos doit être droit, le corps entier en ligne droite. Étapes : 1. Maintenez cette position.","tips":["Commencez à quatre pattes","Maintenez cette position"],"image":"https://wger.de/media/exercise-images/458/b7bd9c28-9f1d-4647-bd17-ab6a3adf5770.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-545","wgerId":545,"name":"Ciseaux","muscle":"abdos","equipment":"none","desc":"Les ciseaux sont un exercice abdominal qui renforce le transverse de l'abdomen, ce qui aide à aplatir le ventre et à renforcer toute la sangle abdominale. Les ciseaux ne sont pas seulement un mouvement de renforcement du tronc, c'est aussi un excellent étirement pour vos ischio-jambiers et votre bas du dos. Tout le monde cherche de nouvelles façons de travailler le tronc, d'aplatir le ventre et d'améliorer la souplesse. Si vous apprenez à faire les ciseaux, vous obtiendrez tout cela réuni en un seul mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-512","wgerId":512,"name":"Rowing assis, prise serrée","muscle":"dos","equipment":"none","desc":"* Contractez les muscles * Mouvement contrôlé * Mouvement lent * Gardez le haut du corps droit * Ne vous penchez pas en arrière * Tirez vers la poitrine","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/512/b938437e-ff00-4679-9036-acb41bb28bbd.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-493","wgerId":493,"name":"Reverse Bar Curl","muscle":"bras","equipment":"barre","desc":"Hold bar with reverse (or \"overhand\") grip, palms facing the floor.","tips":["Hold bar with reverse (or \"overhand\") grip, palms facing the floor."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"other"},{"id":"wger-490","wgerId":490,"name":"Renegade row","muscle":"dos","equipment":"elastiques","desc":"Mettez-vous en position de pompe en saisissant des haltères. Effectuez une pompe, puis tirez votre coude gauche vers le haut, en amenant l'haltère vers votre corps. Ramenez l'haltère à la position de départ. Effectuez une autre pompe, puis tirez avec l'autre bras pour compléter une répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-513","wgerId":513,"name":"Rowing à la T-bar","muscle":"dos","equipment":"none","desc":"L'exécution de cet exercice est très similaire au rowing penché classique, sauf qu'ici la barre est fixée. Saisissez la barre avec une prise large (légèrement plus large que la largeur des épaules) et penchez-vous en avant. Le haut de votre corps n'est pas tout à fait parallèle au sol, mais forme un léger angle. La poitrine est sortie pendant tout l'exercice. Tirez maintenant la barre par un mouvement rapide vers votre nombril, pas plus haut. Redescendez lentement à la position initiale. Ne balancez pas votre corps et gardez vos bras près du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/106/T-bar-row-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-549","wgerId":549,"name":"Extension des triceps assis","muscle":"bras","equipment":"barre","desc":"Asseyez-vous sur un banc (de préférence avec un dossier). Saisissez fermement un haltère à deux mains et tenez-le bras tendus au-dessus de votre tête. Les paumes tournées vers le haut et en soutenant le poids de l'haltère, abaissez lentement le poids derrière votre tête.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-508","wgerId":508,"name":"Rowing","muscle":"dos","equipment":"barre","desc":"En musculation, le rowing (souvent précédé d'un adjectif, par exemple le rowing assis) est un exercice dont le but est de renforcer les muscles qui ramènent les bras vers le corps (le grand dorsal), ainsi que ceux qui rétractent les omoplates (les trapèzes et les rhomboïdes) et ceux qui soutiennent la colonne vertébrale (les érecteurs du rachis). Réalisé sur un rameur, le rowing sollicite également les muscles qui étendent et soutiennent les jambes (les quadriceps et les muscles de la cuisse). Dans tous les cas, les abdominaux et les muscles du bas du dos doivent être sollicités afin de soutenir le corps et de prévenir les blessures du dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-510","wgerId":510,"name":"Rowing, Lying on Bench","muscle":"dos","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-501","wgerId":501,"name":"Ring Dips","muscle":"bras","equipment":"none","desc":"Dips peformed on gymnastic rings.","tips":["Dips peformed on gymnastic rings."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"other"},{"id":"wger-543","wgerId":543,"name":"Shoulder Press, on Machine","muscle":"epaules","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/53/Shoulder-press-machine-2.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-498","wgerId":498,"name":"Reverse Grip Bench Press","muscle":"pectoraux","equipment":"barre","desc":"Upper chest focuses exercise that also works triceps","tips":["Upper chest focuses exercise that also works triceps"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-538","wgerId":538,"name":"Incline Bench Press - Barbell","muscle":"pectoraux","equipment":"barre","desc":"To do slowly, tempo is 4010","tips":["To do slowly, tempo is 4010"],"image":"https://wger.de/media/exercise-images/41/Incline-bench-press-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"other"},{"id":"wger-607","wgerId":607,"name":"Relevés de buste croisés","muscle":"abdos","equipment":"none","desc":"Allongez-vous sur le dos, jambes tendues et bras le long du corps, en gardant les coudes pliés à 90 degrés. En vous redressant, faites pivoter le haut du corps vers la droite et amenez votre genou gauche vers votre coude droit pendant que vous ramenez votre bras gauche vers l'arrière. Redescendez votre corps à la position de départ, et répétez vers la droite. Cela fait 1 répétition.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-569","wgerId":569,"name":"Développé épaules à la multipresse","muscle":"epaules","equipment":"none","desc":"L'exercice est fondamentalement le même qu'avec une barre libre : Asseyez-vous sur un banc, le dossier doit être presque vertical. Saisissez une barre avec une prise à largeur d'épaules et amenez-la à hauteur de poitrine. Poussez le poids vers le haut, mais ne tendez pas complètement les bras. Redescendez lentement et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-591","wgerId":591,"name":"Relevés de buste","muscle":"abdos","equipment":"none","desc":"Asseyez-vous sur un tapis, les mollets reposant sur un banc, les genoux formant un angle droit. Tenez vos mains derrière la nuque. Montez maintenant par un mouvement d'enroulement du dos, vous devriez sentir comment les vertèbres se décollent une à une du tapis. Au point le plus haut, contractez vos abdominaux autant que possible et maintenez 2 secondes. Redescendez maintenant en déroulant le dos.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-567","wgerId":567,"name":"Développé épaules, haltères","muscle":"epaules","equipment":"elastiques","desc":"Asseyez-vous sur un banc, le dossier doit être presque vertical. Prenez deux haltères et amenez-les à hauteur des épaules, les paumes et les coudes pointent vers l'avant pendant tout l'exercice. Poussez les poids vers le haut, au point le plus haut ils se rapprochent beaucoup mais sans se toucher. Redescendez lentement et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/123/dumbbell-shoulder-press-large-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-566","wgerId":566,"name":"Développé épaules, barre","muscle":"epaules","equipment":"barre","desc":"Asseyez-vous sur un banc, le dossier doit être presque vertical. Saisissez une barre avec une prise à largeur d'épaules et amenez-la à hauteur de poitrine. Poussez le poids vers le haut, mais ne tendez pas complètement les bras. Redescendez lentement et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/119/seated-barbell-shoulder-press-large-1.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-584","wgerId":584,"name":"Curl au pupitre à un bras","muscle":"bras","equipment":"elastiques","desc":"Asseyez-vous sur le banc Larry Scott et effectuez un curl biceps avec un haltère dans une main. Votre autre main peut rester au repos, ou se placer sous le coude de votre bras qui travaille.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-590","wgerId":590,"name":"Extensions des mollets assis","muscle":"jambes","equipment":"none","desc":"Asseyez-vous sur un banc pour les extensions des mollets et vérifiez que les pieds sont à moitié dans le vide et que vous pouvez complètement étirer les muscles des mollets vers le bas. Montez sur la pointe des pieds en allant aussi haut que possible. Au point le plus haut, marquez une courte pause de 1 ou 2 secondes, puis redescendez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-583","wgerId":583,"name":"Pompes d'un côté à l'autre","muscle":"epaules","equipment":"none","desc":"- commencez en position de pompe - déplacez le poids du corps vers le côté droit, et effectuez une pompe avec la poitrine au-dessus de la main droite - revenez à la position centrée - à la 2e répétition, penchez-vous vers le côté gauche","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-598","wgerId":598,"name":"Développé couché prise serrée à la machine Smith","muscle":"bras","equipment":"none","desc":"Effectuez un développé couché classique sur la machine Smith, mais placez vos mains sur la barre à environ la largeur des épaules, et gardez vos coudes près du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-576","wgerId":576,"name":"Side Crunch","muscle":"abdos","equipment":"none","desc":"Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.","tips":["Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus."],"image":"https://wger.de/media/exercise-images/176/Cross-body-crunch-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-571","wgerId":571,"name":"Shrugs à la barre","muscle":"epaules","equipment":"barre","desc":"Prenez une barre et tenez-vous debout, le corps droit, les bras pendant librement devant vous. Depuis cette position, levez les épaules aussi haut que possible, mais sans plier les bras pendant le mouvement. Au point le plus haut, marquez une courte pause de 1 ou 2 secondes avant de redescendre lentement à la position initiale. Lorsque vous vous entraînez avec un poids plus lourd, veillez à toujours effectuer le mouvement complet !","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/150/Barbell-shrugs-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-575","wgerId":575,"name":"Shrugs on Multipress","muscle":"epaules","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-572","wgerId":572,"name":"Shrugs aux haltères","muscle":"epaules","equipment":"elastiques","desc":"Tenez-vous debout, le corps droit, les mains pendant librement sur les côtés et tenant chacune un haltère. Depuis cette position, levez les épaules aussi haut que possible, mais sans plier les bras pendant le mouvement. Au point le plus haut, marquez une courte pause de 1 ou 2 secondes avant de redescendre lentement à la position initiale. Lorsque vous vous entraînez avec un poids plus lourd, veillez à toujours effectuer le mouvement complet !","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/151/Dumbbell-shrugs-2.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-570","wgerId":570,"name":"Haussement d'épaules","muscle":"dos","equipment":"none","desc":"The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/570/68b4a33f-40f1-4dda-b56c-a2e20ed13903.jpg.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-580","wgerId":580,"name":"Planche latérale gauche","muscle":"abdos","equipment":"none","desc":"1. Allongez-vous sur le côté, le coude inférieur à angle droit, le bras dépassant 2. Soulevez votre bassin du sol en soulevant votre épaule inférieure, en gardant l'avant-bras sur le sol ; votre tête, votre bassin et vos pieds doivent être en ligne droite 3. Maintenez cette position","tips":["Allongez-vous sur le côté, le coude inférieur à angle droit, le bras dépassant","Maintenez cette position"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-632","wgerId":632,"name":"Squats sumo","muscle":"fessiers","equipment":"none","desc":"Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder. While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting). Lower yourself until your quadriceps and hamstrings are parallel to the floor. Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-616","wgerId":616,"name":"Poussées de squat","muscle":"fessiers","equipment":"none","desc":"The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-627","wgerId":627,"name":"Stiff-legged Deadlifts","muscle":"jambes","equipment":"barre","desc":"* Keep legs straight * Keep back straight","tips":["* Keep legs straight * Keep back straight"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-622","wgerId":622,"name":"Extension des mollets debout","muscle":"jambes","equipment":"none","desc":"Installez-vous sur la machine à mollets ; vous devez pouvoir abaisser complètement vos mollets. Tenez-vous bien droit, ne creusez pas le dos et ne pliez pas les jambes. Montez le plus haut possible. Marquez une courte pause de 1 à 2 secondes, puis redescendez lentement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/622/9a429bd0-afd3-4ad0-8043-e9beec901c81.jpeg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-614","wgerId":614,"name":"Squat Jumps","muscle":"jambes","equipment":"none","desc":"Jump wide, then close","tips":["Jump wide, then close"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-615","wgerId":615,"name":"Accroupi","muscle":"jambes","equipment":"barre","desc":"1. Debout, les pieds écartés à la largeur des épaules 2. Déplacez les hanches vers l'arrière et pliez les genoux et les hanches pour abaisser le torse. 3. Répétez","tips":["Debout, les pieds écartés à la largeur des épaules","Déplacez les hanches vers l'arrière et pliez les genoux et les hanches pour abaisser le torse"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-711","wgerId":711,"name":"Wall Handstand","muscle":"jambes","equipment":"none","desc":"Handstand against a wall for support (chest facing wall).","tips":["Handstand against a wall for support (chest facing wall)."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"other"},{"id":"wger-684","wgerId":684,"name":"Tirage vertical en supination","muscle":"dos","equipment":"none","desc":"Saisissez la barre de tirage, les paumes orientées vers vous et les mains plus rapprochées que la largeur des épaules. Penchez-vous légèrement en arrière et gardez le dos droit. Tirez la barre vers votre poitrine en rapprochant légèrement les épaules en fin de mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-694","wgerId":694,"name":"Tirage menton avec haltères","muscle":"epaules","equipment":"elastiques","desc":"Tenez un haltère dans chaque main devant votre corps. Gardez vos paumes tournées vers votre corps. Levez vos mains tout droit jusqu'à ce qu'elles soient sous votre menton, puis baissez-les. Répétez l'exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/694/119e6823-6960-4341-a9e1-aaf78d7fb57c.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-630","wgerId":630,"name":"Soulevé de terre sumo","muscle":"jambes","equipment":"none","desc":"1. Commencez avec une barre chargée au sol. Approchez-vous de la barre de sorte qu'elle coupe le milieu de vos pieds. Les pieds doivent être très écartés, près des colliers de serrage. Penchez-vous au niveau des hanches pour saisir la barre. Les bras doivent se trouver directement sous les épaules, à l'intérieur des jambes, et vous pouvez utiliser une prise pronation, une prise mixte ou une prise crochet. Relâchez les épaules, ce qui a pour effet d'allonger vos bras. 2. Inspirez, puis abaissez vos hanches, le regard dirigé vers l'avant et la poitrine relevée. Poussez à travers le sol en écartant les pieds, le poids réparti sur la moitié arriè","tips":["Commencez avec une barre chargée au sol","Inspirez, puis abaissez vos hanches, le regard dirigé vers l'avant et la poitrine relevée","Ramenez le poids au sol en pliant les hanches et en contrôlant la charge pendant la descente"],"image":"https://wger.de/media/exercise-images/630/b0f0c7d8-5878-4d9e-b820-21acc013741d.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-371","wgerId":371,"name":"Presse à cuisses","muscle":"jambes","equipment":"none","desc":"La presse à cuisses est un exercice de musculation dans lequel on pousse un poids ou une résistance loin de soi à l'aide des jambes.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/371/d2136f96-3a43-4d4c-9944-1919c4ca1ce1.webp.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-465","wgerId":465,"name":"Curls au pupitre","muscle":"bras","equipment":"barre","desc":"Placez la barre EZ sur les supports devant le banc Larry Scott. Penchez-vous au-dessus du banc et saisissez la barre EZ, paumes vers le haut. Asseyez-vous sur le siège du banc Larry Scott de sorte que vos bras reposent sur le coussin et que votre poitrine soit appuyée contre le coussin. Abaissez le poids jusqu'à ce que vos coudes soient déployés et vos bras tendus. Remontez le poids jusqu'au point de départ en contractant les biceps. Répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/193/Preacher-curl-3-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-621","wgerId":621,"name":"Curl biceps debout","muscle":"bras","equipment":"elastiques","desc":"Tenez-vous debout en tenant des haltères, les mains écartées de la largeur des épaules. Orientez l'avant-bras vers le haut et gardez le bras immobile tout en remontant chaque haltère jusqu'à votre épaule.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-418","wgerId":418,"name":"Développé militaire à la barre EZ","muscle":"epaules","equipment":"barre","desc":"Sur une barre EZ, placez vos mains à l'extérieur de chaque courbure et tenez-vous debout, les bras tendus vers le bas, paumes tournées vers vos jambes. Tirez la barre vers votre poitrine (en pliant les bras au niveau des coudes), puis poussez la barre au-dessus de votre tête (bras aussi tendus que possible). Ramenez la barre vers votre poitrine en abaissant vos bras par les coudes. Ramenez la barre à sa position d'origine (debout, les bras tendus vers le bas, paumes tournées vers vos jambes).","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/418/fa2a2207-43cb-4dc0-bc2a-039e32544790.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-507","wgerId":507,"name":"Romanian Deadlift","muscle":"jambes","equipment":"barre","desc":"DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo","tips":["DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-312","wgerId":312,"name":"Planche inclinée avec touche du sol alternée","muscle":"abdos","equipment":"none","desc":"Réalisez la planche jambes surélevées, les pieds sur un gym ball. Une fois stabilisé, déplacez lentement un pied sur le côté pour le sortir de la balle, faites-le toucher le sol, puis revenez à la position de départ. Alternez avec l'autre pied. C'est un exercice de gainage.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-529","wgerId":529,"name":"Run - Interval Training","muscle":"jambes","equipment":"none","desc":"Run and do some interval trainings such as hill repat, fartlek,..","tips":["Run and do some interval trainings such as hill repat, fartlek,.."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"other"},{"id":"wger-562","wgerId":562,"name":"Shotgun row","muscle":"dos","equipment":"none","desc":"1. Fixez une poignée simple à une poulie basse. 2. Après avoir choisi le poids approprié, tenez-vous reculé de quelques dizaines de centimètres avec une position en fente large. Votre bras doit être tendu et votre épaule projetée vers l'avant. Ce sera votre position de départ. 3. Effectuez le mouvement en rétractant l'épaule et en fléchissant le coude. Pendant que vous tirez, faites une supination du poignet, en tournant la paume vers le haut au fur et à mesure. 4. Après une brève pause, revenez à la position de départ.","tips":["Fixez une poignée simple à une poulie basse","Effectuez le mouvement en rétractant l'épaule et en fléchissant le coude","Après une brève pause, revenez à la position de départ"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-628","wgerId":628,"name":"Tirage bras tendus (poignée barre)","muscle":"dos","equipment":"none","desc":"Utilisez la poignée barre droite sur une poulie haute. Saisissez les deux extrémités de la barre, les paumes orientées vers le bas et les bras tendus devant vous. Tirez les mains vers le bas en direction de vos hanches, tout en gardant les bras tendus, puis relevez-les jusqu'à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-629","wgerId":629,"name":"Tirage bras tendus (poignée corde)","muscle":"dos","equipment":"none","desc":"Utilisez la poignée corde sur une poulie haute. Saisissez les deux extrémités de la corde, les bras tendus devant vous. Tirez les mains vers le bas en direction de vos hanches, tout en gardant les bras tendus, puis relevez-les jusqu'à la position de départ.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"fr"},{"id":"wger-660","wgerId":660,"name":"Extensions des triceps à la poulie avec barre","muscle":"bras","equipment":"none","desc":"Saisissez la barre, tenez-vous debout, les pieds écartés de la largeur des épaules, gardez le dos droit et penchez-vous légèrement vers l'avant. Poussez la barre vers le bas en veillant à ce que les coudes ne bougent pas pendant l'exercice. Sans pause, revenez à la position initiale.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-695","wgerId":695,"name":"V-Bar Pulldown","muscle":"dos","equipment":"none","desc":"Pulldowns using close grip v-bar.","tips":["Pulldowns using close grip v-bar."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-702","wgerId":702,"name":"Lever du mollet gauche","muscle":"jambes","equipment":"none","desc":"1. Tenez-vous debout sur le sol ou sur le bord d'une marche pour augmenter l'amplitude des mouvements. Levez un pied en plaçant la partie supérieure sur votre mollet 2. Soulevez vos talons jusqu'à ce que vous soyez debout sur les orteils 3. Restez dans cette position pendant trois secondes, puis abaissez votre pied sans toucher le sol avec votre talon.","tips":["Tenez-vous debout sur le sol ou sur le bord d'une marche pour augmenter l'amplitude des mouvements","Soulevez vos talons jusqu'à ce que vous soyez debout sur les orteils","Restez dans cette position pendant trois secondes, puis abaissez votre pied sans toucher le sol avec votre talon"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Calves","source":"wger","descLang":"fr"},{"id":"wger-693","wgerId":693,"name":"Tirage menton, barre EZ","muscle":"epaules","equipment":"barre","desc":"Tenez-vous bien droit, les pieds écartés de la largeur des épaules. Tenez la barre EZ en prise pronation contre vos cuisses, les bras tendus. Soulevez la barre près du corps jusqu'à votre menton. Les coudes pointent vers l'extérieur de sorte qu'au point le plus haut ils forment un V. Marquez ici une courte pause avant de redescendre lentement et de répéter le mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/693/05c91bd2-7814-40b6-b2d1-51ae942b8321.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-713","wgerId":713,"name":"Wall Pushup","muscle":"epaules","equipment":"none","desc":"Pushup against a wall","tips":["Pushup against a wall"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"other"},{"id":"wger-691","wgerId":691,"name":"Tirage menton, à la Smith machine","muscle":"epaules","equipment":"none","desc":"Les mouvements sont fondamentalement les mêmes qu'avec une barre EZ, mais vous utilisez la barre de la Smith machine : Tenez-vous bien droit, les pieds écartés de la largeur des épaules. Tenez la barre en prise pronation contre vos cuisses, les bras tendus. Soulevez la barre près du corps jusqu'à votre menton. Les coudes pointent vers l'extérieur de sorte qu'au point le plus haut ils forment un V. Marquez ici une courte pause avant de redescendre lentement et de répéter le mouvement.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/691/297d4ce1-7e9e-4adb-8f5c-7d54054be885.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Shoulders","source":"wger","descLang":"fr"},{"id":"wger-1940","wgerId":1940,"name":"Diaphragmatic Breathing","muscle":"jambes","equipment":"none","desc":"Belly breathing. Hand on chest stays still, hand on belly rises. 8-10 slow breaths.","tips":["Belly breathing. Hand on chest stays still, hand on belly rises. 8-10 slow breaths."],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"other"},{"id":"wger-202","wgerId":202,"name":"Curl biceps avec haltère","muscle":"bras","equipment":"elastiques","desc":"Cet exercice consiste à tenir un haltère dans une main et à le lever (ou le \"curler\") vers l'épaule tout en gardant le haut du bras immobile. Il cible principalement le muscle biceps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-530","wgerId":530,"name":"Run - Treadmill","muscle":"jambes","equipment":"none","desc":"Run on a treadmill","tips":["Run on a treadmill"],"image":"","defaultMode":"time","defaultValue":30,"category":"Cardio","source":"wger","descLang":"other"},{"id":"wger-537","wgerId":537,"name":"Développé incliné - haltères","muscle":"pectoraux","equipment":"elastiques","desc":"Le développé incliné avec haltères est un mélange du développé couché avec haltères et du développé épaules ; les deltoïdes antérieurs et la partie supérieure des pectoraux sont sollicités dans cet exercice.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/16/Incline-press-1.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-718","wgerId":718,"name":"Assis dos au mur","muscle":"jambes","equipment":"none","desc":"1. Appuyez-vous contre le mur, en regardant vers l'avant, les pieds fermement plantés au sol, écartés de la largeur des épaules et à une distance d'environ 60 cm du mur. 2. Glissez le long du mur, en gardant le dos appuyé contre lui, jusqu'à ce que les jambes forment un angle droit. Les genoux doivent être directement au-dessus des chevilles.La douleur au quadriceps est normale, arrêtez si vous ressentez une douleur au genou ou à la rotule","tips":["Glissez le long du mur, en gardant le dos appuyé contre lui, jusqu'à ce que les jambes forment un angle droit"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1567","wgerId":1567,"name":"Curl marteau alterné avec haltères","muscle":"bras","equipment":"elastiques","desc":"Tenez-vous debout, les genoux légèrement fléchis et le dos droit. Tenez un haltère dans chaque main, en prise neutre, les bras le long du corps.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1567/0a8c155c-a48e-47e8-9df3-e39f025c6cad.png.400x400_q85.png","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1847","wgerId":1847,"name":"L-sit jambes écartées","muscle":"abdos","equipment":"none","desc":"Les jambes en position de selle assise, poussez votre corps vers le haut pour décoller du sol. Vos jambes doivent être horizontales et pointer droit vers l'extérieur. Vos bras doivent se trouver entre vos jambes. Maintenez la position de manière isométrique aussi longtemps que nécessaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1852","wgerId":1852,"name":"L-sit","muscle":"dos","equipment":"none","desc":"Asseyez-vous au sol, les jambes serrées et les bras le long du corps. Poussez sur vos mains pour décoller votre corps du sol, en conservant la même position assise de sorte que vos jambes soient tendues et que vos pieds ne touchent pas le sol. Maintenez la position aussi longtemps que nécessaire.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1853","wgerId":1853,"name":"L-Sit (Foot Supported)","muscle":"dos","equipment":"none","desc":"As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs.","tips":["As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"other"},{"id":"wger-1954","wgerId":1954,"name":"Roll-overs into V-sits","muscle":"jambes","equipment":"none","desc":"Roll-overs into V-sits Part of: Limber 11 Source: Joe DeFranco Prescription: 10 reps Type: dynamic","tips":["Roll-overs into V-sits Part of: Limber 11 Source: Joe DeFranco Prescription: 10 reps Type: dynamic"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-441","wgerId":441,"name":"Overhead squat","muscle":"fessiers","equipment":"none","desc":"La barre est maintenue au-dessus de la tête en prise large d'arraché ; il est toutefois également possible d'utiliser une prise plus serrée si l'équilibre le permet.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-674","wgerId":674,"name":"Rowing with TRX band","muscle":"dos","equipment":"none","desc":"Rowing with resistance bands - Bodyweight Exercise","tips":["Rowing with resistance bands - Bodyweight Exercise"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Back","source":"wger","descLang":"other"},{"id":"wger-1960","wgerId":1960,"name":"Étirement des fléchisseurs de la hanche, pied arrière surélevé","muscle":"jambes","equipment":"none","desc":"Étirement des fléchisseurs de la hanche, pied arrière surélevé Fait partie de : Limber 11 Source : Joe DeFranco Prescription : 5 à 10 répétitions de chaque côté Type : dynamique Comprend un mouvement dynamique ainsi qu'un maintien de 3 s.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-173","wgerId":173,"name":"Crunchs à la poulie","muscle":"abdos","equipment":"none","desc":"Prenez le câble dans vos mains et tenez-le près de vos tempes. Mettez-vous à genoux, gardez le haut du corps droit et penchez-vous vers l'avant. Descendez d'un mouvement rapide en enroulant le dos (vos coudes pointent vers vos genoux). Une fois en bas, revenez lentement à la position initiale.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-659","wgerId":659,"name":"Extensions des triceps à la poulie","muscle":"bras","equipment":"none","desc":"Saisissez le câble, tenez-vous debout, les pieds écartés de la largeur des épaules, gardez le dos droit et penchez-vous légèrement vers l'avant. Poussez la barre vers le bas en veillant à ce que les coudes ne bougent pas pendant l'exercice. Tournez les mains vers l'extérieur tout à la fin, puis revenez à la position initiale sans pause.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/659/a60452f1-e2ea-43fe-baa6-c1a2208d060c.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Arms","source":"wger","descLang":"fr"},{"id":"wger-1084","wgerId":1084,"name":"Développé au sol avec haltères","muscle":"pectoraux","equipment":"elastiques","desc":"Prenez vos haltères et allongez-vous à plat sur le dos, les genoux fléchis et les pieds bien à plat au sol (utilisez un banc si vous en avez un). Poussez les poids vers le haut en verrouillant les coudes (A). Abaissez-les lentement jusqu'à ce que le haut de vos bras repose au sol (B), près du corps. Marquez une pause ici avant de pousser à nouveau vers le haut de manière explosive. Contractez fortement les pectoraux et répétez.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1084/91dd5a95-1c45-46f2-a074-de41b6ad599b.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1188","wgerId":1188,"name":"Flexion latérale","muscle":"abdos","equipment":"elastiques","desc":"Avec un poids dans une main, tendez ce bras vers le bas et pliez l'autre bras en posant la main sur votre tête. Déplacez maintenant la main tenant le poids en effectuant une rotation du buste de haut en bas.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1188/43e714e4-b736-4f3a-8ab4-97821fdff86a.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Abs","source":"wger","descLang":"fr"},{"id":"wger-1801","wgerId":1801,"name":"Squat complet à la barre","muscle":"jambes","equipment":"barre","desc":"* Le squat complet à la barre est un **exercice polyarticulaire** qui **sollicite plusieurs groupes musculaires** du bas du corps, notamment les quadriceps, les ischio-jambiers et les fessiers. * Une bonne technique est essentielle pour maximiser les résultats et prévenir les blessures pendant le squat complet à la barre. Cela inclut le maintien d'un écartement des pieds à la largeur des épaules, la création d'une tension dans tout le corps, le contrôle de la descente et le respect d'une profondeur et d'un placement des genoux corrects. * Des exercices complémentaires comme le front squat, le goblet squat, le split squat et le split squat bul","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"https://wger.de/media/exercise-images/1801/60043328-1cfb-4289-9865-aaf64d5aaa28.jpg.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"fr"},{"id":"wger-1551","wgerId":1551,"name":"Pompe","muscle":"pectoraux","equipment":"none","desc":"La pompe est un exercice fondamental au poids du corps qui sollicite les pectoraux, les bras et les épaules tout en mobilisant la sangle abdominale pour la stabilité. Elle ne nécessite aucun matériel et est excellente pour développer la force du haut du corps. Instructions : 1. Commencez en position de planche, les mains placées légèrement plus écartées que la largeur des épaules, les pieds joints et le corps aligné de la tête aux talons. 2. Engagez votre sangle abdominale et abaissez votre corps en pliant les coudes, en les gardant près du corps ou légèrement écartés vers l'extérieur. 3. Descendez jusqu'à ce que votre poitrine touche presque","tips":["Descendez jusqu'à ce que votre poitrine touche presque le sol, tout en maintenant une colonne vertébrale neutre","Poussez sur vos paumes pour revenir à la position de départ en tendant complètement les bras"],"image":"https://wger.de/media/exercise-images/1551/a6a9e561-3965-45c6-9f2b-ee671e1a3a45.png.400x400_q85.jpg","defaultMode":"reps","defaultValue":12,"category":"Chest","source":"wger","descLang":"fr"},{"id":"wger-1688","wgerId":1688,"name":"Kickstand RDL","muscle":"jambes","equipment":"barre","desc":"use non-working leg's toes to help with balance and perform an RDL.","tips":["use non-working leg's toes to help with balance and perform an RDL."],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"},{"id":"wger-71","wgerId":71,"name":"Single Leg Extension","muscle":"jambes","equipment":"none","desc":"Consulte la description complète sur wger.de.","tips":["Contrôle le mouvement","Respire régulièrement","Adapte la charge"],"image":"","defaultMode":"reps","defaultValue":12,"category":"Legs","source":"wger","descLang":"other"}];
